 if(!inTable)issues.push('索引越过ST表；短表的省略TPH、ST=0或实现自定选择需查设备，不能自动取余');
 if(mode===0)issues.push('No ST模式所有ST为0，不从该索引选择ST');if(ignored)issues.push('Interrupt Vector模式中超出已启用向量范围的条目被忽略');
