function packetFlitRegion(byte){return byte<236?'TLP':byte<242?'DLP':byte<250?'CRC':'ECC';}
function packetFlitByteText(byte){if(!Number.isInteger(byte)||byte<0||byte>255)return '请选择0～255的字节。';const region=packetFlitRegion(byte),ranges={TLP:'byte0～235 · 236 B / 1888 bit；可含多个TLP、NOP或跨Flit片段，不等于应用净数据',DLP:'byte236～241 · 6 B / 48 bit；链路控制/序号及32-bit控制负载',CRC:'byte242～249 · 8 B / 64 bit；Flit CRC，不是NFM的逐TLP LCRC',ECC:'byte250～255 · 6 B / 48 bit；三组ECC各2 byte，归组不简单沿用i mod3'};return `Flit byte ${byte}，逻辑线性bit偏移 ${byte*8}～${byte*8+7}（偏移标尺，不是串行位序）→ ${region}区。${ranges[region]}。`;}
function packetFlitMap(){return `<figure class="packet-figure packet-flit"><figcaption><b>FLIT整体结构 · 256 B = 2048 bit</b><span>Base6.0 / 7.0 · 点击任意byte查看区域</span></figcaption><p class="ft-pack-gateway">236 B里面还分包头、扩展头、数据和尾部。<a href="#feature/13/detail/flit-tlp-internal-anatomy">展开TLP区域内部结构与跨FLIT示意 →</a></p><div class="packet-flit-bar" aria-label="FLIT各区长度比例">${[['TLP',236],['DLP',6],['CRC',8],['ECC',6]].map(([k,n])=>`<span class="region-${k}" style="flex:${n}" title="${k} ${n} B"></span>`).join('')}</div><div class="packet-parts">${[['TLP','236 B / 1888 bit · byte0～235'],['DLP','6 B / 48 bit · byte236～241'],['CRC','8 B / 64 bit · byte242～249'],['ECC','6 B / 48 bit · byte250～255']].map(([k,n])=>`<div><b>${k}</b><span>${n}</span></div>`).join('')}</div><p class="packet-reading">下面每格1 byte（8 bit），按逻辑byte偏移从0到255排列。它是整个Link的一份Flit，不是每条lane各256 B；格子的数字是偏移，不是数据值。</p><div class="packet-scroll" tabindex="0" role="region" aria-label="FLIT 256字节图"><div class="packet-flit-grid">${Array.from({length:256},(_,i)=>`<button type="button" class="region-${packetFlitRegion(i)}" data-flit-map-byte="${i}" aria-label="Flit byte ${i}，${packetFlitRegion(i)}区">${i}<small>${packetFlitRegion(i)}</small></button>`).join('')}</div></div><p class="packet-field-help" data-flit-map-help role="status" aria-live="polite">${esc(packetFlitByteText(236))}</p><p class="packet-note">不含SKP等Ordered Set和线路编码开销；TLP在236-byte区域内的切分随内容而变，不能把一行/一个Flit当成一个固定大小TLP。更细的DLP位图在本页对应块中，ECC逻辑lane/组映射可用原有逐字节查询。</p></figure>`;}
function renderPacketGallery(){const entries=DB.features.flatMap(f=>(f.details||[]).filter(d=>d.packetLayouts?.length||d.packetByteLayout||d.flitTlpPacking||d.fmTlpSizeQuery).map(d=>({f,d}))),q=$('#search').value.trim().toLowerCase(),shown=entries.filter(({f,d})=>!q||[f.name,d.title,JSON.stringify(d)].join(' ').toLowerCase().includes(q));$('#content').innerHTML=`<div class="hero"><div class="eyebrow">PACKET ATLAS / TLP · DLLP · FLIT</div><h1>包有多大，字段在哪里。</h1><p>先看完整组成，再逐bit定位。图中标明版本、模式和长度口径；从下方来源按钮打开自己的PDF对照。</p></div><nav class="detail-index" aria-label="包图目录">${shown.map(({f,d})=>`<a href="#packet-map-${f.id}-${esc(d.id)}" data-packet-jump="packet-map-${f.id}-${esc(d.id)}">${esc(d.title)}</a>`).join('')}</nav>${shown.map(({f,d})=>`<article class="list-row" id="packet-map-${f.id}-${esc(d.id)}"><h2>${esc(d.title)}</h2><p><a href="${detailHref(f,d,0)}">回到功能正文与规则 →</a></p>${d.packetByteLayout?packetFlitMap():''}${d.flitTlpPacking?renderFlitTlpPacking():''}${d.fmTlpSizeQuery?fmTlpSizeExplorer():''}${renderPacketLayouts(f,d)}<div class="detail-sources">${detailSources(f,d)}</div></article>`).join('')}${shown.length?'':'<div class="empty">当前没有匹配的包图，可搜索TLP、DLLP、FLIT、Completion或InitFC。</div>'}`;document.title='包结构图 · PCIe Study';}
document.addEventListener('click',e=>{const byte=e.target.closest?.('[data-flit-map-byte]');if(byte){const figure=byte.closest('.packet-flit');figure.querySelector('[data-flit-map-help]').textContent=packetFlitByteText(Number(byte.dataset.flitMapByte));for(const b of figure.querySelectorAll('[data-flit-map-byte]'))b.classList.toggle('is-byte-selected',b===byte);}const jump=e.target.closest?.('[data-packet-jump]');if(jump){e.preventDefault();document.getElementById(jump.dataset.packetJump)?.scrollIntoView({behavior:'smooth',block:'start'});}});

const FM_TLP_COMMON_TYPES={mrd32:{code:3,base:3,data:false,read:true},mrd64:{code:32,base:4,data:false,read:true},mwr32:{code:64,base:3,data:true},mwr64:{code:96,base:4,data:true},cpl:{code:10,base:3,data:false},cpld:{code:74,base:3,data:true}};
function fmTlpSize(type,lengthRaw,ohc,ts){const t=FM_TLP_COMMON_TYPES[type];if(!t||![lengthRaw,ohc,ts].every(Number.isInteger)||lengthRaw<0||lengthRaw>1023||ohc<0||ohc>31||ts<0||ts>7)return null;const decoded=lengthRaw===0?1024:lengthRaw,e=[0,1,2,4][ohc>>3],ohcDW=(ohc&1)+((ohc>>1)&1)+((ohc>>2)&1)+e,trailerDW=[0,1,1,2,2,3,4,5][ts],payloadDW=t.data?decoded:0,totalDW=t.base+ohcDW+payloadDW+trailerDW;return {type,code:t.code,baseDW:t.base,ohcDW,trailerDW,payloadDW,requestBytes:t.read?decoded*4:null,totalBytes:totalDW*4,totalBits:totalDW*32};}
function fmTlpSizeText(type,l,o,t){const r=fmTlpSize(type,l,o,t);if(!r)return '请输入已列类型及整数范围：Raw Length0～1023、OHC0～31、TS0～7。';return `FM Type=0x${r.code.toString(16).padStart(2,'0')}：Base ${r.baseDW*4} B + OHC ${r.ohcDW*4} B + 本包Payload ${r.payloadDW*4} B + Trailer ${r.trailerDW*4} B = ${r.totalBytes} B / ${r.totalBits} bit。${r.requestBytes!==null?`请求读取 ${r.requestBytes} B，但请求Payload为0 B。`:''} 未计Local Prefix；这是格式长度计算，不验证MPS/MRRS、目标能力、必需OHC、IDE、状态、地址或组合合法性。`;}
function fmTlpSizeExplorer(){return `<div class="note flit-controls"><label>普通FM Type <select id="ftsize-type">${Object.keys(FM_TLP_COMMON_TYPES).map(k=>`<option value="${k}" ${k==='mwr64'?'selected':''}>${k.toUpperCase()}</option>`).join('')}</select></label><label>Raw Length（十进制） <input id="ftsize-length" type="number" min="0" max="1023" value="32"></label><label>OHC位图（十进制0～31） <input id="ftsize-ohc" type="number" min="0" max="31" value="0"></label><label>TS编码（十进制0～7） <input id="ftsize-ts" type="number" min="0" max="7" value="0"></label><p id="ftsize-result" aria-live="polite">${esc(fmTlpSizeText('mwr64',32,0,0))}</p></div>`;}
function fmTlpPackingModel(scenario){const sizes={single128:[128],two64:[64,64],cross256:[256]}[scenario];if(!sizes)return null;let stream=0;const pieces=[];sizes.forEach((n,i)=>{const name=String.fromCharCode(65+i),packetStart=stream;pieces.push({kind:'header',name,length:16,start:stream,packetStart});stream+=16;pieces.push({kind:'data',name,length:n,start:stream,packetStart});stream+=n;});const rows=[];
 for(let offset=0;offset<stream;offset+=236){const segments=[];for(const p of pieces){const begin=Math.max(offset,p.start),end=Math.min(offset+236,p.start+p.length);if(begin<end)segments.push({kind:p.kind,name:p.name,start:begin-offset,length:end-begin,packetOffset:begin-p.packetStart});}const used=Math.min(236,stream-offset);if(used<236)segments.push({kind:'nop',name:'NOP',start:used,length:236-used,packetOffset:null});for(const[k,start,length]of [['dlp',236,6],['crc',242,8],['ecc',250,6]])segments.push({kind:k,name:k.toUpperCase(),start,length,packetOffset:null});rows.push({index:rows.length,segments});}
 return {scenario,sizes,streamBytes:stream,rows};
}
function fmPackingLabel(s){return s.kind==='header'?'H_'+s.name:s.kind==='data'?'D_'+s.name:s.name;}
function fmPackingDescription(s){const region=`Flit byte${s.start}～${s.start+s.length-1}，${s.length} B / ${s.length*8} bit`;if(s.kind==='header'||s.kind==='data')return `${region}：TLP ${s.name}的${s.kind==='header'?'Header Base':'Data Payload'}，包内byte${s.packetOffset}～${s.packetOffset+s.length-1}。`;if(s.kind==='nop')return `${region}：${s.length/4}个1 DW NOP TLP，不是业务数据或任意填充。`;return `${region}：本FLIT自己的${s.name}，不属于TLP ${s.name==='DLP'?'内容':'Payload'}。`;}
function fmPackingBody(scenario){const m=fmTlpPackingModel(scenario);if(!m)return '';return `<div class="ft-pack-view" data-ft-pack-view="${esc(scenario)}"><p class="packet-reading">${m.sizes.map((n,i)=>`TLP ${String.fromCharCode(65+i)}：Header16 B + Payload${n} B = ${16+n} B（Length=${n/4} DW）`).join('；')}。图中H表示头，D表示数据；每个横条是一份完整256 B FLIT。</p>${m.rows.map(row=>`<section class="ft-pack-row"><h3>FLIT ${row.index}</h3><div class="packet-scroll" tabindex="0" role="region" aria-label="FLIT ${row.index}内部TLP装载"><div class="ft-pack-track">${row.segments.map((s,i)=>`<button type="button" class="ft-part-${s.kind}" style="flex:${s.length}" data-ft-pack-segment="${row.index}:${i}" title="${esc(fmPackingDescription(s))}">${esc(fmPackingLabel(s))}</button>`).join('')}</div></div><div class="ft-pack-key">${row.segments.map(s=>`<span class="ft-part-${s.kind}">${esc(fmPackingLabel(s))} · byte${s.start}～${s.start+s.length-1} · ${s.length} B${s.packetOffset!==null?' · TLP内'+s.packetOffset+'～'+(s.packetOffset+s.length-1):''}</span>`).join('')}</div></section>`).join('')}<p class="packet-field-help" data-ft-pack-help role="status" aria-live="polite">${esc(scenario==='cross256'?'第二个FLIT从TLP A的包内byte236继续，剩余36 B都是数据，不会重复发送TLP头。':'一个FLIT可包含多个TLP；每个TLP自己的Header仍占TLP区域，余下空闲位置以NOP TLP填充。')}</p><p class="packet-note">这是前提限定的示意，不是完整编码器：普通全BE MWr64，地址0x1000、Type60h、OHC=0、TS=0、无Prefix/IDE，适用MPS至少覆盖所选Payload。三个方案的每半FLIT非NOP计数均不超过4。点击横条查看片段范围。</p></div>`;}
function renderFlitTlpPacking(){return `<figure class="packet-figure"><figcaption><b>把236B展开：TLP自己的头和数据怎样装入FLIT</b><span>全Link的一份FLIT · byte不是每lane独占</span></figcaption><label class="packet-select-label">选择示意 <select data-ft-pack-select><option value="two64">两个64 B写Payload：两包共用一份FLIT</option><option value="single128">一个128 B写Payload：头+数据+NOP</option><option value="cross256">一个256 B写Payload：同一TLP跨两份FLIT</option></select></label><div data-ft-pack-body>${fmPackingBody('two64')}</div><p><a href="#feature/13/detail/fm-memory-tlp-bit-layout">继续展开Header每一bit →</a> · <a href="#feature/13/detail/fm-tlp-size-query">计算Base/OHC/Payload/Trailer长度 →</a></p></figure>`;}
document.addEventListener('input',e=>{if(!e.target.id?.startsWith('ftsize-'))return;const n=k=>{const v=$('#ftsize-'+k).value;return v.trim()===''?NaN:Number(v)};$('#ftsize-result').textContent=fmTlpSizeText($('#ftsize-type').value,n('length'),n('ohc'),n('ts'));});
document.addEventListener('change',e=>{if(!e.target.hasAttribute?.('data-ft-pack-select'))return;const figure=e.target.closest('.packet-figure');if(figure&&fmTlpPackingModel(e.target.value))figure.querySelector('[data-ft-pack-body]').innerHTML=fmPackingBody(e.target.value);});
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-ft-pack-segment]');if(!b)return;const view=b.closest('[data-ft-pack-view]'),m=fmTlpPackingModel(view.dataset.ftPackView),[r,i]=b.dataset.ftPackSegment.split(':').map(Number),s=m?.rows[r]?.segments[i];if(s)view.querySelector('[data-ft-pack-help]').textContent=fmPackingDescription(s);});

// Original learning calculators: no device access or platform resource allocation.
function sriovInteger(value,base,max){const s=String(value).trim().replace(base===16 ? /^0x/i : /^$/,'');if(!(base===16 ? /^[0-9a-f]+$/i : /^\d+$/).test(s))return null;const n=parseInt(s,base);return Number.isSafeInteger(n)&&n>=0&&n<=max?n:null;}
function sriovRidInfo(pfText,offsetText,strideText,countText,vText){
 const pf=sriovInteger(pfText,16,65535),offset=sriovInteger(offsetText,16,65535),stride=sriovInteger(strideText,16,65535),count=sriovInteger(countText,10,65535),v=sriovInteger(vText,10,65535);
 if([pf,offset,stride,count,v].includes(null))return {ok:false,text:'输入无效：PF RID、Offset、Stride用16bit hex；数量与VF序号用十进制0～65535。'};
 if(count===0)return {ok:true,empty:true,text:'NumVFs=0：没有VF，Offset/Stride不用；不生成末VF RID或总线窗口。'};
 if(offset===0||count>1&&stride===0)return {ok:false,text:'不合法：NumVFs>0时Offset须非0；NumVFs>1时Stride须非0。'};
 if(v<1||v>count)return {ok:false,text:'VF序号须在1～NumVFs内。本页VF从1计数。'};
 const first=pf+offset,last=first+(count-1)*stride,raw=first+(v-1)*stride,rid=raw%65536;
 if(last>65535)return {ok:false,rid,text:'出现16bit回绕：规范算术会舍弃进位，但回绕会违反VF Bus不得小于PF等布局约束；此处不提供可用资源分配。'};
 const hex=(n,w=4)=>n.toString(16).toUpperCase().padStart(w,'0'),bus=rid>>>8,func=rid&255;
 return {ok:true,first,last,rid,bus,func,busCount:(last>>>8)-(pf>>>8)+1,text:`VF${v} RID=${hex(rid)}h；ARI解释：Bus=${hex(bus,2)}h、Function=${hex(func,2)}h（${func}）。传统BDF显示：${hex(bus,2)}:${hex(func>>>3,2)}.${func&7}。首VF=${hex(first)}h；末VF=${hex(last)}h。含PF的Bus编号跨度=${(last>>>8)-(pf>>>8)+1}（${hex(pf>>>8,2)}h～${hex(last>>>8,2)}h）；这是所需编号范围，不代表每个Bus都有VF。所选VF在${bus===(pf>>>8)?'captured Bus：设备接收Type0配置请求':'其他Bus：设备接收Type1配置请求'}。还需核其他PF/VF冲突、ARI配置与桥窗口；Offset/Stride须为当前NumVFs/ARI配置下重读值。`};
}
function sriovBarInfo(baseText,sizeText,countText,vText,pageText,widthText){
 const hx=s=>{s=String(s).trim().replace(/^0x/i,'');return /^[0-9a-f]{1,16}$/i.test(s)?BigInt('0x'+s):null;};
 const base=hx(baseText),size=hx(sizeText),page=hx(pageText),count=sriovInteger(countText,10,65535),v=sriovInteger(vText,10,65535),width=String(widthText);
 if([base,size,page,count,v].includes(null)||!['32','64'].includes(width))return {ok:false,text:'输入无效：基址、单VF大小和页大小用最多16位hex；数量与VF序号用十进制；宽度选32或64。'};
 if(size===0n||page===0n||(size&(size-1n))!==0n||(page&(page-1n))!==0n||page<4096n||page>8796093022208n)return {ok:false,text:'非空BAR大小与页大小须是2的幂；页大小须在32bit页位图表示的4KiB～8TiB范围内。'};
 if(base%size!==0n||size%page!==0n)return {ok:false,text:'对齐失败：基址须按单VF BAR大小对齐；单VF大小须为System Page Size的整数倍。'};
 if(count===0)return {ok:true,empty:true,text:'NumVFs=0：总VF BAR窗口为空，不产生有效结束地址。'};
 if(v<1||v>count)return {ok:false,text:'VF序号须在1～NumVFs内。本页VF从1计数。'};
 const total=size*BigInt(count),end=base+total-1n,max=(1n<<BigInt(width))-1n,start=base+BigInt(v-1)*size,vend=start+size-1n;
 if(end>max)return {ok:false,text:`地址溢出：此VF窗口超出所选${width}bit BAR地址范围。`};
 const h=n=>n.toString(16).toUpperCase()+'h';
 return {ok:true,total,end,start,vend,text:`总窗口：[${h(base)}, ${h(end)}]，共${total.toString()}字节。VF${v}：[${h(start)}, ${h(vend)}]，每VF ${size.toString()}字节。地址单位为字节；RID Stride不参与计算。所填页大小是否受PF支持、桥/CPU资源与其他BAR冲突仍需另核。实际使用前须完成VF创建、VF MSE及就绪检查。`};
}
function sriovRidExplorer(){return `<div class="flit-explorer" role="group" aria-label="VF RID与Bus窗口查询"><div class="flit-controls">${powerInput('svrid-pf','PF RID hex','2a00')}${powerInput('svrid-offset','First VF Offset hex','1')}${powerInput('svrid-stride','VF Stride hex','1')}${powerInput('svrid-count','NumVFs 十进制','300')}${powerInput('svrid-v','VF序号（从1开始）','256')}</div><p id="svrid-result" class="note address-query-output" aria-live="polite">${esc(sriovRidInfo('2a00','1','1','300','256').text)}</p></div>`;}
function sriovBarExplorer(){return `<div class="flit-explorer" role="group" aria-label="VF BAR地址窗口查询"><div class="flit-controls">${powerInput('svbar-base','首VF基址 hex','80000000')}${powerInput('svbar-size','单VF BAR大小 hex','10000')}${powerInput('svbar-count','NumVFs 十进制','4')}${powerInput('svbar-v','VF序号（从1开始）','4')}${powerInput('svbar-page','System Page Size字节数 hex','1000')}${powerSelect('svbar-width','Memory BAR地址宽度',[['32','32 bit'],['64','64 bit']])}</div><p id="svbar-result" class="note address-query-output" aria-live="polite">${esc(sriovBarInfo('80000000','10000','4','4','1000','32').text)}</p></div>`;}
function updateSriovQuery(e){const id=e.target?.id||'',val=id=>document.getElementById(id)?.value;if(id.startsWith('svrid-'))document.getElementById('svrid-result').textContent=sriovRidInfo(val('svrid-pf'),val('svrid-offset'),val('svrid-stride'),val('svrid-count'),val('svrid-v')).text;if(id.startsWith('svbar-'))document.getElementById('svbar-result').textContent=sriovBarInfo(val('svbar-base'),val('svbar-size'),val('svbar-count'),val('svbar-v'),val('svbar-page'),val('svbar-width')).text;}
document.addEventListener('input',updateSriovQuery);document.addEventListener('change',updateSriovQuery);

function g6LaneSequenceInfo(o){
 const order=['req+','ack+','req-','ack-'];
 if(!['normal','reset'].includes(o.context)||!['P0','P0s','P1','P2'].includes(o.target))return {state:'invalid',text:'请选择有效的产品运行上下文和目标P-state。'};
 if(o.context==='reset')return {state:'reset',text:'复位上下文：运行态四相查询不适用。复位期间Ack可为高，先按全局/Lane复位和初始化流程检查；不能拿它替代本次运行请求的Ack。'};
 const text=String(o.trace??'').trim();if(text.length>160)return {state:'invalid',text:'只输入本次单方向事务，最多160字符；不拼接多笔或丢失边沿的记录。'};
 const trace=text?text.split(/[,\s]+/).filter(Boolean):[];
 if(!trace.length)return {state:'idle',step:0,text:'本次无边沿：Req/Ack低只是运行态空闲，不是已经完成一次更新。先准备目标配置，再发Req。'};
 for(let i=0;i<trace.length;i++)if(trace[i]!==order[i])return {state:'invalid',step:i,text:`第${i+1}个边沿不符：期望${order[i]||'结束本次事务'}，实际为${trace[i]}。检查是否漏边沿、复用了旧Ack或拼入下一笔；不自行猜测同拍先后。`};
 if(!o.stable)return {state:'blocked',step:trace.length,text:'配置保持条件不满足：本次Req开始到最后Ack下降之间，受请求控制的目标配置须保持。即使四个边沿都齐，也不能确认本次目标已正确应用。'};
 if(!o.coherent)return {state:'blocked',step:trace.length,text:'同Link配置不一致：先核本次方向的pstate/rate/width/PLL选择等捕获值；各Lane有独立引脚不等于同Link可任意组合。'};
 if(o.target==='P0'&&trace.length>=3&&!o.clockReady)return {state:'blocked',step:trace.length,text:'进入P0时过早撤Req：tx_symclk必须在req-之前有效且频率正确。最后Ack下降或PLL状态高不能补回这个已错过的前提。'};
 if(trace.length<4){const hints=['','等待本次Ack升高','已见Ack升高，可以撤Req；还没完成','Req已撤，等待本次Ack下降'];return {state:'pending',step:trace.length,text:`${hints[trace.length]}；目标配置继续保持。下一边沿应为${order[trace.length]}。${o.target==='P0'&&trace.length<3?'进入P0时，撤Req之前还必须确认输入符号时钟有效且频率正确。':''}这里没有给定通用完成超时。`};}
 return {state:'complete',step:4,text:`本次单方向Lane四相序列完成，所填配置保持及同Link一致性前提满足${o.target==='P0'?'，且进入P0的输入时钟资格已确认':''}。这不证明另一方向/全部Lane、校准、L0、DL_Active或BER；P1后disable及PLL/参考停钟还要分别检查。`};
}
function g6LaneSequenceDiagram(){return `<figure><figcaption>原创阶段图：单方向、本次运行态事务；不按时间比例，不是厂商波形或通用PIPE状态机</figcaption><div style="overflow-x:auto"><svg viewBox="0 0 920 235" role="img" aria-label="准备配置，Req上升，Ack上升，Req下降，Ack下降完成；进入P0时Req下降前时钟有效" style="width:100%;min-width:620px;background:#f4f7fb;color:#142333"><g fill="#e0eeea" stroke="#26776c" stroke-width="2"><rect x="16" y="42" width="160" height="67" rx="10"/><rect x="198" y="42" width="160" height="67" rx="10"/><rect x="380" y="42" width="160" height="67" rx="10"/><rect x="562" y="42" width="160" height="67" rx="10"/><rect x="744" y="42" width="160" height="67" rx="10"/></g><g fill="currentColor" font-size="19" text-anchor="middle"><text x="96" y="69">准备目标</text><text x="96" y="94">Req/Ack低</text><text x="278" y="69">Req ↑</text><text x="278" y="94">保持配置</text><text x="460" y="69">Ack ↑</text><text x="460" y="94">尚未完成</text><text x="642" y="69">Req ↓</text><text x="642" y="94">等待Ack撤销</text><text x="824" y="69">Ack ↓</text><text x="824" y="94">本次方向完成</text><text x="187" y="82">→</text><text x="369" y="82">→</text><text x="551" y="82">→</text><text x="733" y="82">→</text></g><path d="M210 133H894 M210 127V139 M894 127V139" stroke="#26776c" stroke-width="2"/><g fill="currentColor" font-size="18"><text x="255" y="159">整个事务内保持本次目标，不提前覆盖下一配置</text><text x="25" y="192">进入TX P0：输入符号时钟在Req ↓前就必须有效且频率正确</text><text x="25" y="221">本次配置完成 ≠ 全部Lane完成 ≠ 协议Link Up</text></g></svg></div></figure>`;}
function g6LaneSequenceExplorer(){const o={context:'normal',target:'P0',trace:'req+,ack+,req-,ack-',stable:true,coherent:true,clockReady:true};return `<div class="flit-explorer" role="group" aria-label="Gen6产品Lane握手序列查询"><div class="flit-controls">${powerSelect('g6lane-context','上下文',[['normal','3.02a运行态，初始Req/Ack低'],['reset','复位或初始化中']])}${powerSelect('g6lane-target','本次目标',[['P0','TX进入P0'],['P0s','P0s'],['P1','P1'],['P2','P2']])}${powerInput('g6lane-trace','依次观测的边沿（逗号分隔）',o.trace)}${powerSelect('g6lane-stable','全过程目标配置保持',[['yes','已确认'],['no','未保持或未知']])}${powerSelect('g6lane-coherent','同Link本方向配置一致',[['yes','已确认'],['no','不一致或未知']])}${powerSelect('g6lane-clock','Req下降前TX输入时钟有效且频率正确',[['yes','已确认'],['no','未确认或不满足']])}</div><p id="g6lane-result" class="protocol-query-output" aria-live="polite">${esc(g6LaneSequenceInfo(o).text)}</p>${g6LaneSequenceDiagram()}</div>`;}
function updateG6LaneSequence(e){if(!e.target?.id?.startsWith('g6lane-'))return;const val=id=>document.getElementById(id)?.value;document.getElementById('g6lane-result').textContent=g6LaneSequenceInfo({context:val('g6lane-context'),target:val('g6lane-target'),trace:val('g6lane-trace'),stable:val('g6lane-stable')==='yes',coherent:val('g6lane-coherent')==='yes',clockReady:val('g6lane-clock')==='yes'}).text;}
document.addEventListener('input',updateG6LaneSequence);document.addEventListener('change',updateG6LaneSequence);

function siovSnapshotInfo(o){
 const parse=v=>{const s=String(v).trim().replace(/^0x/i,'');return /^[0-9a-f]{1,8}$/i.test(s)?parseInt(s,16):null;};
 const cap=parse(o.cap),dw=parse(o.dw08);if(cap===null||dw===null)return {state:'invalid',text:'输入无效：能力+04h与+08h读取值须为1～8位hex。前提为已经确认0038h / Version1的SIOV能力。'};
 const strided=(cap&1)!==0,mixed=(cap&2)!==0,total=dw&65535,status=dw>>>24,enabled=(status&1)!==0,reservedByte=(dw>>>16)&255,capReserved=(cap&0xfffffffc)>>>0,statusReserved=status&254;
 const issues=[];if(enabled&&o.samePfVf)issues.push('同一PF同时有活动SDI和VF Enable：不允许，Mixed=1也不能豁免。');if(enabled&&o.otherPfSriov&&!mixed)issues.push('其他PF已运行SR-IOV且当前Mixed=0：适用的跨PF模式需统一，不能据每PF都有能力就混用。');
 let text=`Total SDIs=${total}（+08h低16bit）；+0Bh Status=${status.toString(16).toUpperCase().padStart(2,'0')}h，${enabled?'至少一个SDI已启用，活动数未知':'没有SDI启用的状态指示'}。SIOV Enabled为RO，不能写1创建。${strided?'Strided=1：RID必须由First SDI Offset/SDI Stride确定；Stride须非0。':'Strided=0：Offset/Stride为RsvdP，不用于分配；VI须从合法且不冲突的RID池提供身份。'} Mixed=${mixed?1:0}。`;
 if(issues.length)text+=' '+issues.join(' ');else text+=' 所填快照未发现上述同PF/跨PF冲突；这不证明RID池、映射或平台隔离已正确。';
 const warnings=[];if(statusReserved)warnings.push('Status的RsvdZ非零，核对偏移、版本和读取一致性');if(total===0&&enabled)warnings.push('支持总数为0但活动指示为1，核对设备/快照一致性');if(capReserved||reservedByte)warnings.push('RsvdP位有读取值，按保留位处理，不解释为新功能或数量');if(warnings.length)text+=' 提示：'+warnings.join('；')+'。';
 return {state:issues.length?'blocked':warnings.length?'warning':'decoded',strided,mixed,total,status,enabled,reservedByte,issues,text};
}
function siovRegisterDiagram(){const rows=[{offset:'+00h',f:[['Next',12],['Ver',4],['ID=0038h',16]]},{offset:'+04h',f:[['RsvdP',30],['M',1],['S',1]]},{offset:'+08h',f:[['Status +0Bh',8],['RsvdP +0Ah',8],['Total SDIs',16]]},{offset:'+0Ch',f:[['SDI Stride',16],['First SDI Offset',16]]}];return `<figure><figcaption>原创位域图 · Base7.0 SIOV Version1 · 每行32bit，左bit31、右bit0；偏移相对能力块</figcaption><div style="overflow-x:auto"><svg viewBox="0 0 840 355" role="img" aria-label="SIOV寄存器四个DWORD，Total SDIs在加08低16位，Status在加0B字节，能力bit1为Mixed，bit0为Strided" style="width:100%;min-width:620px;background:#f4f7fb;color:#142333">${rows.map((r,i)=>{let x=20,bit=31;const y=35+i*72;return `<text x="20" y="${y-8}" fill="currentColor" font-size="17">${r.offset}</text>`+r.f.map(([name,w])=>{const at=x,hi=bit,lo=bit-w+1;x+=w*25;bit-=w;return `<rect x="${at}" y="${y}" width="${w*25}" height="44" fill="${name.includes('Rsvd')?'#e2e8ee':'#d6ece5'}" stroke="#287367"/><text x="${at+w*12.5}" y="${y+16}" text-anchor="middle" fill="currentColor" font-size="12">${w===1?hi:hi+':'+lo}</text><text x="${at+w*12.5}" y="${y+35}" text-anchor="middle" fill="currentColor" font-size="16">${name}</text>`;}).join('');}).join('')}<text x="20" y="339" font-size="17" fill="currentColor">S：Strided RID Mapping；M：Mixed IOV Supported；Status bit0：SIOV Enabled（RO）</text></svg></div></figure>`;}
function siovSnapshotExplorer(){return `<div class="flit-explorer" role="group" aria-label="SIOV能力读取快照查询"><div class="flit-controls">${powerInput('siovq-cap','能力+04h DWORD hex','00000003')}${powerInput('siovq-dw08','+08h读取DWORD hex','01000020')}${powerSelect('siovq-samevf','同一PF的VF Enable',[['no','0：未启用VF'],['yes','1：已启用VF']])}${powerSelect('siovq-other','其他PF已运行SR-IOV',[['yes','是（相关跨PF条件适用）'],['no','否或无相关其他PF']])}</div><p id="siovq-result" class="protocol-query-output" aria-live="polite">${esc(siovSnapshotInfo({cap:'3',dw08:'01000020',samePfVf:false,otherPfSriov:true}).text)}</p>${siovRegisterDiagram()}</div>`;}
function updateSiovSnapshot(e){if(!e.target?.id?.startsWith('siovq-'))return;const val=id=>document.getElementById(id)?.value;document.getElementById('siovq-result').textContent=siovSnapshotInfo({cap:val('siovq-cap'),dw08:val('siovq-dw08'),samePfVf:val('siovq-samevf')==='yes',otherPfSriov:val('siovq-other')==='yes'}).text;}
document.addEventListener('input',updateSiovSnapshot);document.addEventListener('change',updateSiovSnapshot);

function cfgHopInfo(busText,deviceText,pathText,ari){
 const hex=(s,max)=>{s=String(s).trim().replace(/^0x/i,'');return /^[0-9a-f]+$/i.test(s)&&Number.parseInt(s,16)<=max?Number.parseInt(s,16):null};
 const bus=hex(busText,255),dev=hex(deviceText,31),raw=String(pathText).split(',');
 if(bus===null||dev===null||raw.length<1||raw.length>8)return {state:'invalid',message:'Bus须为00～FF、传统Device位须为00～1F；路径输入1～8项Secondary:Subordinate十六进制对。'};
 const pairs=raw.map(s=>s.trim().split(':').map(x=>hex(x,255)));
 if(pairs.some(p=>p.length!==2||p.some(x=>x===null)||p[0]>p[1]))return {state:'invalid',message:'每项应为Secondary:Subordinate，数值00～FF且Secondary≤Subordinate；例如01:09,02:09,03:03。'};
 const h=n=>n.toString(16).toUpperCase().padStart(2,'0'),lines=[];
 for(let i=0;i<pairs.length;i++){
  const [sec,sub]=pairs[i],label=`第${i+1}级 [${h(sec)}:${h(sub)}]`;
  if(bus===sec){
   if(dev!==0&&!ari){lines.push(`${label}：目标Bus命中Secondary，但普通Device=${h(dev)}非0，端口UR；不能退回范围转发分支。`);return {state:'ur',lines,message:lines.join('\n')};}
   lines.push(`${label}：Type1→Type0，其他字段不变；${ari?'ARI Forwarding已启用，传统Device位属于扩展Function。':'Device0有效。'}进入本地Function选择，未证明Function存在或SC。`);
   if(i<pairs.length-1)lines.push('已转换Type0，停止Type1推导；后续输入项未使用，请核候选路径是否正确。');
   return {state:'local',stage:i+1,lines,message:lines.join('\n')};
  }
  if(bus>=sec&&bus<=sub){lines.push(`${label}：目标Bus=${h(bus)}在范围内且不等于Secondary，Type1不修改继续下送。`);continue;}
  lines.push(`${label}：目标Bus=${h(bus)}不在此候选下游范围；该输入路径不能转发。完整Switch仍须检查其他端口，全部无匹配时UR。`);return {state:'no-route',lines,message:lines.join('\n')};
 }
 lines.push('输入级数已用完，仍是Type1；路径不完整，尚未命中最终直连Bus，不能判Endpoint已接收。');return {state:'incomplete',lines,message:lines.join('\n')};
}
function renderCfgHopQuery(){return `<section class="flit-explorer"><h4>常规配置候选路径查询</h4><p>十六进制；逻辑桥顺序，不检查完整fabric、兄弟端口或Function存在性。ARI开关仅对命中直连Bus的转换级生效；FPB/IDE/PCI桥等不适用。</p><div class="flit-controls">${powerInput('cfgh-bus','目标Bus（hex）','03')}${powerInput('cfgh-dev','传统Device位（hex）','00')}${powerInput('cfgh-path','Secondary:Subordinate列表','01:09,02:09,03:03')}${powerSelect('cfgh-ari','转换级ARI Forwarding',[['no','关闭（普通Device0规则）'],['yes','开启（传统Device位并入Function）']])}</div><pre id="cfgh-result" aria-live="polite" style="white-space:pre-wrap">${esc(cfgHopInfo('03','00','01:09,02:09,03:03',false).message)}</pre></section>`}
function updateCfgHop(e){if(!e.target.id?.startsWith('cfgh-'))return;document.getElementById('cfgh-result').textContent=cfgHopInfo(document.getElementById('cfgh-bus').value,document.getElementById('cfgh-dev').value,document.getElementById('cfgh-path').value,document.getElementById('cfgh-ari').value==='yes').message}
document.addEventListener('input',updateCfgHop);document.addEventListener('change',updateCfgHop);
function rrsObservationInfo(capText,controlText,access){
 const hex=s=>{s=String(s).trim().replace(/^0x/i,'');return /^[0-9a-f]{1,4}$/i.test(s)?Number.parseInt(s,16):null};
 const cap=hex(capText),control=hex(controlText);
 if(cap===null||control===null||!['vendor16','vendor32','vendorlow','other','write'].includes(access))return {state:'invalid',message:'请输入16bit十六进制Root Capabilities/Control读取值（0000～FFFF），并选择访问类型。'};
 const supported=!!(cap&1),enabled=!!(control&16),prefix=`RP自身路径：Visibility能力=${Number(supported)}，Enable=${Number(enabled)}。`;
 if(!supported&&enabled)return {state:'inconsistent',supported,enabled,message:prefix+'不一致：未实现该能力时该Enable须硬连0。核读取偏移、访问宽度及控制归属。'};
 if(!supported)return {state:'platform',supported,enabled,message:prefix+'不能套用支持Visibility的处理表；一般处理实现特定，系统复位后另有要求，并需另核RCRB统一控制路径。'};
 if(enabled&&['vendor16','vendor32'].includes(access))return {state:'visible',supported,enabled,value:access==='vendor16'?'0001h':'FFFF0001h',message:prefix+`本次已收到RRS，RC向主机提供${access==='vendor16'?'0001h':'FFFF0001h'}；Vendor ID两字节=0001h，额外读字节全1。该值非设备真实ID、非SC Payload。`};
 return {state:'retry',supported,enabled,message:prefix+'本次RRS后RC须把配置访问作为新Request重新发起；不是继续等待原Request。RC允许限制循环次数，本工具不保证最终SC或无限重试。'};
}
function renderRrsRootBits(){
 const cells=(row,highlight,label)=>Array.from({length:16},(_,i)=>{const bit=15-i,x=130+i*29;return `<text x="${x+14}" y="${row-8}" text-anchor="middle" font-size="12">${bit}</text><rect x="${x}" y="${row}" width="29" height="38" fill="${bit===highlight?'#a5d8ff':'#e5eaf0'}" stroke="#52667c"/><text x="${x+14}" y="${row+24}" text-anchor="middle" font-size="12">${bit===highlight?label:'·'}</text>`}).join('');
 return `<figure><figcaption>原创位域定位图（Base7.0）：两个16bit寄存器，相对PCIe Capability起点；圆点代表此图未展开的位。</figcaption><div style="overflow-x:auto"><svg role="img" aria-label="Root Control bit4使能及Root Capabilities bit0能力的16bit定位图" viewBox="0 0 680 235" style="width:100%;min-width:620px;background:#f4f7fb;color:#142333"><g fill="currentColor" font-family="sans-serif"><text x="12" y="60" font-size="13">+1Ch Control</text>${cells(40,4,'E')}<text x="12" y="145" font-size="13">+1Eh Cap.</text>${cells(125,0,'S')}<text x="16" y="195" font-size="13">E = Visibility Enable（RW，默认0）；S = Visibility Supported（RO）</text><text x="16" y="220" font-size="12">其他Control位有独立功能；此图不提供整字写值或RCRB位域。</text></g></svg></div></figure>`;
}
function renderRrsObservationQuery(){return `${renderRrsRootBits()}<section class="flit-explorer"><h4>已收到RRS后的主机观察查询</h4><p>仅RP自身Enable控制路径；输入读取快照，不访问设备。RCRB统一控制实现须另核归属。</p><div class="flit-controls">${powerInput('rrsq-cap','Root Capabilities +1Eh（hex16）','0001')}${powerInput('rrsq-ctrl','Root Control +1Ch（hex16）','0010')}${powerSelect('rrsq-access','本次配置访问',[['vendor32','读Vendor ID + Device ID（32bit）'],['vendor16','读完整Vendor ID（16bit）'],['vendorlow','仅读Vendor ID低字节（8bit）'],['other','读其他字段，不含完整Vendor ID'],['write','配置写']])}</div><p id="rrsq-result" aria-live="polite">${esc(rrsObservationInfo('0001','0010','vendor32').message)}</p></section>`}
function updateRrsObservation(e){if(!e.target.id?.startsWith('rrsq-'))return;document.getElementById('rrsq-result').textContent=rrsObservationInfo(document.getElementById('rrsq-cap').value,document.getElementById('rrsq-ctrl').value,document.getElementById('rrsq-access').value).message}
document.addEventListener('input',updateRrsObservation);document.addEventListener('change',updateRrsObservation);

function rcfgDecimal(text,integer=false){text=String(text).trim();if(!(integer?/^\d+$/:/^\d+(?:\.\d+)?$/).test(text))return null;const n=Number(text);return Number.isFinite(n)&&n<=1000000000?n:null}
function rcfgSpeedGateInfo(o){
 const rx=rcfgDecimal(o.rx,true),tx=rcfgDecimal(o.tx,true),us=rcfgDecimal(o.us);
 if(!['6','7'].includes(o.version)||!['8b','130b','1b'].includes(o.encoding)||!['normal','eq'].includes(o.kind)||[rx,tx,us].includes(null))return {state:'invalid',message:'请选择规范/编码/TS种类；接收与发送数用非负十进制整数，时间用非负µs数值（均≤10⁹）。'};
 if(o.encoding==='1b'&&o.kind==='eq'&&o.version==='6')return {state:'unmodeled',message:'6.0所列正文未像7.0一样单列1b/1b EQ TS2的all/any+1ms分支。本查询不裁决旧版通用TS2描述与EQ子类型关系；不是判定6.0禁止该序列。'};
 const required=o.encoding==='8b'?32:128,missing=[];
 if(!o.qualified)missing.push('接收序列还未确认字段一致性及speed_change=1');
 if(rx<8)missing.push('任一配置Lane尚未收齐连续8个合格TS2');
 if(o.kind==='eq'&&!o.all&&us<1000)missing.push('EQ证据未覆盖全部配置Lane，且从任一Lane八连完成后还未过1ms');
 if(!o.rate)missing.push('速率资格未满足：当前>2.5GT/s，或本轮双方均广告>2.5GT/s');
 if(!o.anchor)missing.push('发送计数起点尚非同一Lane收到speed_change=1的TS2之后');
 if(tx<required)missing.push(`本端发送不足${required}个speed_change=1的TS2`);
 if(o.encoding==='8b'&&o.eieos)missing.push('8b/10b发送计数被EIEOS打断，不能沿用此前累计');
 return {state:missing.length?'pending':'ready',required,missing,message:missing.length?'尚未满足成功协商出口：\n'+missing.join('\n'):`所建模的接收、速率和本端≥${required}发送门槛均达到，可按该分支去Recovery.Speed；不等于物理速率已改变，亦未裁定全部优先异常。`};
}
function renderRcfgSpeedGate(){return `<section class="flit-explorer"><h4>RcvrCfg → Speed：成功协商分支</h4><p>接收数是某Lane已限定连续序列的数量；EQ时间从该Lane八连完成后算，发送数从同Lane收到speed_change=1的TS2后算。只检查本分支。</p><div class="flit-controls">${powerSelect('rcsg-version','Base版本',[['7','7.0'],['6','6.0']])}${powerSelect('rcsg-encoding','当前训练编码',[['130b','128b/130b'],['8b','8b/10b'],['1b','1b/1b']])}${powerSelect('rcsg-kind','所用接收证据',[['eq','EQ TS2'],['normal','普通TS2']])}${powerInput('rcsg-rx','某Lane连续合格接收数','8')}${powerSelect('rcsg-qualified','字段与speed_change=1已确认',[['yes','已确认'],['no','未确认']])}${powerSelect('rcsg-all','全部配置Lane各有合格八连',[['no','否'],['yes','是']])}${powerInput('rcsg-us','EQ任一Lane八连完成后 µs','999')}${powerSelect('rcsg-rate','本分支速率资格',[['yes','已满足'],['no','尚未满足']])}${powerSelect('rcsg-anchor','发送数起点为同Lane首收speed_change=1',[['yes','是'],['no','否/未知']])}${powerInput('rcsg-tx','此起点后合格发送TS2数','128')}${powerSelect('rcsg-eieos','8b/10b计数期间被EIEOS打断',[['no','否'],['yes','是']])}</div><pre id="rcsg-result" class="note" style="white-space:pre-wrap;font:inherit" aria-live="polite">${esc(rcfgSpeedGateInfo({version:'7',encoding:'130b',kind:'eq',rx:'8',tx:'128',us:'999',qualified:true,all:false,rate:true,anchor:true,eieos:false}).message)}</pre></section>`}
function updateRcfgSpeedGate(e){if(!e.target.id?.startsWith('rcsg-'))return;const v=id=>document.getElementById('rcsg-'+id).value;document.getElementById('rcsg-result').textContent=rcfgSpeedGateInfo({version:v('version'),encoding:v('encoding'),kind:v('kind'),rx:v('rx'),tx:v('tx'),us:v('us'),qualified:v('qualified')==='yes',all:v('all')==='yes',rate:v('rate')==='yes',anchor:v('anchor')==='yes',eieos:v('eieos')==='yes'}).message}
document.addEventListener('input',updateRcfgSpeedGate);document.addEventListener('change',updateRcfgSpeedGate);
function rcfgFmGateInfo(o){
 const rx=rcfgDecimal(o.rx,true),tx=rcfgDecimal(o.tx,true),us=rcfgDecimal(o.us);
 if(!['6','7'].includes(o.version)||!['ts1-after-ts2','pad-ts1-no-ts2','pad-ts2'].includes(o.evidence)||!['ts2','pad-ts1','none'].includes(o.anchor)||[rx,tx,us].includes(null))return {state:'invalid',message:'请选择版本、接收分支和发送锚点；计数为非负十进制整数，时间为非负µs（均≤10⁹）。'};
 if(o.evidence==='pad-ts1-no-ts2'&&o.anchor==='ts2')return {state:'inconsistent',message:'历史矛盾：选了本状态从未收到TS2，却又以收到TS2为发送计数起点。'};
 if(o.evidence==='pad-ts1-no-ts2'&&o.version==='6')return {state:'unmodeled',message:'所核6.0 p509未单列“始终无TS2的PAD TS1”入口；不能直接套7.0该分支。本查询也不覆盖仅发送PAD的路径。'};
 const missing=[];
 if(!o.fm)missing.push('此查询仅适用Flit Mode，NFM须用另一组TS1不匹配规则');
 if(rx<8)missing.push('接收证据尚不足连续8个');
 if(us<1000)missing.push('从本状态第一份TS1或TS2起还未过1ms');
 if(o.speedChange)missing.push('收到的TS1/TS2 speed_change仍为1，必须为0');
 if(o.anchor==='none'||o.version==='6'&&o.anchor!=='ts2')missing.push(o.version==='6'?'6.0发送锚点须为收到一份TS2':'缺合法发送锚点：收到一份PAD TS1或一份TS2');
 if(tx<16)missing.push('合法触发事件之后本端发送TS2不足16个');
 return {state:missing.length?'pending':'ready',missing,message:missing.length?'尚未满足FM接收侧重配分支：\n'+missing.join('\n'):'所选接收侧分支、1ms、后续≥16 TS2及speed_change=0门槛达到；可按该分支回Configuration，清changed_speed_recovery和directed_speed_change。未裁定发送端主动缩宽限制、全状态优先异常或最终链路宽度。'};
}
function renderRcfgFmTimeline(){return `<figure><figcaption>原创时序示意：Base7.0接收侧FM重配，三个独立锚点；并行门槛不代表必须按图中上下顺序先后满足。</figcaption><div style="overflow-x:auto"><svg role="img" aria-label="首次TS触发1ms、连续八个接收证据、合法事件触发后续16个TS2三者汇合才可重配" viewBox="0 0 800 270" style="width:100%;min-width:700px;background:#f4f7fb;color:#142333"><g fill="currentColor" font-family="sans-serif" font-size="14"><text x="18" y="27">Recovery.RcvrCfg / FM · 本状态内观察</text><rect x="20" y="46" width="590" height="43" rx="6" fill="#d9ebff"/><text x="30" y="72">首次收到任一TS1 / TS2 → 从此起经过 ≥1ms</text><rect x="20" y="102" width="590" height="43" rx="6" fill="#e2eddc"/><text x="30" y="128">对应接收分支的连续8个证据 → 另核收到的speed_change=0</text><rect x="20" y="158" width="590" height="43" rx="6" fill="#fff0c9"/><text x="30" y="184">收到一份PAD TS1或TS2 → 此后本端发 ≥16个TS2</text><path d="M620 67 H645 V180 H620 M645 125 H675" stroke="#52667c" stroke-width="2" fill="none"/><text x="680" y="117">条件汇合</text><text x="680" y="141">Configuration</text><text x="20" y="232">6.0发送锚点仍是TS2；无TS2的PAD TS1分支不直接回填旧版。</text><text x="20" y="255">EQ升速的1ms从八连EQ完成后起算，与这里的首份TS起点不同。</text></g></svg></div></figure>`}
function renderRcfgFmGate(){return `${renderRcfgFmTimeline()}<section class="flit-explorer"><h4>FM接收侧回Configuration的门槛</h4><p>只建模下列三个接收分支，不覆盖仅本端发送PAD或完整LTSSM。接收证据选择包含其历史与字段前提。</p><div class="flit-controls">${powerSelect('rcfm-version','Base版本',[['7','7.0'],['6','6.0']])}${powerSelect('rcfm-fm','当前模式',[['yes','Flit Mode'],['no','Non-Flit Mode（本查询不适用）']])}${powerSelect('rcfm-evidence','接收证据及历史',[['pad-ts1-no-ts2','本状态无TS2，连续PAD TS1'],['ts1-after-ts2','已收TS2，随后连续TS1'],['pad-ts2','连续TS2且Link PAD']])}${powerInput('rcfm-rx','该证据连续接收数','8')}${powerInput('rcfm-us','本状态首份TS1/TS2后 µs','1000')}${powerSelect('rcfm-anchor','后续发送TS2的计数起点',[['pad-ts1','收到一份PAD TS1'],['ts2','收到一份TS2'],['none','尚无合法起点']])}${powerInput('rcfm-tx','该起点后本端已发送TS2数','16')}${powerSelect('rcfm-speed','收到序列speed_change',[['no','0'],['yes','1']])}</div><pre id="rcfm-result" class="note" style="white-space:pre-wrap;font:inherit" aria-live="polite">${esc(rcfgFmGateInfo({version:'7',fm:true,evidence:'pad-ts1-no-ts2',rx:'8',us:'1000',anchor:'pad-ts1',tx:'16',speedChange:false}).message)}</pre></section>`}
function updateRcfgFmGate(e){if(!e.target.id?.startsWith('rcfm-'))return;const v=id=>document.getElementById('rcfm-'+id).value;document.getElementById('rcfm-result').textContent=rcfgFmGateInfo({version:v('version'),fm:v('fm')==='yes',evidence:v('evidence'),rx:v('rx'),us:v('us'),anchor:v('anchor'),tx:v('tx'),speedChange:v('speed')==='yes'}).message}
document.addEventListener('input',updateRcfgFmGate);document.addEventListener('change',updateRcfgFmGate);

function memoryHex64(v){v=String(v).trim().replace(/^0x/i,'');return /^[0-9a-f]{1,16}$/i.test(v)?BigInt('0x'+v):null}
function memoryBeInfo(o){
 const address=memoryHex64(o.address),lenText=String(o.dw).trim(),dw=/^\d+$/.test(lenText)?Number(lenText):NaN;
 if(address===null||address%4n!==0n||!Number.isInteger(dw)||dw<1||dw>1024||!['read','write'].includes(o.kind)||!['nfm','th','fm-a1','fm-implied'].includes(o.mode))return {state:'invalid',message:'Header地址须为64bit十六进制且DW对齐；解码Length为十进制1～1024DW（字段编码0另表示1024DW）；请选择普通MRd/MWr及模式。'};
 if(o.mode==='th'&&o.kind!=='read')return {state:'unsupported',message:'本查询的NFM TH隐含BE仅建模MRd；不把MWr或DMWr/AtomicOp套入同一模型。'};
 const implied=['th','fm-implied'].includes(o.mode),nibble=v=>{v=String(v).trim().replace(/^0x/i,'');return /^[0-9a-f]$/i.test(v)?Number.parseInt(v,16):null};
 const first=implied?15:nibble(o.first),last=implied?(dw===1?0:15):nibble(o.last);
 if(first===null||last===null)return {state:'invalid',message:'显式First/Last BE各填一个十六进制nibble（0～F）；隐含模式才忽略这两个输入。'};
 const wireBytes=dw*4,end=address+BigInt(wireBytes)-1n,errors=[];
 if(dw===1&&last!==0)errors.push('1DW的Last BE必须0');
 if(dw>1&&(first===0||last===0))errors.push('多DW的First和Last BE均须非0');
 const sparse=dw===1||(dw===2&&address%8n===0n);
 if(!sparse&&(![8,12,14,15].includes(first)||![1,3,7,15].includes(last)))errors.push('该长度/对齐不允许稀疏BE：First须为8/C/E/F，Last须为1/3/7/F');
 if(end>0xffffffffffffffffn)errors.push('地址范围超过64bit');
 if(address/4096n!==end/4096n)errors.push('Address/Length覆盖跨4KiB，不能靠关闭首尾字节绕过');
 const pop=n=>n.toString(2).split('1').length-1,enabled=dw===1?pop(first):pop(first)+pop(last)+Math.max(0,dw-2)*4;
 const result={state:errors.length?'rule-violation':'checked',address,end,dw,first,last,wireBytes,enabled,implied,sparse,errors,kind:o.kind,mode:o.mode};
 result.message=`有效BE：First=${first.toString(16).toUpperCase()}h，Last=${last.toString(16).toUpperCase()}h${implied?'（隐含，忽略输入掩码）':''}。Length覆盖${wireBytes}byte，有效字节${enabled}。`;
 if(errors.length)result.message+='\n所查规则未通过：'+errors.join('；')+'。BE违规接收行为未定义，不能保证硬件都会检测。';
 else result.message+=`\n所查BE/地址范围通过；${o.kind==='write'?`普通MWr携带${wireBytes}byte Payload，基本1PH+${Math.ceil(dw/4)}PD`:'普通MRd请求无读Payload，基本1NPH；返回包另计'}。未核MPS/MRRS、权限及完整形成规则。`;
 if(dw===1&&first===0&&last===0)result.message+='\n这是zero-length访问：正常读完成仍携带1DW未定义数据；写仍携带1DW且默认无作用（其他协议另有定义除外）。';
 return result;
}
function memoryBeFigure(r){
 if(!['checked','rule-violation'].includes(r.state))return '';
 const bitRow=Array.from({length:8},(_,i)=>{const bit=7-i,x=90+i*60,field=bit>=4?'L':'F',idx=bit%4,val=((bit>=4?r.last:r.first)>>idx)&1;return `<text x="${x+30}" y="72" text-anchor="middle" font-size="14">${field}${idx} / bit${bit}</text><rect x="${x}" y="82" width="60" height="35" fill="${val?'#b9dfef':'#e4e8ec'}" stroke="#667b8c"/><text x="${x+30}" y="105" text-anchor="middle">${val}</text>`}).join('');
 const row=(base,mask,y,label)=>`<text x="16" y="${y+25}" font-size="13">${label}</text>`+Array.from({length:4},(_,i)=>{const x=90+i*120,on=!!(mask&(1<<i));return `<rect x="${x}" y="${y}" width="120" height="50" fill="${on?'#b9dfef':'#e4e8ec'}" stroke="#667b8c"/><text x="${x+60}" y="${y+19}" text-anchor="middle" font-size="14">A+${(base-r.address+BigInt(i)).toString()} / BE${i}=${Number(on)}</text><text x="${x+60}" y="${y+39}" text-anchor="middle" font-size="14">${on?'使能':'未使能占位'}</text>`}).join('');
 const y=r.dw>1?285:220,heading=r.mode==='nfm'?'NFM Header byte7：Last[7:4] / First[3:0]':'有效BE逻辑定位（非线上byte7内容；FM/TH另看正文）';
 return `<figure><figcaption>原创字节图：上方位序从bit7到bit0，下方地址从小到大。蓝色有效、灰色仍占DW位置。</figcaption><div style="overflow-x:auto"><svg role="img" aria-label="Byte Enable首尾位到数据地址的映射图" viewBox="0 0 600 ${y+65}" style="width:100%;background:#f4f7fb;color:#142333"><g fill="currentColor" font-family="sans-serif"><text x="16" y="24" font-size="13">${heading}</text><text x="16" y="48" font-size="14">基址 A=${r.address.toString(16).toUpperCase()}h；下面每格按相对A的偏移。</text>${bitRow}${row(r.address,r.first,135,'首个DW')}${r.dw>1?row(r.address+BigInt((r.dw-1)*4),r.last,205,'最后DW'):''}<text x="16" y="${y}" font-size="13">中间${Math.max(0,r.dw-2)}个DW全部有效；范围${r.wireBytes}byte，有效${r.enabled}byte。</text><text x="16" y="${y+26}" font-size="14">未使能占位不可省Payload；MPS/MRRS和Credit不按有效byte计。</text></g></svg></div></figure>`;
}
function renderMemoryBeQuery(){const initial=memoryBeInfo({address:'1000',dw:'3',first:'C',last:'3',kind:'write',mode:'nfm'});return `<section class="flit-explorer"><h4>普通Memory的BE与字节范围</h4><div class="flit-controls">${powerInput('mbe-address','Header地址 hex（DW对齐）','1000')}${powerInput('mbe-dw','解码Length DW（十进制）','3')}${powerInput('mbe-first','First BE hex nibble','C')}${powerInput('mbe-last','Last BE hex nibble','3')}${powerSelect('mbe-kind','普通请求类型',[['write','MWr'],['read','MRd']])}${powerSelect('mbe-mode','BE解释模式',[['nfm','NFM显式BE'],['th','NFM MRd TH=1（隐含BE）'],['fm-a1','FM有OHC-A1（显式BE）'],['fm-implied','FM无OHC-A1（隐含BE）']])}</div><pre id="mbe-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(initial.message)}</pre><div id="mbe-figure">${memoryBeFigure(initial)}</div></section>`}
