function memorySpanPlan(addressText,bytesText,limitText,kind){
 const start=memoryHex64(addressText),s=String(bytesText).trim(),bytes=/^\d+$/.test(s)?Number(s):NaN,limit=Number(limitText);
 if(start===null||!Number.isInteger(bytes)||bytes<1||bytes>65536||!['128','256','512','1024','2048','4096'].includes(String(limitText))||!['read','write'].includes(kind))return {state:'invalid',message:'起始byte地址用64bit hex；有效字节数用十进制1～65536；上限选择128～4096byte标准值；只支持普通MRd/MWr。'};
 if(start+BigInt(bytes)>1n<<64n)return {state:'invalid',message:'起始地址加有效长度超过64bit地址空间。'};
 const parts=[];let a=start,left=bytes,payloadBytes=0,dataUnits=0;
 while(left>0){const offset=Number(a%4n),base=a-BigInt(offset),pageRoom=4096-Number(a%4096n),take=Math.min(left,limit-offset,pageRoom),dw=Math.ceil((offset+take)/4);let first,last;
  if(dw===1){first=((1<<take)-1)<<offset;last=0;}else{first=(15<<offset)&15;last=(1<<(((offset+take-1)%4)+1))-1;}
  parts.push({address:base,start:a,bytes:take,dw,first,last,wireBytes:dw*4});payloadBytes+=dw*4;dataUnits+=Math.ceil(dw/4);left-=take;a+=BigInt(take);
 }
 return {state:'planned',start,bytes,limit,kind,parts,payloadBytes,dataUnits,headers:parts.length,message:`生成${parts.length}笔普通${kind==='write'?'MWr':'MRd'}请求，有效${bytes}byte，DW范围合计${payloadBytes}byte。${kind==='write'?`MWr载荷也是${payloadBytes}byte；基本${parts.length}PH+${dataUnits}PD（逐TLP取整）`:`MRd请求无读Payload；基本${parts.length}NPH，Completion数量不由此表确定`}。上限取输入的适用${kind==='write'?'Tx MPS':'MRRS'}，未证明设备配置或访问授权。`};
}
function memorySpanTable(r){if(r.state!=='planned')return '';return `<div style="overflow-x:auto"><table><thead><tr><th>笔</th><th>Header地址</th><th>有效起点</th><th>有效byte</th><th>Length DW</th><th>FBE/LBE</th><th>DW范围byte</th></tr></thead><tbody>${r.parts.slice(0,32).map((p,i)=>`<tr><td>${i+1}</td><td>${p.address.toString(16).toUpperCase()}h</td><td>${p.start.toString(16).toUpperCase()}h</td><td>${p.bytes}</td><td>${p.dw}</td><td>${p.first.toString(16).toUpperCase()}/${p.last.toString(16).toUpperCase()}</td><td>${p.wireBytes}</td></tr>`).join('')}</tbody></table></div>${r.parts.length>32?'<p>仅显示前32笔；汇总按全部请求计算。</p>':''}`}
function renderMemorySpanPlanner(){const initial=memorySpanPlan('1FFD','10','128','write');return `<section class="flit-explorer"><h4>连续byte访问的普通TLP规划</h4><p>上限是已确认的适用Tx MPS或MRRS；生成一种合法候选拆法，不读取真实配置。排除UIO/AtomicOp/DMWr/TH/IDE。</p><div class="flit-controls">${powerInput('mspan-address','起始byte地址 hex','1FFD')}${powerInput('mspan-bytes','有效byte数（十进制）','10')}${powerSelect('mspan-limit','适用Tx MPS / MRRS（byte）',[['128','128'],['256','256'],['512','512'],['1024','1024'],['2048','2048'],['4096','4096']])}${powerSelect('mspan-kind','普通请求类型',[['write','MWr：上限按适用Tx MPS'],['read','MRd：上限按MRRS']])}</div><p id="mspan-result" class="note" aria-live="polite">${esc(initial.message)}</p><div id="mspan-table">${memorySpanTable(initial)}</div></section>`}
