function r51Hex(value){const t=String(value).trim();return /^(?:0x)?[0-9a-f]{1,8}$/i.test(t)?Number.parseInt(t.replace(/^0x/i,''),16):null}
function lowerSkpInfo(o){
 const rates=[2.5,5,8,16,32,64,128],rate=Number(o.rate),k=rates.indexOf(rate),v=o.version;
 if(!['6.0','7.0'].includes(v)||k<0||!['cc','srns','sris'].includes(o.clock)||!['nfm','fm'].includes(o.mode)||!['l0','other'].includes(o.state)||!['observe','change'].includes(o.action)||!['yes','no','unknown'].includes(o.path))return {state:'invalid',message:'请选择已列的版本、速率、模式、状态与路径条件。'};
 const fields=['own','peer','own2','peer2','control'],n=fields.map(x=>r51Hex(o[x]));if(n.includes(null))return {state:'invalid',message:'五个寄存器均需输入1～8位十六进制DWORD，可带0x；不接受负数、超32bit或空值。'};
 if((rate>=64&&o.mode!=='fm')||(v==='6.0'&&rate===128))return {state:'invalid',message:'所选版本/速率/模式不匹配：64/128GT/s需FM，Base6.0不定义128GT/s。'};
 const [a,b,a2,b2,ctl]=n,bit=(x,i)=>((x>>>i)&1)===1,ext=rate===128;
 const supportedA=ext?bit(a,7)&&bit(a2,0):bit(a,k+1),supportedB=ext?bit(b,7)&&bit(b2,0):bit(b,k+1);
 const tx=ext?bit(a,15)&&bit(a2,8):bit(a,k+9),rx=ext?bit(b,22)&&bit(b2,16):bit(b,k+16),enabled=bit(ctl,k+9);
 const loc=ext?'128GT/s：Supported=LinkCap2[7]+Vector2[0]；A生成=LinkCap2[15]+Vector2[8]；B接收=LinkCap2[22]+Vector2[16]；使能=LinkControl3[15]。':`${rate}GT/s：Supported=LinkCap2[${k+1}]；A生成[${k+9}]；B接收[${k+16}]；使能=LinkControl3[${k+9}]。`;
 const flags=`A支持速率 ${supportedA?'是':'否'}；B支持速率 ${supportedB?'是':'否'}；A生成 ${tx?'是':'否'}；B接收 ${rx?'是':'否'}；使能位 ${enabled?1:0}；透明路径 ${o.path==='yes'?'已确认':o.path==='no'?'不支持':'未确认'}。`;
 let state='checked',reason='该方向所查Lower SKP能力与路径条件通过。',qualified=supportedA&&supportedB&&tx&&rx&&o.path==='yes';
 if(v==='6.0'&&rate===64){state='reserved';qualified=false;reason='Base6.0能力表列64GT/s，但LinkControl3内部bit5仍Reserved；不能套7.0编码给出启用通过。';}
 else if(v==='7.0'&&o.mode==='fm'&&o.action==='change'&&rate!==2.5){state='undefined';reason='Base7.0：FM且非2.5GT/s时改变Lower SKP使能设置，行为未定义；能力通过也不能消除此限制。';}
 else if(!supportedA||!supportedB){state='blocked';reason='所选速率支持条件不齐，不能据此认定该运行配置或Lower SKP可用。';}
 else if(enabled&&(!tx||!rx||o.path==='no')){state='blocked';reason='已置使能，但本端生成、对端接收或透明路径条件不齐。不得认定配置有效；生成能力未广告却置使能有未定义行为。';}
 else if(enabled&&o.path==='unknown'){state='pending';reason='使能位已置，但扩展路径能力未确认，不能判通过。';}
 else if(!enabled){state='disabled';reason=qualified?'所查方向具备开启条件，但当前使能为0。':'当前使能为0；尚未满足全部开启资格，这不单独证明SRIS本身不支持。';}
 const effective=state==='checked'&&qualified&&enabled&&o.state==='l0';
 const policy=o.clock!=='sris'?'Common/SRNS：普通调度本来就按非SRIS分支；Lower位不会改变物理架构。':effective?'SRIS且L0、Lower已使能并通过所查资格：采用SRNS频度。':o.state!=='l0'?'SRIS但不是L0：Lower不生效，按SRIS频度。':'SRIS：只有有效使能后才可用SRNS频度；异常/未知配置不作调度通过判定。';
 return {state,qualified,enabled,effective,rateCode:rate===128?8:k+1,message:[loc,flags,reason,policy,`当前速率状态编码=${rate===128?8:k+1}；这不是PIPE Rate编码。`,v==='6.0'&&o.action==='change'?'6.0未在所读相应页列7.0该修改窗口句；本查询不据此保证6.0任意动态修改合法。':'','仅离线检查所列规则，不写寄存器，不验证电气/所有Function/完整LTSSM。'].filter(Boolean).join('\n')};
}
const R51_LOWER_DEFAULT={version:'7.0',rate:'32',clock:'sris',mode:'nfm',state:'l0',action:'observe',path:'yes',own:'00002020',peer:'00100020',own2:'00000101',peer2:'00010001',control:'00002000'};
function lowerSkpExplorer(){return `<section class="flit-explorer"><h4>A→B：能力与使能快照</h4><div class="flit-controls">${powerSelect('lsk-version','Base版本',[['7.0','7.0'],['6.0','6.0']])}${powerSelect('lsk-rate','当前速率 GT/s',[['32','32'],['2.5','2.5'],['5','5'],['8','8'],['16','16'],['64','64'],['128','128']])}${powerSelect('lsk-clock','实际时钟',[['sris','SRIS'],['srns','SRNS'],['cc','Common Clock']])}${powerSelect('lsk-mode','模式',[['nfm','NFM'],['fm','FM']])}${powerSelect('lsk-state','LTSSM',[['l0','L0'],['other','非L0']])}${powerSelect('lsk-action','动作',[['observe','只观察取值'],['change','准备改变使能设置']])}${powerSelect('lsk-path','透明扩展路径Lower SKP支持',[['yes','无扩展或所有扩展已确认支持'],['unknown','未确认'],['no','已知存在不支持者']])}${powerInput('lsk-own','A LinkCap2 DWORD hex','00002020')}${powerInput('lsk-peer','B LinkCap2 DWORD hex','00100020')}${powerInput('lsk-own2','A 128GT/s Capabilities hex','00000101')}${powerInput('lsk-peer2','B 128GT/s Capabilities hex','00010001')}${powerInput('lsk-control','A LinkControl3 DWORD hex','00002000')}</div><pre id="lsk-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(lowerSkpInfo(R51_LOWER_DEFAULT).message)}</pre></section>`}
function skpScheduleInfo(o){
 const rate=Number(o.rate),count=Number(o.count),rates=[2.5,5,8,16,32,64,128];
 if(!['6.0','7.0'].includes(o.version)||!rates.includes(rate)||!['nfm','fm'].includes(o.mode)||!['cc','srns','sris'].includes(o.clock)||!['on','off'].includes(o.lower)||!['l0','other','loopback','compliance','upsize'].includes(o.state)||!['outside','inside','boundary'].includes(o.stream)||!/^\d+$/.test(String(o.count))||!Number.isSafeInteger(count))return {state:'invalid',message:'请选择已列条件，计数为非负十进制整数；它是调度计数，不是实测线间距。'};
 if((rate>=64&&o.mode!=='fm')||(o.version==='6.0'&&rate===128))return {state:'invalid',message:'64/128GT/s需FM；Base6.0不定义128GT/s。'};
 if(['loopback','compliance','upsize'].includes(o.state))return {state:'special',message:'Loopback/Compliance/L0p激活Lane有专门分支；本普通调度查询不对此上下文判通过。请对照相应版本§4.2.8.4及对应状态规则。'};
 if(o.mode==='nfm'&&o.stream!=='outside')return {state:'invalid',message:'本字段inside/boundary专指FM Data Stream及其边界；NFM选择普通调度范围。'};
 if(o.mode==='fm'&&rate>=8&&o.stream!=='outside')return {state:'boundary',message:'FM Data Stream及其进出边界需按适用Flit位置与SKP安排检查，不套370/740 Blocks普通表。本查询暂不判此分支计数合法性。'};
 const slow=o.clock!=='sris'||(o.lower==='on'&&o.state==='l0'),unit=rate<=5?'Symbol Times':'Blocks';
 const min=slow?(rate<=5?1180:rate<=32?370:740):0,max=slow?(rate<=5?1538:rate<=32?375:750):(rate<=5?154:rate<=32?38:76);
 const pass=slow?count>=min&&count<=max:count<max;
 const range=slow?`${min}～${max} ${unit}（含端点）`:`严格小于${max} ${unit}`;
 return {state:pass?'checked':'outside',slow,min,max,unit,pass,message:`${rate<=5?'8b/10b':rate<=32?'128b/130b':'1b/1b'}；${slow?'非SRIS或L0有效Lower分支':'SRIS高频分支'}：${range}。\n输入${count} ${unit}，${pass?'在所选调度范围内':'不在所选调度范围内'}。${o.clock==='sris'&&o.lower==='on'&&o.state!=='l0'?'非L0不能用Lower强制低频。':''}\nLower能力/路径资格另查；EI时间不计入计数。调度到期与线上发出、Receiver容忍度分开；不是完整硬件合规验证。`};
}
const R51_SCHEDULE_DEFAULT={version:'7.0',rate:'32',mode:'nfm',clock:'sris',lower:'on',state:'l0',stream:'outside',count:'375'};
function skpScheduleExplorer(){return `<section class="flit-explorer"><h4>普通SKP调度分支与计数</h4><div class="flit-controls">${powerSelect('sks-version','Base',[['7.0','7.0'],['6.0','6.0']])}${powerSelect('sks-rate','GT/s',[['32','32'],['2.5','2.5'],['5','5'],['8','8'],['16','16'],['64','64'],['128','128']])}${powerSelect('sks-mode','模式',[['nfm','NFM'],['fm','FM']])}${powerSelect('sks-clock','实际时钟',[['sris','SRIS'],['srns','SRNS'],['cc','Common Clock']])}${powerSelect('sks-lower','Lower SKP（资格另核）',[['on','已有效使能'],['off','未使能']])}${powerSelect('sks-state','LTSSM上下文',[['l0','L0'],['other','其他普通状态'],['loopback','Loopback'],['compliance','Compliance'],['upsize','L0p正在激活的Lane']])}${powerSelect('sks-stream','FM Data Stream位置',[['outside','普通表范围：NFM或FM非Data Stream'],['inside','FM Data Stream中'],['boundary','FM Data Stream进出边界']])}${powerInput('sks-count','调度计数（十进制）','375')}</div><pre id="sks-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(skpScheduleInfo(R51_SCHEDULE_DEFAULT).message)}</pre></section>`}
function lowerSkpBitDiagram(){const rows=[['LinkCap2 +2Ch（两端各自）',[[31,23,'其他'],[22,16,'Reception'],[15,9,'Generation'],[8,8,'Cross'],[7,1,'Speeds'],[0,0,'R']]],['LinkControl3：0019h +04h',[[31,16,'其他/保留'],[15,9,'Lower使能'],[8,2,'R'],[1,0,'EQ控制']]],['128GT/s Cap：0039h +04h',[[31,24,'R'],[23,16,'Reception2'],[15,8,'Generation2'],[7,0,'Speeds2']]]];return `<figure class="flit-explorer"><svg viewBox="0 0 800 340" role="img" aria-labelledby="lower-skp-bit-title" style="width:100%;height:auto"><title id="lower-skp-bit-title">Base7.0 Lower SKP三个寄存器的原创字段位置图</title><g font-family="sans-serif" fill="#17324c">${rows.map(([name,fields],r)=>`<text x="12" y="${28+r*102}" font-size="19">${name}</text>${fields.map(([hi,lo,label])=>{const x=12+(31-hi)*24,w=(hi-lo+1)*24;return `<rect x="${x}" y="${40+r*102}" width="${w}" height="43" fill="${label.includes('Generation')?'#dbe6ff':label.includes('Reception')?'#d6eee3':'#edf0f4'}" stroke="#62768c"/><text x="${x+w/2}" y="${56+r*102}" text-anchor="middle" font-size="12">${hi===lo?hi:hi+':'+lo}</text>${w>=55?`<text x="${x+w/2}" y="${75+r*102}" text-anchor="middle" font-size="13">${label}</text>`:''}`}).join('')}`).join('')}<text x="12" y="332" font-size="16">字段内部bit0在各字段最低位；Vector2当前仅bit0定义为128GT/s。</text></g></svg><figcaption>7.0原位图重新组织为并排字段对照；6.0的Control3仅定义到32GT/s，高两位不照搬本图。</figcaption></figure>`}
function refClockOwnershipDiagram(){return `<figure class="flit-explorer"><svg viewBox="0 0 760 270" role="img" aria-labelledby="refclk-map-title" style="width:100%;height:auto"><title id="refclk-map-title">参考时钟关系与PIPE及恢复时钟的不同边界</title><g font-family="sans-serif" fill="#17324c" font-size="18"><rect x="12" y="20" width="330" height="80" rx="8" fill="#e6edff" stroke="#647b91"/><rect x="418" y="20" width="330" height="80" rx="8" fill="#e2f1e9" stroke="#647b91"/><text x="35" y="51">A：MAC → PHY TX</text><text x="35" y="80">PCLK是接口域，按拓扑供钟</text><text x="440" y="51">B：PHY RX → MAC</text><text x="440" y="80">SerDes RxCLK是恢复域</text><path d="M350 60H410l-12 -7m12 7l-12 7" stroke="#3155a4" stroke-width="3" fill="none"/><text x="28" y="140">两端Refclk：Common / SRNS / SRIS决定频差条件</text><text x="28" y="178">Lower SKP：核A生成 + B接收 + 扩展路径 + 速率/状态</text><text x="28" y="216">SKP与弹性缓冲补偿频差；不会替换晶振或切换PCLK源</text><text x="28" y="252">反方向B→A须交换角色重新检查；不以单根Valid证明整链路就绪。</text></g></svg></figure>`}
function r51Refresh(e){const id=e.target.id||'';if(id.startsWith('lsk-')){const o={};for(const k of Object.keys(R51_LOWER_DEFAULT))o[k]=$('#lsk-'+k).value;$('#lsk-result').textContent=lowerSkpInfo(o).message;}if(id.startsWith('sks-')){const o={};for(const k of Object.keys(R51_SCHEDULE_DEFAULT))o[k]=$('#sks-'+k).value;$('#sks-result').textContent=skpScheduleInfo(o).message;}}
document.addEventListener('input',r51Refresh);document.addEventListener('change',r51Refresh);


const R52_MODES=[['nfm128','NFM / 128b/130b'],['nfm8','NFM / 8b/10b'],['fm128','FM / 128b/130b'],['fm8','FM / 8b/10b'],['fm1','FM / 1b/1b']];
function r52ChoicesValid(o,choices){return Object.entries(choices).every(([k,values])=>values.includes(o[k]))}
function recoveryIdleRequestInfo(o){
 const modes=R52_MODES.map(x=>x[0]),events=['local-disable','local-hot','local-config','local-loop','rx2-disable','rx2-hot','rx2-pad','rx2-loop','fm8-disable','fm8-hot','fm8-loop'];
 if(!r52ChoicesValid(o,{version:['6.0','7.0'],mode:modes,role:['dsp','usp','cross'],event:events,lane:['yes','no'],entry:['yes','no'],lead:['yes','no'],stream:['yes','no']})||!/^\d+$/.test(String(o.count))||!Number.isSafeInteger(Number(o.count)))return {state:'invalid',message:'选择已列版本/模式/角色，计数须为非负十进制整数。计数只用于相应接收路径。'};
 const fm=o.mode.startsWith('fm'),local=o.event.startsWith('local-'),rx2=o.event.startsWith('rx2-'),fm8=o.event.startsWith('fm8-'),kind=o.event.split('-')[1],count=Number(o.count),name={disable:'Disabled',hot:'Hot Reset',config:'Configuration',pad:'Configuration',loop:'Loopback'}[kind];
 let state='matched',reason='',role='';
 if(local){
  if(['disable','hot'].includes(kind)&&o.role==='usp'){state='not-this-path';reason='本地高层Disable/Hot Reset这条入口适用于DSP或可选crosslink；USP不能仅据这条规则认定目标。';}
  else if(kind==='loop'&&o.lead!=='yes'){state='not-qualified';reason='主动Loopback Lead需要实现可选Lead能力；Follower接收路径不是同一条件。';}
  else {reason='本地高层定向路径满足所选角色/能力条件。';if(kind==='loop')role='Lead';}
 }else{
  if(o.lane!=='yes'){state='not-qualified';reason='接收证据不来自已配置Lane，未满足any configured Lane。';}
  else if(rx2){
   if(kind!=='pad'&&fm){state='not-this-path';reason='所选两TS1控制请求路径用于NFM；FM应核导致进入Idle的8TS2路径。';}
   else if(kind==='pad'&&o.mode==='fm1'){state='format-review';reason='1b/1b不总显式发送Lane Number；需联核§4.2.7格式规则，本查询不从原始Lane PAD字段作简化判定。';}
   else if(['disable','hot'].includes(kind)&&o.role==='dsp'){state='not-this-path';reason='NFM两TS1 Disable/Hot Reset接收路径仅USP或可选crosslink适用。';}
   else if(count<2){state='waiting';reason='需要同一已配置Lane的连续2份合格TS1；零散总数不能替代。';}
   else {reason='连续2份合格TS1满足本接收路径。';if(kind==='loop')role='Follower';}
  }else if(fm8){
   if(!fm){state='not-this-path';reason='导致进入Idle的8TS2控制路径属于FM；NFM核两TS1或本地定向路径。';}
   else if(kind==='disable'&&o.role!=='usp'){state='not-this-path';reason='FM Disable的此接收句仅写USP，不能推广到DSP或可选crosslink。';}
   else if(kind==='hot'&&o.role==='dsp'){state='not-this-path';reason='FM Hot Reset的此接收路径不以DSP为接收角色。';}
   else if(kind==='hot'&&o.role==='cross'&&o.version==='6.0'){state='version-review';reason='6.0对应句只写USP；7.0新增可选crosslink文字。本查询不将7.0扩展倒填为6.0已确认条件。';}
   else if(count<8||o.entry!=='yes'){state='waiting';reason='需连续8份合格TS2，且确实是导致进入Idle的那组入口证据；Idle之后重新累计不足以替代。';}
   else{reason='FM入口8TS2请求快照满足本路径。';if(kind==='loop')role='Follower';}
  }
 }
 const target=state==='matched'?name:null;
 let cleanup='尚未匹配所选路径，不据此决定实际LTSSM下一状态。';
 if(target){cleanup=o.mode==='nfm128'?(o.stream==='yes'?'128b/130b NFM已发SDS：先在活动Lane发送EDS结束流，再发送目标状态训练序列；去这些控制状态前不得再补Idle Symbols。':'128b/130b NFM尚未开始Data Stream：不能凭空要求先结束不存在的流；去控制状态前不得额外补Idle Symbols。'):['fm128','fm1'].includes(o.mode)?'128b/130b或1b/1b FM去这些控制状态前不得额外补IDLE Flits；流结束按FM专门边界规则，不套NFM EDS。':o.mode==='fm8'?'8b/10b FM：所读段落未在此编码分支重复128b/130b/1b/1b的禁补Idle条款；本查询不替它补该要求，也不推断可以任意延迟目标状态入口。':'8b/10b NFM不套128b/130b的EDS专属要求。';}
 const note=kind==='pad'&&fm?'7.0推荐FM改宽用RcvrCfg→Configuration，NFM用此PAD路径；这里不把建议当所有其它入口禁止。':kind==='config'&&fm?'Configuration候选不等于FM任意动态upconfigure获准；还须核重配目的与L0p规则。':'';
 return {state,target,loopRole:role,needsEds:!!target&&o.mode==='nfm128'&&o.stream==='yes',message:[`${state==='matched'?'匹配候选出口':'未判为匹配'}${target?'：'+target+(role?' '+role:''):''}。`,reason,cleanup,note,'只检查一个请求路径，不裁决多个并发请求、timeout优先级或完整目标状态入口。'].filter(Boolean).join('\n')};
}
const R52_IDLE_DEFAULT={version:'7.0',mode:'nfm128',role:'usp',event:'rx2-loop',count:'2',lane:'yes',entry:'yes',lead:'no',stream:'yes'};
function recoveryIdleControlExplorer(){return `<section class="flit-explorer"><h4>Recovery.Idle单请求检查</h4><div class="flit-controls">${powerSelect('rid-version','Base',[['7.0','7.0'],['6.0','6.0']])}${powerSelect('rid-mode','模式/编码',R52_MODES)}${powerSelect('rid-role','本端角色',[['usp','USP'],['dsp','DSP'],['cross','可选crosslink']])}${powerSelect('rid-event','单一请求路径',[['rx2-loop','接收连续TS1 Loopback'],['rx2-disable','接收连续TS1 Disable'],['rx2-hot','接收连续TS1 Hot Reset'],['rx2-pad','接收连续TS1 Lane PAD'],['fm8-loop','FM入口8TS2 Loopback'],['fm8-disable','FM入口8TS2 Disable'],['fm8-hot','FM入口8TS2 Hot Reset'],['local-loop','本地上层请求Lead'],['local-disable','本地上层Disable'],['local-hot','本地上层Hot Reset'],['local-config','本地上层重配']])}${powerInput('rid-count','同一Lane合格连续TS数','2')}${powerSelect('rid-lane','接收者为已配置Lane',[['yes','是'],['no','否']])}${powerSelect('rid-entry','FM TS2确为导致进Idle的序列',[['yes','是'],['no','否/不确定']])}${powerSelect('rid-lead','本端实现可选Lead能力',[['no','否'],['yes','是']])}${powerSelect('rid-stream','已发SDS启动NFM Data Stream',[['yes','是'],['no','否']])}</div><pre id="rid-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(recoveryIdleRequestInfo(R52_IDLE_DEFAULT).message)}</pre>${r52IdleCleanupDiagram()}</section>`}
function l0ExitEvidenceInfo(o){
 if(!r52ChoicesValid(o,{version:['6.0','7.0'],mode:R52_MODES.map(x=>x[0]),event:['ts','eieos','all-ei','eios','direct','tx-l0s'],scope:['any','all','none'],power:['none','l1','l2'],txAll:['yes','no'],rxL0s:['yes','no'],txL0s:['yes','no'],l0p:['yes','no']}))return {state:'invalid',message:'请选择已列版本、模式、单一事件和限定条件。'};
 const fm=o.mode.startsWith('fm'),encoded=['nfm128','fm128','fm1'].includes(o.mode);let state='candidate',target=null,reason='';
 if(o.event==='direct'){target='Recovery';reason='高层指示到Recovery（包括Retrain Link）构成该出口；发端可完成在途TLP/DLLP，不是任意截断。';}
 else if(o.event==='tx-l0s'){
  if(fm){state='not-supported';reason='FM不支持L0s；7.0还明确硬件忽略L0s Enable。';}
  else if(o.txL0s!=='yes'){state='not-qualified';reason='TX L0s须先核实现、时钟/Retimer条件及适用启用资格。';}
  else{target='TX L0s';reason='本地高层发起且TX L0s已具备资格：仅TX进入，RX不必同时进入。';}
 }else if(o.scope==='none'){state='not-qualified';reason='未在配置Lane上取得所选事件证据；不能按该条判断出口。';}
 else if(o.event==='ts'){target='Recovery';reason='任一配置Lane的有效TS1/TS2足够；不先等全部Lane各收8份。';}
 else if(o.event==='eieos'){
  if(!encoded){state='not-this-rule';reason='L0的这个EIEOS出口仅用于128b/130b或1b/1b；8b/10b不能套用。';}
  else{target='Recovery';reason='128b/130b或1b/1b的任一配置Lane收到EIEOS。';}
 }else if(o.event==='all-ei'){
  if(o.scope!=='all'){state='not-qualified';reason='本条件要求所有Lane EI且未收EIOS；部分Lane EI不能直接满足，L0p本来可有闲置Lane。';}
  else{state='permitted-choice';target='Recovery 或保持L0';reason='所有Lane已检测/推断EI且没有EIOS：规范允许两种处理，不自动判L1/L2/Hot Reset或热拔出。';}
 }else if(o.event==='eios'){
  if(fm&&o.rxL0s==='yes'){state='invalid';reason='FM与RX L0s已可用矛盾；不能用旧使能位绕过FM不支持L0s。';}
  else if(o.power!=='none'&&o.l0p==='yes'){state='context-review';reason='同一个EIOS被同时标为已协商低功耗与预期L0p缩宽；需先澄清上下文，本查询不裁决并发流程优先。';}
  else if(o.power!=='none'){
   if(o.txAll!=='yes'){state='waiting';reason='已同意'+o.power.toUpperCase()+'且收到EIOS，但还需全部Lane完成发送EIOSQ。';}
   else{target=o.power.toUpperCase();reason='双方已同意目标 + 任一Lane收到EIOS + 全部Lane已发EIOSQ，三者满足。';}
  }else if(o.l0p==='yes'){
   if(!fm){state='invalid';reason='L0p仅FM支持；NFM不能把EIOS标作L0p缩宽预期来忽略。';}
   else if(o.version==='6.0'){state='version-review';reason='6.0 L0句未列7.0的显式L0p排除；需联核该版L0p完整流程，不能按后版一句话裁决。';}
   else{state='l0p-context';target='按L0p缩宽流程继续';reason='7.0明确排除预期L0p降宽EIOS进入该Recovery分支；不代表整个EIOS都被无条件忽略。';}
  }else if(o.rxL0s==='yes'){
   if(fm){state='invalid';reason='FM与“RX L0s已可用”条件矛盾；L0s在FM不支持。';}
   else{target='RX L0s';reason='无L1/L2定向且RX L0s资格已核：仅RX进入L0s，TX可留L0。';}
  }else{target='Recovery';reason='任一Lane EIOS、RX无L0s、无L1/L2定向，且不是已确认的L0p预期EIOS。';}
 }
 return {state,target,message:[`${target?'候选处理：'+target:'未确认候选出口'}。`,reason,'“L0s已可用”需预先核NFM、无Retimer、非SRIS与实现条件；本查询不做EI物理推断。','单事件解释，不给并发事件发明优先关系，也不证明Data Link/业务已经可用。'].join('\n')};
}
const R52_L0_DEFAULT={version:'7.0',mode:'nfm128',event:'eios',scope:'any',power:'l1',txAll:'no',rxL0s:'no',txL0s:'no',l0p:'no'};
function l0ExitEvidenceExplorer(){return `<section class="flit-explorer"><h4>已在L0：单一事件与候选出口</h4><div class="flit-controls">${powerSelect('l0e-version','Base',[['7.0','7.0'],['6.0','6.0']])}${powerSelect('l0e-mode','模式/编码',R52_MODES)}${powerSelect('l0e-event','单一已限定事件',[['eios','收到EIOS'],['ts','收到有效TS1/TS2'],['eieos','收到有效EIEOS'],['all-ei','EI且没有EIOS'],['direct','上层直接要求Recovery'],['tx-l0s','上层要求TX L0s']])}${powerSelect('l0e-scope','事件发生范围',[['any','至少一条配置Lane'],['all','全部Lane'],['none','无配置Lane证据']])}${powerSelect('l0e-power','双方已同意的高层目标',[['l1','L1'],['none','没有L1/L2定向'],['l2','L2']])}${powerSelect('l0e-txAll','全部Lane已发送EIOSQ',[['no','尚未'],['yes','已完成']])}${powerSelect('l0e-rxL0s','RX L0s资格已全部核实',[['no','否'],['yes','是（NFM/无Retimer/非SRIS等）']])}${powerSelect('l0e-txL0s','TX L0s资格已全部核实',[['no','否'],['yes','是']])}${powerSelect('l0e-l0p','EIOS确为L0p降低宽度的预期',[['no','否'],['yes','是，已有L0p上下文']])}</div><pre id="l0e-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(l0ExitEvidenceInfo(R52_L0_DEFAULT).message)}</pre>${r52L0ExitDiagram()}</section>`}
function r52IdleCleanupDiagram(){return `<figure><svg viewBox="0 0 760 245" role="img" aria-labelledby="r52-idle-diagram" style="width:100%;height:auto"><title id="r52-idle-diagram">Recovery.Idle请求资格与已有Data Stream收尾的顺序</title><g font-family="sans-serif" fill="#18324b" font-size="18"><rect x="14" y="18" width="730" height="52" rx="8" fill="#e6edff" stroke="#647b91"/><text x="33" y="50">先核角色、FM/NFM、连续TS及入口快照；确定候选出口</text><path d="M380 74v23" stroke="#3155a4" stroke-width="3"/><rect x="14" y="102" width="730" height="60" rx="8" fill="#e1f0e8" stroke="#647b91"/><text x="33" y="129">若128b/130b NFM已发SDS：先发EDS结束当前流</text><text x="33" y="152" font-size="16">去控制状态前不额外补Idle；FM不得机械套NFM EDS</text><path d="M380 166v23" stroke="#3155a4" stroke-width="3"/><text x="34" y="220">再进入相应Configuration / Disabled / Hot Reset / Loopback流程</text></g></svg><figcaption>单路径依赖图，不表示多个请求同时发生时的全局优先级。</figcaption></figure>`}
function r52L0ExitDiagram(){return `<figure><svg viewBox="0 0 760 300" role="img" aria-labelledby="r52-l0-diagram" style="width:100%;height:auto"><title id="r52-l0-diagram">L0事件的不同证据与候选出口</title><g font-family="sans-serif" fill="#18324b" font-size="18"><rect x="15" y="15" width="730" height="48" rx="7" fill="#e7edff" stroke="#647b91"/><text x="35" y="46">L0：先分事件，再核各出口限定条件</text><text x="25" y="100">有效TS / 适用EIEOS → Recovery</text><text x="25" y="140">全Lane EI、无EIOS → 可Recovery或留L0</text><text x="25" y="180">EIOS + 已协商L1/L2 + 全Lane发EIOSQ → L1 / L2</text><text x="25" y="220">无协商：核RX L0s资格；FM还核预期L0p缩宽EIOS</text><text x="25" y="266" font-size="16">TX/RX L0s可分离；收到EIOS本身不能证明已进入低功耗。</text></g></svg></figure>`}
function r52Refresh(e){const id=e.target.id||'';if(id.startsWith('rid-')){const o={};for(const k of Object.keys(R52_IDLE_DEFAULT))o[k]=$('#rid-'+k).value;$('#rid-result').textContent=recoveryIdleRequestInfo(o).message;}if(id.startsWith('l0e-')){const o={};for(const k of Object.keys(R52_L0_DEFAULT))o[k]=$('#l0e-'+k).value;$('#l0e-result').textContent=l0ExitEvidenceInfo(o).message;}}
document.addEventListener('input',r52Refresh);document.addEventListener('change',r52Refresh);


function r53Hex(raw,bits){if(!/^(?:0x)?[0-9a-f]+$/i.test(String(raw).trim()))return null;const n=Number.parseInt(String(raw).trim().replace(/^0x/i,''),16);return Number.isSafeInteger(n)&&n<2**bits?n:null;}
function ariRegisterInfo(fn,kind,capRaw,ctlRaw,f0Raw){
 const cap=r53Hex(capRaw,16),ctl=r53Hex(ctlRaw,16),f0=r53Hex(f0Raw,16);
 if(!/^\d+$/.test(String(fn))||Number(fn)>255||![cap,ctl,f0].every(x=>x!==null)||!['nonvf','vf'].includes(kind))return {state:'invalid',message:'Function须为0～255十进制，三个寄存器须为0～FFFF十六进制。'};
 fn=Number(fn);const isF0=fn===0&&kind==='nonvf';
 if(isF0&&cap!==f0)return {state:'inconsistent',message:'当前Function为0时，两处Capability输入必须来自同一读值。'};
 const nfn=cap>>>8,m=f0&1,a=(f0>>>1)&1,group=(ctl>>>4)&7,problems=[];
 if(!isF0&&(cap&3))problems.push('非Function0的M/A能力必须为0');
 if(!isF0&&(ctl&3))problems.push('非Function0的组使能必须硬连0');
 if(!m&&(ctl&1))problems.push('F0无MFVC分组能力，MFVC组使能必须为0');
 if(!a&&(ctl&2))problems.push('F0无ACS分组能力，ACS组使能必须为0');
 if(!(m||a)&&group)problems.push('F0的M/A均为0，Function Group必须为000b');
 if(kind==='nonvf'&&nfn!==0&&nfn<=fn)problems.push('非零NFN必须指向更高编号非VF');
 const state=problems.length?'conflict':kind==='vf'?'vf-undefined':'decoded';
 return {state,nfn:kind==='vf'?null:nfn,group,m,a,message:[`Function ${fn}；当前M=${cap&1}、A=${(cap>>>1)&1}；F0 M=${m}、A=${a}。`,`Control：MFVC组使能=${ctl&1}，ACS组使能=${(ctl>>>1)&1}；Function Group=${group}（[6:4]）。`,kind==='vf'?'VF：NFN未定义，请使用PF的First VF Offset/VF Stride，不能沿本值枚举VF。':nfn===0?'NFN=0：本非VF链在此结束。':`NFN=${nfn}：${nfn>fn?'指向更高编号的非VF':'回退或自指，不满足规则'}。`,...problems.map(x=>'冲突：'+x),'组使能不等于上游ARI Forwarding Enable。结果依赖输入身份和成功读取，不替代完整设备审查。'].join('\n')};
}
function r53AriDiagram(){return `<figure class="note"><svg viewBox="0 0 660 255" role="img" aria-label="原创ARI两个16bit寄存器位图" style="width:100%;height:auto"><title>ARI Capability与Control位定义（原创）</title><g font-size="19" font-family="sans-serif" fill="currentColor"><text x="10" y="25">+04h Capability · 16 bit · RO</text><text x="10" y="145">+06h Control · 16 bit · RW / 硬连零条件</text></g><g stroke="currentColor" fill="none"><rect x="10" y="38" width="640" height="55"/><path d="M330 38v55M570 38v55M610 38v55"/><rect x="10" y="158" width="640" height="55"/><path d="M370 158v55M490 158v55M570 158v55M610 158v55"/></g><g font-family="sans-serif" font-size="18" text-anchor="middle" fill="currentColor"><text x="170" y="73">[15:8] NFN</text><text x="450" y="73">[7:2] RsvdP</text><text x="590" y="73">A</text><text x="630" y="73">M</text><text x="190" y="193">[15:7] RsvdP</text><text x="430" y="193">[6:4] Group</text><text x="530" y="193">[3:2]</text><text x="590" y="193">A</text><text x="630" y="193">M</text></g><g font-family="sans-serif" font-size="17" fill="currentColor"><text x="10" y="115">bit1=A，bit0=M；能力及组使能仅F0有效</text><text x="10" y="243">Group属于当前Function；上游Forwarding另在PCIe Cap +28h bit5</text></g></svg></figure>`;}
function ariRegisterExplorer(){return `<section class="flit-explorer"><h4>ARI寄存器离线解码</h4>${r53AriDiagram()}<div class="flit-controls">${powerInput('arq-fn','当前Function（十进制）','17')}${powerSelect('arq-kind','身份',[['nonvf','非VF'],['vf','VF']])}${powerInput('arq-cap','当前Capability hex','c800')}${powerInput('arq-ctl','当前Control hex','0030')}${powerInput('arq-f0','Function0 Capability hex','1103')}</div><pre id="arq-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(ariRegisterInfo('17','nonvf','c800','0030','1103').message)}</pre></section>`;}
function capSnapshotInfo(mode,startRaw,text){
 const stop=(state,message,rows=[],warnings=[])=>({state,rows,warnings,message:[...rows,...warnings.map(x=>'提示：'+x),message].join('\n')});
 if(!['extended','traditional'].includes(mode))return stop('invalid','请选择配置Function的传统或Extended模式，不含RCRB。');
 const lines=String(text).split(/\r?\n/).map(x=>x.trim()).filter(Boolean),map=new Map(),warnings=[];
 if(!lines.length||lines.length>128)return stop('invalid','输入1～128行；128是本工具预算，不是协议限制。');
 for(const line of lines){const pair=line.split('=');if(pair.length!==2)return stop('invalid','每行格式：hex偏移=hex头值。');const addr=r53Hex(pair[0],12),v=r53Hex(pair[1],mode==='extended'?32:16);if(addr===null||v===null)return stop('invalid','偏移须在000～FFFh，头须符合16/32bit宽度。');if(map.has(addr))return stop('invalid','重复输入偏移，请先整理快照。');map.set(addr,v);}
 let ptr=0x100;if(mode==='traditional'){const raw=r53Hex(startRaw,8);if(raw===null)return stop('invalid','34h值须为8bit十六进制。');ptr=raw&0xfc;if(raw!==ptr)warnings.push('34h raw低2bit已按规范掩码');if(ptr===0)return stop('invalid','PCIe Function的传统Capabilities Pointer应非零，不能按Extended空链解释。',[],warnings);}
 const seen=new Set(),rows=[];
 for(let hop=0;hop<128;hop++){
  if(ptr<(mode==='extended'?0x100:0x40)||ptr>(mode==='extended'?0xffc:0xfc)||ptr%4)return stop('range','偏移不满足本模式范围/对齐检查；传统节点Next不对齐按本工具保护停止。',rows,warnings);
  if(seen.has(ptr))return stop('cycle','重复访问偏移：链形成环，停止。',rows,warnings);seen.add(ptr);
  if(!map.has(ptr))return stop('incomplete',`缺少${ptr.toString(16).toUpperCase()}h节点：快照证据不足，不直接判硬件错误。`,rows,warnings);
  const v=map.get(ptr),id=mode==='extended'?v&0xffff:v&0xff,ver=mode==='extended'?(v>>>16)&15:null,rawNext=mode==='extended'?v>>>20:v>>>8,next=mode==='extended'?rawNext&0xffc:rawNext;
  if(mode==='extended'&&v===0&&ptr===0x100&&hop===0)return stop('empty','100h全零：配置Function没有Extended Capability。',rows,warnings);
  if((mode==='extended'&&v===0xffffffff)||(mode==='traditional'&&v===0xffff))return stop('read-suspect','全1头不是本工具认可的空链标记；请先检查配置读取。',rows,warnings);
  if(id===0)return stop('invalid-header','非起始空链位置遇到ID=0，本工具停止并要求核对快照。',rows,warnings);
  rows.push(`${ptr.toString(16).toUpperCase()}h：ID=${id.toString(16).toUpperCase()}h${ver===null?'':`，Version=${ver}`}；Next raw=${rawNext.toString(16).toUpperCase()}h → ${next.toString(16).toUpperCase()}h`);
  if(mode==='extended'&&rawNext!==next)warnings.push('Extended Next低2bit已按规范掩码，保留raw供对照');
  if(next===0)return stop('complete','Next=0：链结束。未知ID不妨碍按标准头继续；未解析各能力正文。',rows,warnings);
  ptr=next;
 }
 return stop('budget','达到本工具128节点预算，未宣称链完整。',rows,warnings);
}
function r53ChainDiagram(){return `<figure class="note"><svg viewBox="0 0 660 235" role="img" aria-label="原创三种发现机制对照" style="width:100%;height:auto"><title>偏移链、Function链与VF映射（原创）</title><g fill="currentColor" font-family="sans-serif" font-size="19"><text x="12" y="30">能力偏移链 · 单个Function内部 · 单位byte</text><text x="25" y="65">100h → 300h → 180h → 0　可回退但不能成环</text><text x="12" y="110">ARI NFN · 非VF · 单位Function编号</text><text x="25" y="145">F0 → F17 → F200 → 0　非零必须更高</text><text x="12" y="190">VF RID = PF RID + First VF Offset + (n−1) × Stride</text><text x="25" y="225">VF不走NFN；组号不是RID，也不是Capability偏移</text></g></svg></figure>`;}
const R53_CAP_SAMPLE='100=3001000e\n300=1801000b\n180=00010001';
function capSnapshotExplorer(){return `<section class="flit-explorer"><h4>Capability链离线快照</h4><div class="flit-controls">${powerSelect('cpq-mode','配置Function链',[['extended','Extended · 32bit头'],['traditional','传统Type0/1 · 16bit头']])}${powerInput('cpq-start','传统34h读值 hex（Extended忽略）','40')}</div><label for="cpq-text">每行hex偏移=hex头值；传统例：40=8010，80=0005（分两行）</label><textarea id="cpq-text" rows="6" style="display:block;width:100%;box-sizing:border-box;font:inherit" spellcheck="false">${esc(R53_CAP_SAMPLE)}</textarea><pre id="cpq-result" class="note" aria-live="polite" style="white-space:pre-wrap;overflow-wrap:anywhere;font:inherit">${esc(capSnapshotInfo('extended','40',R53_CAP_SAMPLE).message)}</pre></section>`;}
function r53Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x)?.value;if(id.startsWith('arq-'))document.getElementById('arq-result').textContent=ariRegisterInfo(v('arq-fn'),v('arq-kind'),v('arq-cap'),v('arq-ctl'),v('arq-f0')).message;if(id.startsWith('cpq-'))document.getElementById('cpq-result').textContent=capSnapshotInfo(v('cpq-mode'),v('cpq-start'),v('cpq-text')).message;}
document.addEventListener('input',r53Refresh);document.addEventListener('change',r53Refresh);


function ioFormationInfo(o){
 const first=r53Hex(o.first,4),last=r53Hex(o.last,4),attr=r53Hex(o.attr,2),at=r53Hex(o.at,2);
 if(!['nfm','fm'].includes(o.mode)||!['read','write'].includes(o.action)||!['sc','ur','ca','rrs'].includes(o.status)||!['yes','no'].includes(o.a2)||![first,last,attr,at].every(x=>x!==null)||!/^\d+$/.test(String(o.length))||Number(o.length)>1023||!/^\d+$/.test(String(o.tc))||Number(o.tc)>7)return {state:'invalid',message:'请使用所列模式/操作/状态；Length输入0～1023的十进制原始编码，TC 0～7，BE单hex位，Attr/AT为0～3 hex。'};
 const errors=[];if(Number(o.length)!==1)errors.push('Length必须编码1（1DW）；0不是零byte，而是不能用于此请求的长度编码');if(Number(o.tc)!==0)errors.push('TC必须000b');if(attr)errors.push('Attr[1:0]必须00b，不能启用RO/No Snoop');if(at)errors.push('AT必须00b（接收端不要求/不鼓励检查，不等于发送端可任意设置）');if(last)errors.push('Last DW BE必须0000b');
 const enabled=[0,1,2,3].filter(i=>first&(1<<i)),missing=o.mode==='fm'&&o.a2!=='yes',reqBytes=(o.mode==='fm'?16:12)+(o.action==='write'?4:0),statusError=o.status==='rrs';
 let state=missing?'missing-ohc':errors.length?'formation-conflict':statusError?'status-not-applicable':'fields-ok';
 const cpl=o.status==='sc'&&o.action==='read'?'CplD':'Cpl',cplPayload=cpl==='CplD'?4:0;
 const message=[`I/O ${o.action==='read'?'Read':'Write'} · ${o.mode.toUpperCase()}。`,...errors.map(x=>'形成冲突：'+x),missing?'FM缺少必需OHC-A2：不能隐含全BE；接收端按缺少必需OHC的Request处理为UR。':'NFM不使用A2；FM必须携带A2。',`First BE=${first.toString(2).padStart(4,'0')}：${enabled.length?'选DW基址+'+enabled.join('/+'): '无byte使能'}；Length仍须1DW，不能用选中数代替。`,`按要求形成的最小请求：${reqBytes}B（Header${o.mode==='fm'?' Base 12B + A2 4B':' 12B'}${o.action==='write'?' + Data 4B':''}）；其它OHC/Prefix/Digest/Trailer及链路开销另计。`,statusError?'RRS不是I/O请求的通用忙重试状态；不据该输入构造正常完成。':`若成功到达并返回所选${o.status.toUpperCase()}状态：${cpl}，数据${cplPayload}B；Byte Count=4，Lower Address=0。${cplPayload?'仅BE选中字节具有对应读取有效性；BE=0时数据内容未指定。':'无数据不等于Byte Count必须0；本工具不生成Reserved Length值。'}`,errors.length?'违反所列形成要求；除必需OHC检查外，不据此断言全部Receiver必然报告同一种Malformed。':'仅所列字段检查，不含真实地址命中、Tag能力、路由、设备模型和其它错误。','预期完成形态仅在请求可以被服务/终止时适用；形成错误时不承诺实际出现该Completion。'].join('\n');
 return {state,errors,enabled,requestBytes:reqBytes,completion:statusError?null:{type:cpl,payload:cplPayload,byteCount:4,lowerAddress:0},message};
}
const R54_IO_DEFAULT={mode:'fm',action:'read',length:'1',tc:'0',attr:'0',at:'0',first:'5',last:'0',a2:'yes',status:'sc'};
function ioFormationExplorer(){return `<section class="flit-explorer"><h4>I/O请求字段与完成形态</h4><div class="flit-controls">${powerSelect('ioq-mode','模式',[['fm','FM'],['nfm','NFM']])}${powerSelect('ioq-action','操作',[['read','IORd'],['write','IOWr']])}${powerInput('ioq-length','Length原始编码（十进制）','1')}${powerInput('ioq-tc','TC（十进制）','0')}${powerInput('ioq-attr','Attr[1:0] hex','0')}${powerInput('ioq-at','AT[1:0] hex','0')}${powerInput('ioq-first','First BE hex','5')}${powerInput('ioq-last','Last BE hex','0')}${powerSelect('ioq-a2','FM携带OHC-A2',[['yes','是'],['no','否']])}${powerSelect('ioq-status','假设返回状态',[['sc','SC'],['ur','UR'],['ca','CA'],['rrs','RRS（观察不适用）']])}</div><pre id="ioq-result" class="note" aria-live="polite" style="white-space:pre-wrap;overflow-wrap:anywhere;font:inherit">${esc(ioFormationInfo(R54_IO_DEFAULT).message)}</pre></section>`;}
function cfgDwordInfo(o){
 const off=r53Hex(o.offset,12),dest=r53Hex(o.dest,16),seg=r53Hex(o.segment,8);
 if(!['nfm','fm'].includes(o.mode)||!['cfg0rd','cfg0wr','cfg1rd','cfg1wr'].includes(o.kind)||off===null||dest===null||seg===null||!['1','2','4'].includes(String(o.bytes)))return {state:'invalid',message:'偏移须为000～FFFh，Destination ID 0000～FFFFh，Segment 00～FFh；访问byte数选1/2/4。'};
 const count=Number(o.bytes),lane=off%4,base=off-lane,ext=(base>>>8)&15,reg=(base>>>2)&63,regFm=base>>>2,be=((1<<count)-1)<<lane,write=o.kind.endsWith('wr');
 if(off+count>4096)return {state:'outside',message:'访问超出单Function 4KiB配置空间；不能回卷到下一Function。'};
 if(lane+count>4)return {state:'cross-dw',message:'访问跨越DW，不能形成一笔Length=1DW的配置请求；需按平台/寄存器模型安排多次访问，不自动读改写或拆分。'};
 const hex=(n,w=1)=>n.toString(16).toUpperCase().padStart(w,'0'),fmt=write?'010':'000',type=o.kind.startsWith('cfg0')?'00100':'00101',a3=hex(seg,2)+'0080'+hex(be,2),nfmDw=hex(dest,4)+hex(ext,2)+hex(reg<<2,2),fmDw=hex(dest,4)+hex(base,4),requestBytes=(o.mode==='fm'?16:12)+(write?4:0);
 return {state:'encoded',base,ext,reg,regFm,be,requestBytes,nfmDw,fmDw,a3: o.mode==='fm'?a3:null,message:[`${o.kind.toUpperCase()}；Destination ID=${hex(dest,4)}h；单包Length=1DW、Last BE=0、TC0、Attr[1:0]=0、AT=0。`,`byte偏移=${hex(off,3)}h → DW基址=${hex(base,3)}h，选择byte ${Array.from({length:count},(_,i)=>lane+i).join('/')}，First BE=${be.toString(2).padStart(4,'0')}b。`,`NFM：Fmt=${fmt}b，Type=${type}b；ExtReg=${hex(ext)}h，Reg=${hex(reg,2)}h；Byte8→11=${nfmDw}（按Header byte序展示）。`,`FM：Register Number[9:0]=${hex(regFm,3)}h；Header Base的Byte8→11=${fmDw}。`,o.mode==='fm'?`限定RP新发起FM请求：必带A3，DSV=1、Destination Segment=${hex(seg,2)}h；A3相对Byte0→3=${a3}。不能套到经历NFM翻译的所有中间观测点。`:'当前NFM不发送A3/Segment字段；此处FM字段仅作对照。',`最小请求${requestBytes}B（其它可选头/尾、链路开销另计）；${write?'写Payload仍为1DW，由BE选byte':'请求无读Payload，成功单份CplD返回1DW'}。`,'未验证Type0/Type1路由、ARI、Tag、寄存器访问语义或运行状态，不执行真实寄存器读写。'].join('\n')};
}
const R54_CFG_DEFAULT={mode:'fm',kind:'cfg0rd',offset:'abd',bytes:'1',dest:'2a11',segment:'02'};
