function ebCadenceInfo(config,text){
 if(!['pclk2','pclk3'].includes(config))return {state:'invalid',message:'仅支持所列Rate=1、Width=2的两个PCLK_Rate示例。'};
 const trace=String(text).replace(/\s/g,'');if(!/^[01]{1,128}$/.test(trace))return {state:'invalid',message:'输入1～128个0/1，每位代表一个PCLK；可有空格和换行。'};
 const gap=config==='pclk2'?2:4,positions=Array.from(trace).flatMap((x,i)=>x==='1'?[i]:[]),pairs=positions.slice(1).map((v,i)=>({from:positions[i],to:v,distance:v-positions[i],ok:v-positions[i]>=gap})),bad=pairs.filter(x=>!x.ok);
 return {state:bad.length?'cadence-conflict':'no-conflict',trace,minInterval:gap,positions,pairs,message:[`Rate=1，Width=2，PCLK_Rate=${config==='pclk2'?'2':'3'}；相邻有效拍间隔检查值${gap}个PCLK，即中间${gap-1}个0。`,config==='pclk2'?'本例原文should never，不提升为额外MUST；工具标出节奏不符。':'本例原文must always，要求两次有效之间至少3个空拍。',`有效拍位置（从0起）：${positions.length?positions.join('、'):'无'}。`,...pairs.map(x=>`${x.from}→${x.to}：间距${x.distance}，${x.ok?'符合本项间隔':'过密'}。`),bad.length?'发现示例节奏冲突，不能靠连续补发缩短空拍造成的延迟。':'本快照未发现这项最小间隔冲突；空拍后相位不必回到原位置。',pairs.length?'':'没有两个有效拍，不足以验证持续节奏。','只核此示例的间隔，不判断吞吐下限、缓冲深度、对齐、RxValid/Status或整条链路合规。'].filter(Boolean).join('\n')};
}
function ebCadencePlot(info){if(!info.trace)return '';return `<figure class="note"><figcaption>原创逐拍图 · 上方数字为PCLK序号</figcaption><div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:10px">${Array.from(info.trace).map((x,i)=>`<span style="display:inline-flex;flex-direction:column;align-items:center;min-width:32px;border:1px solid currentColor;border-radius:5px;padding:4px;${x==='1'?'font-weight:700;background:var(--surface,#e7f3ed)':''}"><small>${i}</small><span>${x}</span></span>`).join('')}</div><p>1：RxDataValid有效；0：本拍无有效数据。颜色仅辅助阅读。</p></figure>`;}
function ebCadenceExplorer(){const r=ebCadenceInfo('pclk3','10001000010001000');return `<section class="flit-explorer"><h4>Nominal Empty：示例有效拍节奏</h4><div class="flit-controls">${powerSelect('ebc-config','固定Rate=1、Width=2',[['pclk3','PCLK_Rate=3：至少3个空拍'],['pclk2','PCLK_Rate=2：至少1个空拍']])}</div><label for="ebc-trace">RxDataValid轨迹（每位一个PCLK）</label><textarea id="ebc-trace" rows="3" spellcheck="false" style="display:block;width:100%;box-sizing:border-box;font:inherit">10001000010001000</textarea><pre id="ebc-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(r.message)}</pre><div id="ebc-plot">${ebCadencePlot(r)}</div></section>`;}
function rxErrorBeatInfo(o){
 const yesno=['yes','no'];if(!['original','serdes'].includes(o.arch)||!['8b10b','128b130b'].includes(o.encoding)||!['half','empty'].includes(o.buffer)||!['none','add','remove'].includes(o.skp)||!['separate','decode'].includes(o.disparityReport)||!['bypass','decode','overflow','underflow','disparity','header'].every(k=>yesno.includes(o[k])))return {state:'invalid',message:'请选择所列架构、编码、缓冲和单拍事件。'};
 if(o.arch==='serdes')return {state:'out-of-scope',status:null,message:'本查询的接收流错误模型不适用于SerDes PHY。该架构的RxStatus仅Receiver detected功能适用；接收流检查需看MAC职责，不能输出本工具的PHY错误码。'};
 const conflicts=[];if(o.buffer==='empty'&&o.underflow==='yes')conflicts.push('Nominal Empty不使用普通underflow错误');if(o.buffer==='empty'&&o.skp==='add')conflicts.push('本PCIe Nominal Empty模型移除SKP并使用RxDataValid，不以添加SKP替代空拍');if(o.encoding==='128b130b'&&o.disparity==='yes')conflicts.push('PCIe 8/16/32GT/s不使用8b/10b disparity报告');if(o.encoding==='8b10b'&&o.header==='yes')conflicts.push('128b/130b Sync Header事件不能用于8b/10b模式');if(o.bypass==='yes'&&(o.decode==='yes'||o.disparity==='yes'))conflicts.push('EncodeDecodeBypass时不使用解码/Disparity错误报告');
 if(conflicts.length)return {state:'scope-conflict',status:null,message:conflicts.join('\n')+'\n输入的接口报告条件互相矛盾；先确认模式和事件定义，不将其修成一个看似合法的RxStatus。'};
 const ranked=[['decode','100',o.encoding==='8b10b'?'8b/10b decode错误':'PHY需上报的SKP内容decode错误'],['overflow','101','EB overflow'],['underflow','110','EB underflow'],['disparity',o.disparityReport==='decode'?'100':'111','Receive disparity']];const winner=ranked.find(([k])=>o[k]==='yes');const status=winner?winner[1]:o.skp==='add'?'001':o.skp==='remove'?'010':'000';
 const reason=winner?winner[2]:o.skp!=='none'?'SKP'+(o.skp==='add'?'添加':'移除')+'指示':'本输入没有需要PHY报告的接收流事件';
 return {state:'selected',status,winner:winner?.[0]||o.skp,message:[`本拍RxStatus=${status}：${reason}。`,winner&&o.skp!=='none'?'同拍错误优先于SKP添加/移除通知；不能据缺少001/010断言未补偿。':'',winner?.[0]==='disparity'&&o.disparityReport==='decode'?'该PHY选择disparity合并报100；这不把disparity事件优先级提升到真正decode错误之前。':'',o.encoding==='128b130b'?'128b/130b原始Sync Header检查属于MAC；PHY的SKP内容decode错误是另一类事件。':'8b/10b decode错误用EDB替换坏byte并同拍报告；宽接口不提供每个byte完整错误定位。',o.header==='yes'?'另有Sync Header错误：由MAC独立处理，不能因本拍RxStatus=000或其它码就忽略。':'',status==='000'?'000仅表示本输入未选PHY报告事件，不能证明CRC、Sync Header或高层事务均正确。':'',o.buffer==='empty'?'Nominal Empty空条件应为RxValid=1、RxDataValid=0、RxStatus=000；overflow仍可发生。':'Half Full的SKP单位和指示窗口按2.5/5与8/16/32GT/s分开。','只检查已确认的单拍事件；排除Receiver Detect、EB Reset忙窗口和其它协议，非原始波形解码器。'].filter(Boolean).join('\n')};
}
const R55_RX_DEFAULT={arch:'original',encoding:'8b10b',buffer:'half',skp:'remove',bypass:'no',decode:'no',overflow:'yes',underflow:'no',disparity:'yes',header:'no',disparityReport:'separate'};
function rxErrorPriorityDiagram(){return `<figure class="note"><svg viewBox="0 0 650 220" role="img" aria-label="原创接收错误优先级与MAC职责图" style="width:100%;height:auto"><title>单拍RxStatus竞争：PHY错误与MAC Header检查分开</title><g fill="currentColor" font-family="sans-serif" font-size="18"><text x="12" y="28">PHY接收流事件（Original）</text><text x="20" y="65">Decode → Overflow → Underflow → Disparity</text><text x="20" y="100">按事件优先级选一个RxStatus；错误先于SKP通知</text><text x="20" y="134">100码也可能是PHY选择合并报告的Disparity</text><text x="12" y="180">MAC独立检查：128b/130b原始Sync Header</text><text x="20" y="210">RxStatus=000不等于Header、CRC或整个TLP无错</text></g><path d="M10 150h625" stroke="currentColor" stroke-dasharray="7 5"/></svg></figure>`;}
function rxErrorBeatExplorer(){const choices=[['no','否'],['yes','是']];return `<section class="flit-explorer"><h4>单拍接收事件 → RxStatus</h4>${rxErrorPriorityDiagram()}<div class="flit-controls">${powerSelect('rxe-arch','架构',[['original','Original'],['serdes','SerDes（范围外）']])}${powerSelect('rxe-encoding','PCIe编码范围',[['8b10b','8b/10b · 2.5/5'],['128b130b','128b/130b · 8/16/32']])}${powerSelect('rxe-buffer','EB模型',[['half','Nominal Half Full'],['empty','Nominal Empty']])}${powerSelect('rxe-skp','同拍补偿通知',[['remove','SKP移除'],['none','无'],['add','SKP添加']])}${powerSelect('rxe-decode','Decode / SKP内容错误',choices)}${powerSelect('rxe-overflow','EB Overflow',[['yes','是'],['no','否']])}${powerSelect('rxe-underflow','普通EB Underflow',choices)}${powerSelect('rxe-disparity','8b/10b Disparity',[['yes','是'],['no','否']])}${powerSelect('rxe-disparityReport','PHY的Disparity编码',[['separate','独立111'],['decode','合并100']])}${powerSelect('rxe-header','128b/130b Sync Header错误',choices)}${powerSelect('rxe-bypass','EncodeDecodeBypass',choices)}</div><pre id="rxe-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">${esc(rxErrorBeatInfo(R55_RX_DEFAULT).message)}</pre></section>`;}
function r55Refresh(e){const id=e.target?.id||'',v=k=>document.getElementById(k)?.value;if(id.startsWith('ebc-')){const r=ebCadenceInfo(v('ebc-config'),v('ebc-trace'));document.getElementById('ebc-result').textContent=r.message;document.getElementById('ebc-plot').innerHTML=ebCadencePlot(r);}if(id.startsWith('rxe-')){const o={};for(const k of Object.keys(R55_RX_DEFAULT))o[k]=v('rxe-'+k);document.getElementById('rxe-result').textContent=rxErrorBeatInfo(o).message;}}
