function ohcePackingExplorer(){const text='1E123456 1FABCDEF 1E654321 00000000',r=ohcePackingInfo(text,'4');return '<section class="flit-explorer"><h4>OHC-E布局查询（Base7.0）</h4><div class="flit-controls">'+powerSelect('oce-format','Header所选E块',[['4','E4：4DW'],['2','E2：2DW'],['1','E1：1DW']])+'</div><label for="oce-words">逐DW内容：每项8位hex，按byte0→3书写</label><textarea id="oce-words" rows="3" spellcheck="false" style="display:block;width:100%;box-sizing:border-box;font:inherit">'+text+'</textarea><pre id="oce-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="oce-plot">'+ohcePackingPlot(r)+'</div></section>';}
