function nfmHex(v){return /^(?:0x)?[0-9a-f]{1,3}$/i.test(String(v).trim())?parseInt(String(v).trim().replace(/^0x/i,''),16):null;}
function nfmFmt(v){return v.toString(16).toUpperCase().padStart(3,'0')+'h';}
function nfmRxInfo(expected,received,phy,nul,crc,nak){
 const n=nfmHex(expected),r=nfmHex(received),flag=nak==='yes';
 if(n===null||r===null||![phy,nul,nak].every(x=>['yes','no'].includes(x))||!['normal','inverse','bad'].includes(crc))return {state:'invalid',message:'序号输入000～FFF hex；选择各项前置结果。'};
 let state,next=n,newFlag=flag,action,error='无',forward=false;
 if(phy==='yes'){state='phy-error';action=flag?'丢弃；不重复安排NAK':'丢弃；安排NAK';newFlag=true;error='PHY负责报告，不重复记为链路层Bad TLP';}
 else if(nul==='yes'&&crc==='inverse'){state='nullified';action='有效作废：无错误丢弃，不检查普通序号分支';}
 else if(nul==='yes'||crc!=='normal'){state='bad-lcrc';action=flag?'丢弃；不重复安排NAK':'丢弃；安排NAK';newFlag=true;error='Bad TLP';}
 else if(r===n){state='accepted';next=(n+1)%4096;newFlag=false;forward=true;action='剥去链路信息，交事务层；ACK按调度/计时规则安排';}
 else if((n-r+4096)%4096<=2048){state='duplicate';action='重复包丢弃，安排ACK；不再次交事务层或重复计FC';}
 else {state='out-of-sequence';action=flag?'失序丢弃；不重复安排NAK':'失序丢弃；安排NAK';newFlag=true;error=flag?'进一步Bad TLP报告可选但不推荐':'Bad TLP';}
 const ack=(next+4095)%4096;
 return {state,next,nak:newFlag,ack,forward,message:action+'\n错误：'+error+'\nNEXT_RCV_SEQ → '+nfmFmt(next)+'；NAK_SCHEDULED → '+Number(newFlag)+'\n若发ACK/NAK，AckNak_Seq_Num = '+nfmFmt(ack)+'（最后连续正确接收序号）\n仅NFM快照；安排反馈不等于已上线路，CRC关系由输入提供。'};
}
function nfmTxInfo(nextText,ackText,reportText,kind){
 const n=nfmHex(nextText),a=nfmHex(ackText),r=nfmHex(reportText);
 if(n===null||a===null||r===null||!['ack','nak'].includes(kind))return {state:'invalid',message:'三个序号都输入000～FFF hex，选择ACK或NAK。'};
 const distance=(n-a+4096)%4096,stall=distance>=2048;
 if(distance<1||distance>2048)return {state:'snapshot-review',distance,message:'模距离='+distance+'，超出本工具连续窗口模型。请核对快照和真实缓冲区，不由此直接判定硬件故障。'};
 const outstanding=distance-1,advance=(r-a+4096)%4096,valid=advance===0||advance<=outstanding;
 if(!valid)return {state:'protocol-error',distance,outstanding,stall,message:'确认序号既不等于ACKD_SEQ，也不在本快照未确认窗口；丢弃DLLP，报告Data Link Protocol Error。'};
 const remaining=outstanding-advance,start=remaining?(r+1)%4096:null,items=Array.from({length:Math.min(remaining,8)},(_,i)=>(r+1+i)%4096),replay=kind==='nak'&&remaining>0;
 return {state:'valid',distance,outstanding,stall,advance,remaining,start,items,replay,progress:advance>0,message:'模距离='+distance+'，推导未确认数='+outstanding+'；接受新TLP'+(stall?'暂停（≥2048）':'未因该公式暂停')+'。\n累计释放 '+advance+' 项；ACKD_SEQ → '+nfmFmt(r)+'；剩余 '+remaining+' 项。\n'+(advance?'有确认进展：重置REPLAY_NUM / REPLAY_TIMER。':'重复确认：没有确认进展，不因它本身重置进展计数。')+'\n'+(kind==='nak'?(remaining?'NAK启动重放，从 '+nfmFmt(start)+' 开始；NAK序号本身已正确收到。':'NAK触发时缓冲区为空，重放立即结束。'):'ACK不单独启动重放。')+'\n仅一致连续窗口快照；不推演正在重放时的并发事件或物理缓存容量。'};
}
function nfmRxPlot(){return '<figure class="note"><figcaption>原创NFM接收判定流程 · 按顺序检查</figcaption><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px">'+['① PHY错误？ → 丢弃/必要时NAK','② 有效Nullify？ → 无错误丢弃','③ LCRC错误？ → Bad TLP/必要时NAK','④ 序号=预期？ → 交事务层，预期+1','⑤ 模距离≤2048？ → 重复包，ACK','⑥ 其余失序 → NAK标志抑制重复反馈'].map(x=>'<span style="border:1px solid #547b76;padding:10px;border-radius:6px">'+esc(x)+'</span>').join('')+'</div><p>该图为查询分支导读；反馈实际发送还受仲裁与计时条件约束。</p></figure>';}
function nfmTxPlot(r){return '<figure class="note"><figcaption>确认后剩余队列 · 最旧在左，最多预览8项</figcaption><div style="display:flex;flex-wrap:wrap;gap:8px">'+(r.items||[]).map(x=>'<span style="border:1px solid #547b76;padding:8px">'+nfmFmt(x)+'</span>').join('')+'</div><p>'+esc(r.state==='valid'?(r.remaining?'共'+r.remaining+'项；'+(r.replay?'NAK从左端开始重放。':'ACK后等待后续确认。'):'无剩余项。'):'请先提供模型内有效快照。')+'</p></figure>';}
function nfmRxExplorer(){const r=nfmRxInfo('001','FFF','no','no','normal','no');return '<section class="flit-explorer"><h4>NFM接收快照查询（Base6.0/7.0）</h4><div class="flit-controls">'+powerInput('nrx-next','NEXT_RCV_SEQ (hex)','001')+powerInput('nrx-received','ReceivedSeq (hex)','FFF')+powerSelect('nrx-phy','正在收TLP时PHY错误',[['no','无'],['yes','有']])+powerSelect('nrx-null','Nullified指示',[['no','否'],['yes','是']])+powerSelect('nrx-crc','收到的LCRC与正常计算结果',[['normal','相同'],['inverse','逻辑反值'],['bad','两者皆非']])+powerSelect('nrx-nak','NAK_SCHEDULED',[['no','0'],['yes','1']])+'</div><pre id="nrx-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre>'+nfmRxPlot()+'</section>';}
function nfmTxExplorer(){const r=nfmTxInfo('002','FFE','000','nak');return '<section class="flit-explorer"><h4>NFM发送确认窗口（Base6.0/7.0）</h4><div class="flit-controls">'+powerInput('ntx-next','NEXT_TRANSMIT_SEQ (hex)','002')+powerInput('ntx-ackd','ACKD_SEQ (hex)','FFE')+powerInput('ntx-report','AckNak_Seq_Num (hex)','000')+powerSelect('ntx-kind','反馈类型',[['nak','NAK'],['ack','ACK']])+'</div><pre id="ntx-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="ntx-plot">'+nfmTxPlot(r)+'</div></section>';}
function r59Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x).value;if(id.startsWith('nrx-'))document.getElementById('nrx-result').textContent=nfmRxInfo(v('nrx-next'),v('nrx-received'),v('nrx-phy'),v('nrx-null'),v('nrx-crc'),v('nrx-nak')).message;if(id.startsWith('ntx-')){const r=nfmTxInfo(v('ntx-next'),v('ntx-ackd'),v('ntx-report'),v('ntx-kind'));document.getElementById('ntx-result').textContent=r.message;document.getElementById('ntx-plot').innerHTML=nfmTxPlot(r);}}
document.addEventListener('input',r59Refresh);document.addEventListener('change',r59Refresh);


function dlFeatureRegisterInfo(capText,statusText,revision,mode,highestText){
 const parse=x=>/^(?:0x)?[0-9a-f]{1,8}$/i.test(String(x).trim())?parseInt(String(x).trim().replace(/^0x/i,''),16):null;
 const cap=parse(capText),status=parse(statusText),highest=Number(highestText);
 if(cap===null||status===null||!['6','7'].includes(revision)||!['nfm','fm'].includes(mode)||![8,16,32,64,128].includes(highest))return {state:'invalid',message:'寄存器输入1～8位hex，选择6.0/7.0、模式与最高共同速率。'};
 const local=cap&0x7fffff,remote=status&0x7fffff,enabled=!!(cap>>>31),valid=!!(status>>>31),scaled=valid&&!!(local&1)&&!!(remote&1),params=v=>({scaled:!!(v&1),ready:!!(v&2),vc:(v>>2)&7,latency:(v>>5)&7,half:(v>>8)&3}),l=params(local),r=params(remote),notes=[];
 const reservedMask=revision==='6'?0x7fff00:0x7ffc00;
 if((local&reservedMask)||(remote&reservedMask))notes.push('存在该修订中保留的Feature字段位；仅显示，不据此推导唯一错误。');
 if(((cap>>>23)&255)||((status>>>23)&255))notes.push('寄存器[30:23]为保留域；不当额外能力。');
 if(mode==='nfm'&&((local|remote)&(revision==='6'?0xfc:0x3fc)))notes.push('线上NFM参数表要求[7:2]以及7.0[9:8]为0；部分寄存器表称Reserved，保留两层语义，不直接裁定实现违规。');
 if(mode==='fm'&&!scaled)notes.push('FM所需Scaled FC支持/激活条件未由这些输入证明；请复核快照与模式，不强制改寄存器。');
 const latency6=['<1 μs','1～<2 μs','2～<4 μs','4～<8 μs','8～<16 μs','16～<32 μs','32～64 μs','>64 μs'],latency7=['<1 μs','<2 μs','<4 μs','<8 μs','<16 μs','<32 μs','<64 μs','>64 μs'];
 const packing=revision==='7'&&mode==='fm'&&valid?(r.half===0?8:highest>=128?4:8):null;
 if(revision==='7'&&mode==='fm'&&valid&&r.half>=2)notes.push('远端每半Flit参数为保留1xb，按接收处理规则等同01b；不是合法发送许可。');
 const desc=(x,label)=>label+'：Scaled支持='+Number(x.scaled)+'；Immediate Readiness='+Number(x.ready)+(mode==='nfm'&&!x.ready?'（清0可能未全部Ready，也可能未提供）':'')+'；Extended VC Count原始值='+x.vc+'；L0p编码='+x.latency+'；Half Flit编码='+x.half;
 const message=['+04h Enable='+Number(enabled)+'（HwInit）；+08h Remote Valid='+Number(valid)+'（RO）。','Scaled FC满足所列激活条件：'+(scaled?'是':'否')+'；只有bit0按双方支持判断，Parameter不统一按位AND。',desc(l,'Local'),valid?desc(r,'Remote'):'Remote Valid=0：远端参数无效，不作打包/延迟结论。',mode==='fm'?'Local L0p '+(revision==='7'?latency7[l.latency]:latency6[l.latency])+(valid?'；Remote '+(revision==='7'?latency7[r.latency]:latency6[r.latency]):'')+'。000不能证明支持L0p；7.0寄存器是典型提示，§3.3仍列旧区间。':'NFM不解释L0p和VC/半Flit参数为有效值。',packing===null?'无可用的7.0 FM远端每半Flit结论。':'本端TX遵从远端RX要求：每Half Flit最多 '+packing+' 个非NOP TLP（包括partial TLP）；按最高共同速率 '+highest+' GT/s判定，非当前速率。',...notes,'查询不证明交换或InitFC已实际完成；不解析CRC，不写硬件，不推导L0p硬时限。'].join('\n');
 return {state:'decoded',enabled,valid,scaled,local:l,remote:r,packing,notes,message};
}
function fcInitTraceInfo(text,mode,vcText){
 const vc=Number(vcText),events=String(text).trim()?String(text).trim().toUpperCase().split(/\s+/):[];
 if(!['nfm','fm'].includes(mode)||!Number.isInteger(vc)||vc<0||vc>7||events.length>64||events.some(x=>!/^[12][DS]-(P|NP|CPL)$/.test(x)&&!['TLP','UPDATE','OPT','DOWN','DISABLE'].includes(x)))return {state:'invalid',rows:[],message:'最多64个事件；使用1D-P/1D-NP/1D-CPL、2D-*，FM可用S；另有TLP UPDATE OPT DOWN DISABLE。'};
 const required=mode==='nfm'?['D-P','D-NP','D-CPL']:['D-P','D-NP','D-CPL','S-P','S-NP','S-CPL'],seen=new Set(),rows=[];let phase='FC_INIT1',fi1=false,fi2=false;
 for(const token of events){const before=phase;let action='';
  if(token==='DOWN'){phase='DL_Inactive';seen.clear();fi1=false;fi2=false;action='PHY LinkUp=0：终止初始化，清本模型记录；其它DL状态也需按Inactive清理。';}
  else if(phase==='DL_Inactive'||phase==='ABORTED'){action='当前过程已终止；本工具不自动建新轮初始化。';}
  else if(token==='DISABLE'){if(vc===0)action='DISABLE中止规则限VC1～7；VC0未据此停止，本工具不推演软件复位。';else{phase='ABORTED';action='VC1～7被禁用：终止本VC初始化。';}}
  else if(phase==='READY'){action='初始化已完成；不按新InitFC重装信用，本工具不推演正常流控。';}
  else if(/^[12][DS]-/.test(token)){
   const kind=token.slice(1);
   if(mode==='nfm'&&kind[0]==='S')action='NFM不使用Shared FC；不把该事件计入所需集合。';
   else if(before==='FC_INIT1'){seen.add(kind);action='记录该类别Header/Data与适用Scale；'+(token[0]==='2'?'InitFC2也可提供FI1初值。':'');if(required.every(x=>seen.has(x))){fi1=true;phase='FC_INIT2';action+='收齐，FI1=1 → FC_INIT2；本事件不再跨阶段复用。';}}
   else {action='FC_INIT2忽略收到的FC/Scale初值；';if(token[0]==='2'){fi2=true;phase='READY';action+='任意本VC InitFC2置FI2并完成。';}else action+='InitFC1不置FI2。';}
  }else if(before==='FC_INIT2'&&(['TLP','UPDATE'].includes(token)||(mode==='fm'&&token==='OPT'))){fi2=true;phase='READY';action='收到完成证据，FI2=1；解除本VC初始化门控，仍需其它正常发送条件。';}
  else action=token==='OPT'&&mode==='nfm'?'NFM无此Optimized_Update_FC完成事件。':'当前阶段该事件不补FI1初值，也不完成本VC初始化。';
  rows.push({token,before,after:phase,action});
 }
 const missing=required.filter(x=>!seen.has(x)),blocked=phase!=='READY',dlStatus=vc===0?(phase==='FC_INIT2'||phase==='READY'?'DL_Up':'DL_Down'):null;
 return {state:'trace',phase,fi1,fi2,rows,missing,blocked,dlStatus,message:'VC'+vc+' / '+mode.toUpperCase()+'：'+phase+'；FI1='+Number(fi1)+'，FI2='+Number(fi2)+'。\n'+(dlStatus?'VC0对应状态输出：'+dlStatus+'。':'这是附加VC初始化，不据它改写整条链路DL_Up输出。')+'\n'+(blocked?'本过程尚未解除该VC发送门控。':'已解除初始化门控；不表示信用、排序、Replay等其它条件都满足。')+'\n'+(phase==='FC_INIT1'?'FI1尚缺：'+missing.join('、'):phase==='FC_INIT2'?'已收齐初值，但仍等后续FI2事件。':'')+'\n从本VC FC_INIT1开始，仅接收事件模型；不验发送顺序、时戳/34μs、CRC、初始分配矩阵和数值。'};
}
function dlFeatureRegisterExplorer(){const r=dlFeatureRegisterInfo('80000123','80000123','7','fm','128');return '<section class="flit-explorer"><h4>Data Link Feature寄存器查询</h4><div class="flit-controls">'+powerInput('dlf-cap','+04h Capabilities DWORD (hex)','80000123')+powerInput('dlf-status','+08h Status DWORD (hex)','80000123')+powerSelect('dlf-revision','Base修订',[['7','7.0'],['6','6.0']])+powerSelect('dlf-mode','当前模式',[['fm','FM'],['nfm','NFM']])+powerSelect('dlf-highest','最高共同速率（非当前）',[['128','128 GT/s'],['64','64 GT/s'],['32','32 GT/s'],['16','16 GT/s'],['8','8 GT/s']])+'</div><pre id="dlf-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre></section>';}
function fcInitTracePlot(r){return '<figure class="note"><figcaption>原创接收事件轨迹 · 每格按事件前阶段处理</figcaption><div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:12px">'+(r.rows||[]).map((x,i)=>'<div style="border:1px solid #547b76;border-radius:6px;padding:10px;flex:1 1 220px"><b>'+(i+1)+'. '+esc(x.token)+'</b><p>'+esc(x.before)+' → '+esc(x.after)+'</p><p>'+esc(x.action)+'</p></div>').join('')+'</div><p>VC0：FC_INIT1为DL_Down；FC_INIT2已是DL_Up但本VC仍禁止发TLP；FI2后解除初始化门控。</p></figure>';}
function fcInitTraceExplorer(){const text='1D-P 1D-NP 1D-CPL 2D-P',r=fcInitTraceInfo(text,'nfm','0');return '<section class="flit-explorer"><h4>InitFC接收事件轨迹（Base6.0/7.0）</h4><div class="flit-controls">'+powerSelect('fci-mode','模式',[['nfm','NFM：三份Dedicated'],['fm','FM：Dedicated＋Shared六份']])+powerSelect('fci-vc','初始化VC',Array.from({length:8},(_,i)=>[String(i),'VC'+i]))+'</div><label for="fci-events">事件（空白分隔；1/2阶段、D/S池、P/NP/CPL）</label><textarea id="fci-events" rows="3" spellcheck="false" style="width:100%;box-sizing:border-box;font:inherit">'+text+'</textarea><p>FM例：1D-P 1D-NP 1D-CPL 1S-P 1S-NP 1S-CPL 2S-P</p><pre id="fci-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="fci-plot">'+fcInitTracePlot(r)+'</div></section>';}
function r60Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x).value;if(id.startsWith('dlf-'))document.getElementById('dlf-result').textContent=dlFeatureRegisterInfo(v('dlf-cap'),v('dlf-status'),v('dlf-revision'),v('dlf-mode'),v('dlf-highest')).message;if(id.startsWith('fci-')){const r=fcInitTraceInfo(v('fci-events'),v('fci-mode'),v('fci-vc'));document.getElementById('fci-result').textContent=r.message;document.getElementById('fci-plot').innerHTML=fcInitTracePlot(r);}}
document.addEventListener('input',r60Refresh);document.addEventListener('change',r60Refresh);


function irqParseHex(text,bits){const t=String(text).trim();if(!/^(?:0x)?[0-9a-f]+$/i.test(t)||t.replace(/^0x/i,'').length>Math.ceil(bits/4))return null;const n=BigInt('0x'+t.replace(/^0x/i,''));return n<(1n<<BigInt(bits))?n:null;}
function irqHex(n,width=8){return '0x'+BigInt(n).toString(16).toUpperCase().padStart(width,'0');}
function msiMessageInfo(controlText,lowText,highText,dataText,extText,indexText,maskText,bme,msix){
 const cc=irqParseHex(controlText,16),lo=irqParseHex(lowText,32),hi=irqParseHex(highText,32),dd=irqParseHex(dataText,16),ee=irqParseHex(extText,16),mask=irqParseHex(maskText,32),index=Number(indexText);
 if([cc,lo,hi,dd,ee,mask].some(x=>x===null)||!/^\d+$/.test(String(indexText))||!Number.isInteger(index)||index>31||![bme,msix].every(x=>['yes','no'].includes(x)))return {state:'invalid',message:'Control/Data/Ext输入≤4位hex，地址与Mask≤8位hex；索引为0～31十进制，选择BME及MSI-X Enable。'};
 const c=Number(cc),mmc=(c>>1)&7,mme=(c>>4)&7,a64=!!(c&128),pvm=!!(c&256),edmCap=!!(c&512),edmEnable=!!(c&1024),enabled=!!(c&1),notes=[],issues=[];
 if(mmc>5||mme>5)return {state:'reserved-encoding',mmc,mme,message:'MMC或MME为保留编码6/7，不计算向量或发送结果。'};
 const requested=2**mmc,allocated=2**mme,lowMask=allocated-1;
 if(mme>mmc)issues.push('MME分配数大于MMC请求数，行为未定义');
 if(index>=allocated)issues.push('索引不在已分配0～'+(allocated-1)+'范围');
 if(edmEnable&&!edmCap)issues.push('Extended Data Enable=1但能力=0，与字段硬连0要求矛盾');
 if((Number(dd)&lowMask)!==0)issues.push('基准Data低MME位未清0：按7.0显式条件行为未定义');
 if(enabled&&msix==='yes')issues.push('MSI与MSI-X同时Enable，行为未定义；不选择优先赢家');
 if(lo&3n)notes.push('低地址输入[1:0]非0；MSI寄存器这些位实际读0/写无效，计算按0处理。');
 if(!a64&&hi!==0n)notes.push('32bit布局不存在Upper Address，输入高DW被忽略。');
 if(!pvm&&mask!==0n)notes.push('没有PVM能力，Mask字段不存在；输入Mask不参与门控。');
 if(c&0xf800)notes.push('Control[15:11]保留，未赋业务含义。');
 const layout={dataOffset:a64?12:8,extOffset:a64?14:10,maskOffset:pvm?(a64?16:12):null,pendingOffset:pvm?(a64?20:16):null};
 const address=((a64?hi:0n)<<32n)|(lo&0xfffffffcn),payload=((edmEnable?ee:0n)<<16n)|BigInt((Number(dd)&(0xffff^lowMask))|index),masked=pvm&&!!((mask>>BigInt(index))&1n);
 let state=issues.length?'configuration-conflict':!enabled?'disabled':bme==='no'?'bme-blocked':masked?'masked':'eligible';
 const action={ 'configuration-conflict':'存在上述配置/输入冲突，不给出正常发送许可。',disabled:'MSI未启用，不发送。','bme-blocked':'BME=0，禁止发起MSI内存写；不自动推导Pending变化。',masked:'该已分配向量被Mask；若原本需要通知，按PVM规则置Pending。',eligible:'所列MSI门控满足；是否有事件、链路/排序等其它条件仍需另查。'}[state];
 const message=['MMC='+mmc+' → 请求'+requested+'；MME='+mme+' → 分配'+allocated+'；索引='+index+'。','MSI Enable='+Number(enabled)+'，64bit Cap='+Number(a64)+'，PVM='+Number(pvm)+'，Ext Cap/Enable='+Number(edmCap)+'/'+Number(edmEnable)+'。','相对能力：Data+'+layout.dataOffset.toString(16).toUpperCase()+'h；Ext位置+'+layout.extOffset.toString(16).toUpperCase()+'h（仅能力有效时可用）'+(pvm?'；Mask+'+layout.maskOffset.toString(16).toUpperCase()+'h；Pending+'+layout.pendingOffset.toString(16).toUpperCase()+'h。':'；无Mask/Pending寄存器。'),...issues,...notes,issues.length?'冲突输入下的地址/Data不作为合法消息输出。':'候选消息：Address='+irqHex(address,16)+'；Payload='+irqHex(payload)+'（1DW，四个BE均1）。',action,'仅输入快照和算式；不读写硬件，不承诺IRQ/ISR响应，也不把Mask解除当事件清除。'].join('\n');
 return {state,mmc,mme,requested,allocated,index,enabled,a64,pvm,edmCap,edmEnable,masked,layout,addressHex:issues.length?null:irqHex(address,16),payloadHex:issues.length?null:irqHex(payload),issues,notes,message};
}
function msixLocationInfo(controlText,tableText,pbaText,tableBaseText,pbaBaseText,indexText,vectorText,bme,msi,pending){
 const cc=irqParseHex(controlText,16),tt=irqParseHex(tableText,32),pp=irqParseHex(pbaText,32),tb=irqParseHex(tableBaseText,64),pb=irqParseHex(pbaBaseText,64),vv=irqParseHex(vectorText,32),index=Number(indexText);
 if([cc,tt,pp,tb,pb,vv].some(x=>x===null)||!/^\d+$/.test(String(indexText))||!Number.isInteger(index)||index>2047||![bme,msi,pending].every(x=>['yes','no'].includes(x)))return {state:'invalid',message:'Control≤4位hex，定位DW/Vector Control≤8位hex，资源基址≤16位hex；索引为0～2047十进制。'};
 const c=Number(cc),n=(c&0x7ff)+1,tableBir=Number(tt&7n),pbaBir=Number(pp&7n),enabled=!!(c&0x8000),functionMask=!!(c&0x4000),entryMask=!!(vv&1n),masked=functionMask||entryMask,issues=[],notes=[];
 if(tableBir>5||pbaBir>5)issues.push('BIR=6/7保留，不能定位普通Type0资源');
 if(index>=n)issues.push('索引超出Table Size的0～'+(n-1)+'范围');
 if(tableBir===pbaBir&&tb!==pb)issues.push('同一BIR却给了不同资源基址，输入不一致');
 const tableBase=tb+(tt&0xfffffff8n),pbaBase=pb+(pp&0xfffffff8n),tableBytes=BigInt(n*16),pbaBytes=BigInt(Math.ceil(n/64)*8),entry=tableBase+BigInt(index*16),qword=pbaBase+BigInt(Math.floor(index/64)*8),dword=pbaBase+BigInt(Math.floor(index/32)*4);
 if((tableBase&7n)||(pbaBase&7n))issues.push('解析后的Table/PBA基址不满足QWORD对齐，检查已去属性位的资源输入');
 if(tableBase+tableBytes>(1n<<64n)||pbaBase+pbaBytes>(1n<<64n))issues.push('资源相加超过64bit地址范围');
 if(tableBase<pbaBase+pbaBytes&&pbaBase<tableBase+tableBytes)issues.push('计算出的Table与PBA范围重叠，不满足结构分离要求');
 if(enabled&&msi==='yes')issues.push('MSI与MSI-X同时Enable，行为未定义；不选优先赢家');
 if(c&0x3800)notes.push('Control[13:11]保留，不当成表项数。');
 let state=issues.length?'configuration-conflict':!enabled?'disabled':bme==='no'?'bme-blocked':masked?'masked':pending==='yes'?'schedule-pending':'no-pending';
 const action={'configuration-conflict':'有上述输入/配置冲突，不给出正常发送许可。',disabled:'MSI-X未启用，不发送。','bme-blocked':'BME=0，禁止MSI-X内存写；Pending后果不在本快照裁决。',masked:'有效屏蔽=1；若原本要发通知，必须维护该项Pending。','schedule-pending':'所列门控满足且Pending=1，应调度该项通知；实际发出后清Pending。','no-pending':'所列门控满足、输入Pending=0；不能据此判断未来事件或其它队列。'}[state];
 const location={tableBase:irqHex(tableBase,16),pbaBase:irqHex(pbaBase,16),entry:irqHex(entry,16),vectorControl:irqHex(entry+12n,16),qword:irqHex(qword,16),qwordBit:index%64,dword:irqHex(dword,16),dwordBit:index%32,tableBytes:Number(tableBytes),pbaBytes:Number(pbaBytes)};
 const message=['Table Size='+(n-1)+' → '+n+'项；索引='+index+'；Table BIR='+tableBir+'，PBA BIR='+pbaBir+'。',...issues,'Table基址='+location.tableBase+'，长度'+location.tableBytes+'B；该Entry='+location.entry+'；Vector Control='+location.vectorControl+'。','PBA基址='+location.pbaBase+'，长度'+location.pbaBytes+'B；QWORD地址='+location.qword+' bit'+location.qwordBit+'；DWORD地址='+location.dword+' bit'+location.dwordBit+'。','MSI-X Enable='+Number(enabled)+'；Function Mask='+Number(functionMask)+'；Entry Mask='+Number(entryMask)+'；有效屏蔽='+Number(masked)+'；Pending输入='+Number(pending==='yes')+'。',action,...notes,'表/PBA地址是设备资源位置，不是中断消息目的地址。PBA只读观察，不写1清除。仅普通Type0已解析资源模型，不验证资源长度/页隔离、EA/VF或全部发送条件。'].join('\n');
 return {state,n,index,tableBir,pbaBir,enabled,functionMask,entryMask,masked,issues,notes,location,message};
}
function msiMessageExplorer(){const r=msiMessageInfo('01A5','FEE00000','00000000','0040','0000','3','00000008','yes','no');return '<section class="flit-explorer"><h4>MSI消息形成与门控（6.0/7.0；低位规则按7.0显式约束）</h4><div class="flit-controls">'+powerInput('irqm-control','MSI Control (hex)','01A5')+powerInput('irqm-low','Address Low (hex)','FEE00000')+powerInput('irqm-high','Address High (hex)','00000000')+powerInput('irqm-data','Message Data (hex)','0040')+powerInput('irqm-ext','Extended Data (hex)','0000')+powerInput('irqm-index','向量索引（十进制）','3')+powerInput('irqm-mask','Mask Bits (hex，仅PVM有效)','00000008')+powerSelect('irqm-bme','Command BME',[['yes','1'],['no','0']])+powerSelect('irqm-msix','同一Function MSI-X Enable',[['no','0'],['yes','1']])+'</div><pre id="irqm-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><p>默认地址仅作算式输入示意；PCIe不规定所有平台采用这个CPU地址布局。没有任何硬件读写。</p></section>';}
function msixLocationPlot(r){if(!r.location)return '';const x=r.location;return '<figure class="note"><figcaption>原创MSI-X资源定位图 · 与消息目的地址分开</figcaption><div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:12px">'+[['Table资源',x.tableBase,x.tableBytes+' B'],['Entry '+r.index,x.entry,'4 DW / 16 B'],['PBA QWORD',x.qword,'bit '+x.qwordBit]].map(a=>'<div style="border:1px solid #547b76;border-radius:6px;padding:10px"><b>'+esc(a[0])+'</b><p style="overflow-wrap:anywhere">'+esc(a[1])+'</p><p>'+esc(a[2])+'</p></div>').join('')+'</div><p>通知真正的Address/Data另从Entry内容读出；本图只算设备内的位置。</p></figure>';}
function msixLocationExplorer(){const r=msixLocationInfo('8081','00002002','00004002','90000000','90000000','129','00000001','yes','no','yes');return '<section class="flit-explorer"><h4>MSI-X定位与有效屏蔽（普通Type0资源模型）</h4><div class="flit-controls">'+powerInput('irqx-control','MSI-X Control (hex)','8081')+powerInput('irqx-table','Table Offset/BIR DWORD (hex)','00002002')+powerInput('irqx-pba','PBA Offset/BIR DWORD (hex)','00004002')+powerInput('irqx-tbase','Table所选资源基址（已解析hex）','90000000')+powerInput('irqx-pbase','PBA所选资源基址（已解析hex）','90000000')+powerInput('irqx-index','Entry索引（十进制）','129')+powerInput('irqx-vector','Vector Control (hex)','00000001')+powerSelect('irqx-bme','Command BME',[['yes','1'],['no','0']])+powerSelect('irqx-msi','同一Function MSI Enable',[['no','0'],['yes','1']])+powerSelect('irqx-pending','该项Pending输入',[['yes','1'],['no','0']])+'</div><pre id="irqx-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="irqx-plot">'+msixLocationPlot(r)+'</div></section>';}
function r61Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x).value;if(id.startsWith('irqm-'))document.getElementById('irqm-result').textContent=msiMessageInfo(v('irqm-control'),v('irqm-low'),v('irqm-high'),v('irqm-data'),v('irqm-ext'),v('irqm-index'),v('irqm-mask'),v('irqm-bme'),v('irqm-msix')).message;if(id.startsWith('irqx-')){const r=msixLocationInfo(v('irqx-control'),v('irqx-table'),v('irqx-pba'),v('irqx-tbase'),v('irqx-pbase'),v('irqx-index'),v('irqx-vector'),v('irqx-bme'),v('irqx-msi'),v('irqx-pending'));document.getElementById('irqx-result').textContent=r.message;document.getElementById('irqx-plot').innerHTML=msixLocationPlot(r);}}
document.addEventListener('input',r61Refresh);document.addEventListener('change',r61Refresh);


function iatuWindowInfo(mode,baseText,limitText,targetText,addressText,bytesText,granuleText){
 const base=irqParseHex(baseText,64),limit=irqParseHex(limitText,64),target=irqParseHex(targetText,64),address=irqParseHex(addressText,64),bytes=Number(bytesText),granule=Number(granuleText);
 if([base,limit,target,address].some(x=>x===null)||!['outbound','inbound-address','inbound-bar'].includes(mode)||!/^\d+$/.test(String(bytesText))||!Number.isInteger(bytes)||bytes<1||bytes>1048576||![4096,65536].includes(granule))return {state:'invalid',message:'地址输入≤16位hex；长度1～1048576十进制；选择模式与模型粒度。1MiB是工具输入限制。'};
 if(limit<base)return {state:'invalid',message:'Limit小于Base，无法构成含端点窗口。'};
 const size=limit-base+1n,last=address+BigInt(bytes)-1n,issues=[],notes=[],max64=1n<<64n;
 if(last>=max64)return {state:'invalid',message:'访问末地址超过64bit范围，不回卷计算。'};
 if(size>0x100000000n||(base>>32n)!==(limit>>32n))issues.push('本模型不覆盖跨4GiB源窗口或Increase Region Size');
 const align=mode==='inbound-bar'?size:BigInt(granule);
 if(mode==='inbound-bar'&&(size&(size-1n))!==0n)issues.push('简化BAR窗口大小必须为2的幂');
 if(size<BigInt(granule)||base%align!==0n||target%align!==0n||(limit+1n)%align!==0n)issues.push('窗口大小/基址/Target/Limit低位不满足所选模型对齐条件');
 if(target+size>max64||(target>>32n)!==((target+size-1n)>>32n))issues.push('Target窗口跨模型4GiB最大Region边界；硬件可能回卷，本工具不以普通加法外推');
 if(issues.length)return {state:'outside-model',issues,message:issues.join('\n')+'\n这些是本查询模型/输入边界，需核真实生成参数和模式；不直接裁定设备违规。'};
 if((address>>12n)!==(last>>12n))notes.push('该字节范围跨4KB，仅作地址映射；不是一个可直接发出的合法单burst/TLP。');
 if(address<base||address>limit)return {state:'no-match',size:Number(size),message:(mode==='inbound-bar'?'所设BAR窗口未覆盖起址；真实BAR过滤/错误责任另查。':'该单区域未命中；6.50a默认iATU地址可不翻译，后续过滤/路由另查。')+'\n不把未命中等同统一UR，也不当成访问权限通过。'};
 const offset=address-base,mapped=target+offset;
 if(last>limit)return {state:'span-crosses-window',offsetHex:irqHex(offset,1),mappedStart:irqHex(mapped,16),message:'访问起址命中，但末地址'+irqHex(last,16)+'超过Limit。不能按一个区域给出整个范围安全结果，需先拆分或核实际decomposition；不声称硬件对整段做了同一翻译。'};
 const mappedEnd=mapped+BigInt(bytes)-1n;
 return {state:'mapped',mode,size:Number(size),offsetHex:irqHex(offset,1),sourceStart:irqHex(address,16),sourceEnd:irqHex(last,16),mappedStart:irqHex(mapped,16),mappedEnd:irqHex(mappedEnd,16),notes,message:'单区域窗口 '+irqHex(base,16)+'～'+irqHex(limit,16)+'，共'+size+' byte。\n窗口偏移='+irqHex(offset,1)+'；Target='+irqHex(target,16)+'。\n映射后首址='+irqHex(mapped,16)+'；末址='+irqHex(mappedEnd,16)+'。\n'+notes.join('\n')+'\n仅普通单窗口算式；未验证区域使能、优先级、真实BAR/属性匹配、iATU旁路、权限或目标可达。'};
}
function hdmaRemotePlanInfo(direction,mode,sarText,darText,lengthText,mpsText,mrrsText,supportedText,bypass){
 const sar=irqParseHex(sarText,64),dar=irqParseHex(darText,64),length=Number(lengthText),mps=Number(mpsText),mrrs=Number(mrrsText),supported=Number(supportedText),sizes=[128,256,512,1024,2048,4096];
 if([sar,dar].some(x=>x===null)||!['write','read'].includes(direction)||!['direct','ll'].includes(mode)||!['yes','unknown'].includes(bypass)||!/^\d+$/.test(String(lengthText))||!Number.isInteger(length)||length<1||length>1048576||![mps,mrrs,supported].every(x=>sizes.includes(x)))return {state:'invalid',items:[],message:'SAR/DAR≤16位hex；长度1～1048576十进制；MPS/MRRS/Supported从所列值选择。'};
 if(mps>supported)return {state:'invalid',items:[],message:'配置MPS大于输入的MPS Supported，先核对能力/配置。'};
 if((sar&3n)||(dar&3n)||length%4)return {state:'outside-tool-scope',items:[],message:'本候选模型只处理DW对齐SAR/DAR与4byte整数倍长度；不是声称HDMA硬件不支持byte对齐。'};
 const max64=1n<<64n;if(sar+BigInt(length)>max64||dar+BigInt(length)>max64)return {state:'invalid',items:[],message:'源或目的末地址超过64bit范围，不回卷规划。'};
 const remote=direction==='write'?dar:sar,local=direction==='write'?sar:dar,cap=direction==='write'?mps:Math.min(mrrs,supported),items=[];let left=length,offset=0;
 while(left){const at=remote+BigInt(offset),amount=Math.min(left,cap,4096-Number(at&4095n));items.push({index:items.length,remote:irqHex(at,16),local:irqHex(local+BigInt(offset),16),bytes:amount});offset+=amount;left-=amount;}
 return {state:'planned',direction,mode,cap,length,count:items.length,items,localStart:irqHex(local,16),remoteStart:irqHex(remote,16),remoteEnd:irqHex(remote+BigInt(length)-1n,16),wireAddressKnown:bypass==='yes',message:(direction==='write'?'Write：SAR本地→本地Manager读→远端MWr到DAR。':'Read：远端MRd从SAR取数→CplD→本地Manager写DAR。')+'\n本地首址='+irqHex(local,16)+'；远端生成侧范围='+irqHex(remote,16)+'～'+irqHex(remote+BigInt(length)-1n,16)+'。\n候选单请求上限='+cap+' B（'+(direction==='write'?'配置MPS':'min(MRRS,MPS Supported)')+'）；4KB处分段，共'+items.length+'份候选。\n'+(bypass==='yes'?'用户输入声明已确保ATU不改地址；此假设下可作为候选线上地址。':'ATU映射未确认：这里只是生成侧地址，不能认定实际线上目的地址。')+'\n'+(mode==='ll'?'LL输入为数据元素SAR/DAR；不把LLP和描述符读取算入这些数据请求。':'Direct上下文仅表示一块任务；不输出Doorbell/寄存器写值。')+'\n候选不是实际发包预测：本地AXI拆分、Tag/信用、对齐和仲裁可增加分段；不验证DMA权限、同步或真实完成。'};
}
function axiFourPathDiagram(){const paths=[['本地写远端','本地应用 AW/W → 控制器Subordinate → Outbound iATU → PCIe MWr → 远端','本地B不等于远端业务确认'],['本地读远端','本地应用 AR → Subordinate → MRd → 远端CplD → 重组 → Subordinate R','Tag/上下文匹配原请求'],['远端写本地','远端MWr → BAR/过滤/Inbound iATU → Manager AW/W → 本地目标','本地B不形成普通MWr Completion'],['远端读本地','远端MRd → BAR/过滤/iATU → Manager AR → 本地R → CplD返回','读请求及返回数据方向相反']];return '<figure class="note"><figcaption>原创四向请求/响应路径 · Controller 6.50a</figcaption>'+paths.map(x=>'<div style="border-left:3px solid #31766b;padding:10px;margin-top:12px"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p><p>'+esc(x[2])+'</p></div>').join('')+'</figure>';}
function hdmaDescriptorDiagram(){return '<figure class="note"><figcaption>原创数据元素组成图 · 6 DW / 24 B · 不是TLP</figcaption><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px;margin-top:12px">'+[['+00h','Control，完整32bit未逐位展开'],['+04h','Transfer Size'],['+08h','SAR Low'],['+0Ch','SAR High'],['+10h','DAR Low'],['+14h','DAR High']].map(x=>'<div style="border:1px solid #547b76;border-radius:6px;padding:12px"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p><small>1 DWORD / 32 bit</small></div>').join('')+'</div><p>从+00h到+14h按DWORD偏移递增；这是字段组成，不规定主机CPU字节序。Link元素须按另一套语义解析，不能照此搬运。</p></figure>';}
function iatuWindowPlot(r){if(r.state!=='mapped')return '';return '<figure class="note"><figcaption>原创单窗口映射 · 字节偏移不变</figcaption><div style="display:flex;flex-wrap:wrap;gap:10px">'+[['原始首址',r.sourceStart],['窗口内偏移',r.offsetHex],['转换后首址',r.mappedStart]].map(x=>'<div style="border:1px solid #547b76;padding:10px;border-radius:6px;overflow-wrap:anywhere"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p></div>').join('')+'</div></figure>';}
function hdmaRemotePlanPlot(r){return '<figure class="note"><figcaption>候选远端请求预览 · 最多显示前8份，不是实际抓包</figcaption><div style="display:flex;flex-wrap:wrap;gap:8px">'+(r.items||[]).slice(0,8).map(x=>'<div style="border:1px solid #547b76;padding:10px;border-radius:6px"><b>#'+x.index+' · '+x.bytes+' B</b><p>'+esc(x.remote)+'</p></div>').join('')+'</div></figure>';}
function iatuWindowExplorer(){const r=iatuWindowInfo('outbound','80000000','8000FFFF','0000000120000000','80000040','64','4096');return '<section class="flit-explorer"><h4>iATU普通窗口算式（6.50a受限模型）</h4><div class="flit-controls">'+powerSelect('atuw-mode','模式',[['outbound','Outbound Address'],['inbound-address','Inbound Address'],['inbound-bar','Inbound BAR（输入为假定BAR范围）']])+powerInput('atuw-base','Base (hex)','80000000')+powerInput('atuw-limit','Limit（含端点hex）','8000FFFF')+powerInput('atuw-target','Target (hex)','0000000120000000')+powerInput('atuw-address','访问首址 (hex)','80000040')+powerInput('atuw-bytes','长度byte（十进制）','64')+powerSelect('atuw-granule','模型最小粒度',[['4096','4 KiB'],['65536','64 KiB']])+'</div><pre id="atuw-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="atuw-plot">'+iatuWindowPlot(r)+'</div></section>';}
function hdmaRemotePlanExplorer(){const r=hdmaRemotePlanInfo('write','direct','40000000','0000000120000FC0','512','256','512','512','yes');return '<section class="flit-explorer"><h4>HDMA候选远端包规划（6.50a，DW对齐模型）</h4><div class="flit-controls">'+powerSelect('hdp-direction','通道方向',[['write','Write：本地→远端'],['read','Read：远端→本地']])+powerSelect('hdp-mode','上下文来源',[['direct','Direct'],['ll','LL数据元素']])+powerInput('hdp-sar','SAR (hex)','40000000')+powerInput('hdp-dar','DAR (hex)','0000000120000FC0')+powerInput('hdp-length','长度byte（十进制，≤1MiB）','512')+powerSelect('hdp-mps','配置MPS',[['256','256 B'],['128','128 B'],['512','512 B'],['1024','1024 B'],['2048','2048 B'],['4096','4096 B']])+powerSelect('hdp-mrrs','配置MRRS',[['512','512 B'],['128','128 B'],['256','256 B'],['1024','1024 B'],['2048','2048 B'],['4096','4096 B']])+powerSelect('hdp-supported','MPS Supported（能力）',[['512','512 B'],['128','128 B'],['256','256 B'],['1024','1024 B'],['2048','2048 B'],['4096','4096 B']])+powerSelect('hdp-bypass','已确保ATU不改远端地址？',[['yes','是，作为输入假设'],['unknown','尚未确认/可能翻译']])+'</div><pre id="hdp-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="hdp-plot">'+hdmaRemotePlanPlot(r)+'</div></section>';}
function r62Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x).value;if(id.startsWith('atuw-')){const r=iatuWindowInfo(v('atuw-mode'),v('atuw-base'),v('atuw-limit'),v('atuw-target'),v('atuw-address'),v('atuw-bytes'),v('atuw-granule'));document.getElementById('atuw-result').textContent=r.message;document.getElementById('atuw-plot').innerHTML=iatuWindowPlot(r);}if(id.startsWith('hdp-')){const r=hdmaRemotePlanInfo(v('hdp-direction'),v('hdp-mode'),v('hdp-sar'),v('hdp-dar'),v('hdp-length'),v('hdp-mps'),v('hdp-mrrs'),v('hdp-supported'),v('hdp-bypass'));document.getElementById('hdp-result').textContent=r.message;document.getElementById('hdp-plot').innerHTML=hdmaRemotePlanPlot(r);}}
document.addEventListener('input',r62Refresh);document.addEventListener('change',r62Refresh);
function renderStageReviews(){return (DB.maintenance.stageReviews||[]).map(r=>'<article class="list-row" id="review-'+esc(r.id)+'"><span class="tag">'+esc(r.edition)+' · '+r.completedRounds+'/'+r.completedRounds+' 已总结</span><h2>'+esc(r.title)+'</h2><p>'+esc(r.result)+'</p><div class="table-wrap"><table class="generation-table"><thead><tr><th>轮次</th><th>已补内容/入口</th><th>仍需继续</th></tr></thead><tbody>'+r.rounds.map(x=>'<tr><th scope="row">'+esc(x.edition)+'</th><td>'+esc(x.topic)+'<p>'+x.featureIds.map(id=>'<a class="tag" href="#feature/'+id+'">'+esc(DB.features.find(f=>f.id===id)?.name||String(id))+'</a>').join(' ')+'</p></td><td>'+esc(x.remaining)+'</td></tr>').join('')+'</tbody></table></div><h3>下一阶段优先级与原因</h3>'+r.nextPriorities.map(x=>'<div class="note"><b>'+esc(x.title)+'</b><p>'+esc(x.reason)+'</p><p>'+x.featureIds.map(id=>'<a class="tag" href="#feature/'+id+'">'+esc(DB.features.find(f=>f.id===id)?.name||String(id))+'</a>').join(' ')+'</p></div>').join('')+'<p class="muted">'+esc(r.limitations)+'</p></article>').join('');}
function renderPriorityProgress(){const m=DB.maintenance,p=m.priorityPlan,c=m.reviewCadence;if(!p||!c)return '';const reviewed=!!c.lastReviewEdition;return '<section class="list-row" id="priority-progress"><span class="tag">'+(reviewed?'上阶段4/4已总结 · 新阶段 ':'阶段 ')+Number(c.completedSinceReview)+' / '+Number(c.intervalRounds)+'</span><h2>当前优先级与阶段总结</h2><p>每 '+Number(c.intervalRounds)+' 个实质常规轮次总结一次；距下一次还有 '+Number(c.nextReviewAfterRounds)+' 轮。'+(reviewed?'最近总结 '+esc(c.lastReviewEdition)+'；下一次预计 '+esc(c.nextExpectedReview):'首次预计 '+esc(c.firstExpectedReview))+'。</p><p>'+esc(c.countingRule)+'</p></section>'+renderStageReviews()+'<section class="list-row"><h2>已采用路线与保留缺口</h2>'+p.map(x=>'<article class="note"><h3>'+esc(x.title)+' <span class="tag">'+esc(x.status)+'</span></h3><p>'+esc(x.remaining)+'</p><p>'+x.featureIds.map(id=>'<a class="tag" href="#feature/'+id+'">'+esc(DB.features.find(f=>f.id===id)?.name||String(id))+'</a>').join(' ')+'</p></article>').join('')+'</section>';}

