function r34DependencyDiagram(abort=false){return `<figure style="overflow-x:auto"><figcaption>${abort?'原创：MAC取消与内部评估完成是两件事':'原创：恢复证据逐关口检查'}</figcaption><svg viewBox="0 0 920 240" role="img" aria-label="${abort?'MAC中止后，PMA仍可完成，返回反馈由MAC忽略':'静态配置、动态校准、PHY有效、MAC对齐和链路可用分别确认'}" style="width:100%;min-width:570px;background:#f4f7fb;color:#142333"><g fill="#e1ecf7" stroke="#28649b"><rect x="20" y="30" width="250" height="70" rx="8"/><rect x="335" y="30" width="250" height="70" rx="8"/><rect x="650" y="30" width="250" height="70" rx="8"/></g><path d="M270 65H335 M585 65H650" stroke="#28649b" stroke-width="3"/><g fill="currentColor" font-size="19" text-anchor="middle"><text x="145" y="60">${abort?'MAC取消评估':'静态配置已回填'}</text><text x="145" y="85">${abort?'不再接受本次反馈':'不是动态校准有效'}</text><text x="460" y="60">${abort?'PMA可继续最后评估':'匹配且有效的校准结果'}</text><text x="460" y="85">${abort?'PCS仍可返回完成':'保存域与配置需可信'}</text><text x="775" y="60">${abort?'MAC忽略迟到/重叠值':'PHY有效 → MAC对齐'}</text><text x="775" y="85">${abort?'不能变回成功结果':'仍要完成协议训练'}</text><text x="460" y="155">${abort?'直接打断PMA请求可能留下非最优设置':'不同对象各有完成证据，不能合并成一个Done'}</text><text x="460" y="195">${abort?'消息确认、评估完成、结果被采用：分开观察':'产品内部状态 ≠ PIPE操作完成 ≠ Link/DLL可用'}</text></g></svg><p>原创概念示意，不按时间比例，也不定义完整硬件异常恢复流程。</p></figure>`;}
