function cfgLaneGroupText(o){const r=cfgLaneGroupInfo(o);if(!r)return '输入无效：按物理Lane顺序列0～31或x，最多32项；起止是有效的0基索引，最大远端编号0～31。';return `候选宽度=${r.width}；${r.hasHole?'跨无TS1空洞':'没有无TS1空洞'}；${r.edge?'包含0或最大端点':'缺少0/最大端点'}；${r.range?'编号未超给定最大值':'编号超过给定最大值'}；${r.unique?'组内编号唯一':'组内编号重复'}；${r.widthOk?'m−1≤n−1':'m−1超远端最大编号'}。${r.necessary?'所列分组必要条件满足':'所列分组条件不满足'}；仍未检查支持宽度、2份连续TS、Link匹配、skew和全状态出口。`;}
function sharedLimitExplorer(){const o={applied:true,fm:true,dynamic:true,extended:true,localEnabled:true,remoteEnabled:true,localBase:6,localGran:0,remoteBase:5,remoteGran:2};return `<div class="flit-explorer"><div class="flit-controls">${[['applied','采用本地ECN对应规则'],['fm','当前Link为Flit Mode'],['dynamic','Dynamic Usage Limit能力'],['extended','Extended Shared Limit能力'],['localEnabled','软件有效限额Enable'],['remoteEnabled','已收到有效RX推荐Enable']].map(([k,t])=>pwrBool('sflimit-'+k,t,o[k])).join('')}${[['localBase','软件base / 12.5%'],['remoteBase','对端推荐base / 12.5%']].map(([k,t])=>pwrSelect('sflimit-'+k,t,Array.from({length:8},(_,i)=>[String(i),String(i)]),String(o[k]))).join('')}${[['localGran','软件粒度'],['remoteGran','对端推荐粒度']].map(([k,t])=>pwrSelect('sflimit-'+k,t,[['0','00b +0'],['1','01b 保留'],['2','10b +6.25%'],['3','11b 保留']],String(o[k]))).join('')}</div><p id="sflimit-result" class="protocol-query-output" aria-live="polite">${esc(sharedLimitText(o))}</p><p>软件输入是已确定的有效寄存器约束；不替多种VC/MFVC结构自动决定归属。关闭限额显示100%只是本机制不约束，不是保证有100%的Credit。</p></div>`;}
