function receiveDispositionInfo(o){if(!o||!['malformed','uio-drop','reserved-fm','ecrc'].includes(o.kind)||['bufferKnown','vcUsable','flitSupported','returnCompletion'].some(k=>typeof o[k]!=='boolean'))return null;if(o.kind==='malformed')return {drop:true,fc:!o.bufferKnown||!o.vcUsable?'no-update':'choice',completion:'not-normal-path'};if(o.kind==='uio-drop')return {drop:true,fc:'prior-processing',completion:'no-promise'};if(o.kind==='reserved-fm')return {drop:true,fc:'update-recommended-path',completion:'ur-compatibility'};return {drop:null,fc:'not-defined-here',completion:!o.returnCompletion?'not-returned':o.flitSupported?'ur-required':'older-rule-not-expanded'};}
function receiveDispositionText(o){const r=receiveDispositionInfo(o);if(!r)return '请选择已分类的单一入口和有效开关。';const w={malformed:`Malformed必须丢弃；${r.fc==='no-update'?'缓冲归属歧义或VC未初始化/禁用，不得更新RX FC。':'缓冲归属明确且VC可用，仍允许不更新RX FC；本条不是唯一更新策略。'}不沿正常请求完成路径凭猜测合成UR/CA。`,'uio-drop':'解码UIO Type但不能转发/处理，按专门规则丢弃；不承诺合成完成。FC沿先前处理规则判断，本句不定义所有错误优先级。','reserved-fm':'FM Reserved Request入口：强烈建议更新FC后丢弃；兼容性脚注仍许可按UR处理，不改写成唯一动作。',ecrc:`ECRC Check Failed：是否返回完成由实现决定；${!o.returnCompletion?'当前选择不返回。':o.flitSupported?'Flit Mode Supported能力为1，若返回须按MUST@FLIT给UR状态。':'MUST@FLIT能力前提不成立，较早实现规则须另核；本工具不凭当前模式替代能力判定。'}`};return w[o.kind]+' 仅选定入口查询；不判断并发形成/路由/ACS/IDE等错误的总优先级。';}
function uioReadCoverageInfo(o){
 if(!o||!Number.isInteger(o.start)||o.start<0||o.start%4||!Number.isInteger(o.dw)||o.dw<1||o.dw>1024||o.start+o.dw*4>4096||typeof o.trace!=='string'||o.trace.length>24000)return null;
 let rows;try{rows=JSON.parse(o.trace)}catch{return null}if(!Array.isArray(rows)||rows.length>128)return null;
 const used=new Array(o.dw).fill(0);let completedDW=0,errorDW=0,outsideDW=0,duplicateDW=0,scDW=0;const rank={SC:0,RRS:1,CA:2,UR:3,reserved:3};let status='SC';
 for(const row of rows){if(!row||!Object.prototype.hasOwnProperty.call(rank,row.status)||!Number.isInteger(row.dw)||row.dw<1||row.dw>1024)return null;completedDW+=row.dw;if(rank[row.status]>rank[status])status=row.status==='reserved'?'UR':row.status;if(row.status!=='SC'){errorDW+=row.dw;continue;}if(!Number.isInteger(row.offset)||row.offset<0||row.offset%4||row.offset+row.dw*4>4096)return null;scDW+=row.dw;for(let k=0;k<row.dw;k++){const ix=(row.offset-o.start)/4+k;if(ix<0||ix>=o.dw)outsideDW++;else{if(used[ix]>0)duplicateDW++;used[ix]++;}}}
 const uniqueDW=used.filter(x=>x>0).length;return {completedDW,errorDW,scDW,uniqueDW,duplicateDW,outsideDW,missingSC:o.dw-uniqueDW,status,dwEqual:completedDW===o.dw,overCount:completedDW>o.dw,dataComplete:errorDW===0&&completedDW===o.dw&&uniqueDW===o.dw&&duplicateDW===0&&outsideDW===0};
}
function uioReadCoverageText(o){const r=uioReadCoverageInfo(o);if(!r)return '输入无效：请求须DW对齐且不跨4KB；dw为解码后1～1024；JSON最多128项，status=SC/RRS/CA/UR/reserved，SC另填DW对齐页内offset。';return `期望${o.dw}DW，完成账面${r.completedDW}DW（${r.dwEqual?'仅数值相等':r.overCount?'已超计数':'尚未收齐'}）；SC Payload=${r.scDW}DW，唯一覆盖=${r.uniqueDW}DW，重复=${r.duplicateDW}DW，越界=${r.outsideDW}DW；错误核销=${r.errorDW}DW，归并状态=${r.status}。`+(r.dataComplete?'本模型内成功数据范围已完整覆盖。':r.errorDW?'错误完成无有效Lower Address，不能据它定位错误区间；未成功覆盖的DW也不能一概断言尚未完成。':'仅靠DW和不能证明成功数据完整。')+' 不验证全部形成/RCB/MPS/关联/超时条件。';}
function ebResetWindowInfo(o){if(!o||!['original','serdes'].includes(o.arch)||!Number.isFinite(o.mhz)||o.mhz<=0||o.mhz>100000||!Number.isSafeInteger(o.start)||o.start<0||!Number.isSafeInteger(o.now)||o.now<o.start||['busy','clean'].some(k=>o[k]!==null&&(!Number.isSafeInteger(o[k])||o[k]<o.start||o[k]>o.now))||o.busy!==null&&o.clean!==null&&o.clean<o.busy)return null;if(o.arch==='serdes')return {state:'outside'};const end=o.clean??o.now,cycles=end-o.start;return {state:o.clean!==null?(o.busy===null?'missing-busy':cycles<=16?'within':'late'):cycles<16?'waiting':cycles===16?'boundary':'overdue',cycles,ns:cycles*1000/o.mhz};}
function ebResetWindowText(o){const r=ebResetWindowInfo(o);if(!r)return '输入无效：周期须为同一PCLK基准的非负整数；事件不晚于当前周期，clean不早于首次忙；频率须为合理正数。';if(r.state==='outside')return '本寄存器EB Reset不用于SerDes架构；当前不套用Original PHY的16PCLK模型。';const w={within:'已观察忙及clean恢复，所列先后与≤16PCLK窗口满足。',late:'观察到clean恢复，但超过16PCLK约束。','missing-busy':'存在clean时刻，但缺少忙序列证据，不确认完整复位已完成。',waiting:'尚未观察clean恢复，窗口内等待。',boundary:'到达16PCLK上限仍未观察clean；核对同拍采样，不能宣称完成。',overdue:'已超过16PCLK且未观察clean恢复。'};return `${r.cycles}个PCLK周期；在固定${o.mhz}MHz假设下约${Number(r.ns.toFixed(6))}ns。${w[r.state]}未检查所有RxStatus/RxValid/RxDataValid保持条件和真实指针。`;}
function receiveDispositionExplorer(){const o={kind:'malformed',bufferKnown:false,vcUsable:true,flitSupported:true,returnCompletion:true};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('rdisp-kind','已确定的单一接收问题',[['malformed','Malformed TLP'],['uio-drop','解码UIO但无法处理/转发'],['reserved-fm','Reserved FM Request Type'],['ecrc','ECRC Check Failed']],o.kind)}${[['bufferKnown','缓冲归属明确'],['vcUsable','VC已初始化且启用'],['flitSupported','Flit Mode Supported能力'],['returnCompletion','ECRC路径选择返回完成']].map(([k,t])=>pwrBool('rdisp-'+k,t,o[k])).join('')}</div><p id="rdisp-result" class="protocol-query-output" aria-live="polite">${esc(receiveDispositionText(o))}</p></div>`;}
function uioReadCoverageExplorer(){const o={start:256,dw:8,trace:JSON.stringify([{status:'SC',offset:256,dw:4},{status:'SC',offset:256,dw:4}],null,2)};return `<div class="flit-explorer"><div class="flit-controls"><label>读请求页内起点 / byte<input id="ucover-start" type="number" min="0" max="4092" step="4" value="256"></label><label>请求已解码DW数<input id="ucover-dw" type="number" min="1" max="1024" value="8"></label><label class="power-trace-label">完成JSON：status、dw；SC另填页内offset<textarea id="ucover-trace" rows="12" maxlength="24000">${esc(o.trace)}</textarea></label></div><p id="ucover-result" class="protocol-query-output" aria-live="polite">${esc(uioReadCoverageText(o))}</p><p>默认示例故意重复前4DW，显示“总量相等”为什么不等于“地址覆盖完整”。错误条目不使用offset定位数据。</p></div>`;}
function ebResetWindowExplorer(){const o={arch:'original',mhz:250,start:0,busy:2,clean:16,now:16};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('ebreset-arch','接口架构',[['original','Original PIPE'],['serdes','SerDes PIPE']],o.arch)}${[['mhz','固定PCLK频率 / MHz',250],['start','已确定的操作触发周期',0],['busy','首次1xx忙周期（未知留空）',2],['clean','clean恢复周期（未知留空）',16],['now','当前周期',16]].map(([k,t,n])=>`<label>${esc(t)}<input id="ebreset-${k}" type="number" min="0" step="${k==='mhz'?'any':'1'}" value="${n}"></label>`).join('')}</div><p id="ebreset-result" class="protocol-query-output" aria-live="polite">${esc(ebResetWindowText(o))}</p>${ebResetDiagram()}</div>`;}
function ebResetDiagram(){return `<figure style="overflow-x:auto"><figcaption>原创：EB恢复的控制、忙与clean证据</figcaption><svg viewBox="0 0 900 225" role="img" aria-label="EB触发后以PCLK计时，1xx忙期间移动指针，16周期内释放状态并恢复clean" style="width:100%;min-width:570px;background:#f4f7fb;color:#142333"><g fill="currentColor" font-size="18"><text x="25" y="30">PHY接受EB复位触发</text><text x="340" y="30">RxStatus=1xx：忙与指针恢复</text><text x="670" y="30">clean恢复</text></g><path d="M50 75H850 M50 160H850" stroke="#235c90" stroke-width="2"/><path d="M50 130H210V95H760V130H850" fill="none" stroke="#158577" stroke-width="3"/><g fill="currentColor" font-size="18"><text x="45" y="65">起点0</text><text x="190" y="195">保持适用有效指示；不是消息Ack</text><text x="665" y="65">≤16 PCLK</text><text x="45" y="220">不按比例；复位不恢复已丢失数据，也不表示整个Link重新就绪。</text></g></svg></figure>`;}
for(const type of ['input','change'])document.addEventListener(type,e=>{const id=e.target.id||'';if(id.startsWith('rdisp-')){const o={kind:$('#rdisp-kind').value};for(const k of ['bufferKnown','vcUsable','flitSupported','returnCompletion'])o[k]=$('#rdisp-'+k).value==='1';$('#rdisp-result').textContent=receiveDispositionText(o);}if(id.startsWith('ucover-')){const o={trace:$('#ucover-trace').value};for(const k of ['start','dw'])o[k]=$('#ucover-'+k).value.trim()?Number($('#ucover-'+k).value):NaN;$('#ucover-result').textContent=uioReadCoverageText(o);}if(id.startsWith('ebreset-')){const o={arch:$('#ebreset-arch').value};for(const k of ['mhz','start','busy','clean','now'])o[k]=$('#ebreset-'+k).value.trim()?Number($('#ebreset-'+k).value):['busy','clean'].includes(k)?null:NaN;$('#ebreset-result').textContent=ebResetWindowText(o);}});

function detectResultInfo(o){if(!o||!['pipe-p1','pipe-p2','pma'].includes(o.iface)||!['P0','P0s','P1','P2'].includes(o.state)||typeof o.done!=='boolean'||typeof o.p2!=='boolean'||!Number.isInteger(o.code)||o.code<0||o.code>7)return null;const product=o.iface==='pma';if(product&&o.code>1)return {state:'bad-code'};if(product&&!['P1','P2'].includes(o.state)||!product&&(o.iface==='pipe-p1'?o.state!=='P1':o.state!=='P2'))return {state:'outside'};if(o.iface==='pipe-p2'&&!o.p2)return {state:'unsupported'};if(!o.done)return {state:'unqualified'};if(!product&&![0,3].includes(o.code))return {state:'bad-code'};return {state:o.code===(product?1:3)?'present':'absent',completion:product?'product-ack':o.iface==='pipe-p1'?'pulse':'held'};}
function detectResultText(o){const r=detectResultInfo(o);if(!r)return '输入无效：选择已定义接口/状态，编码为0～7整数。';const t={outside:'所选状态不属于该检测入口；PMA检测请求在P0/P0s须撤销。',unsupported:'PIPE PCIe P2检测为可选；未确认支持，不能套用该完成契约。',unqualified:'完成证据尚未有效：不能凭当前结果编码判断是否存在Receiver。','bad-code':'该接口的检测结果编码不适用；检查是否混用PIPE三位状态与产品1-bit结果。',present:'已在有效完成窗口观测到Receiver存在；这不证明CDR/TS训练或LinkUp完成。',absent:'已在有效完成窗口观测到未检测出Receiver；不等于已证明物理上永久不存在设备。'};return t[r.state]+(r.completion==='pulse'?' P1为单PCLK PhyStatus完成脉冲。':r.completion==='held'?' P2保持PhyStatus/结果，直到请求撤销。':r.completion==='product-ack'?' 产品结果在Ack有效时采样，不直接当作PIPE RxStatus。':'');}
function detectResultExplorer(){const o={iface:'pipe-p1',state:'P1',done:false,p2:false,code:0};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('detr-iface','检测接口',[['pipe-p1','PIPE PCIe P1'],['pipe-p2','PIPE PCIe P2（可选）'],['pma','Gen6 PMA 3.02a']],o.iface)}${pwrSelect('detr-state','当前状态',['P0','P0s','P1','P2'].map(x=>[x,x]),o.state)}${pwrSelect('detr-done','检测完成指示',[['0','未有效'],['1','PhyStatus / 产品Ack已有效']],'0')}${pwrSelect('detr-p2','PIPE P2检测能力',[['0','未确认支持'],['1','已确认支持']],'0')}<label>结果编码（十进制；PIPE 011b填3）<input id="detr-code" type="number" min="0" max="7" step="1" value="0"></label></div><p id="detr-result" class="protocol-query-output" aria-live="polite">${esc(detectResultText(o))}</p><figure style="overflow-x:auto"><figcaption>原创：完成窗口限定检测结果含义（不按时间比例）</figcaption><svg viewBox="0 0 900 200" role="img" aria-label="先请求检测，再在完成有效窗口采样结果，最后释放请求；检测完成不等于LinkUp" style="width:100%;min-width:600px;background:#f4f7fb;color:#142333"><g fill="currentColor" font-size="18"><text x="20" y="30">启动检测请求</text><text x="310" y="30">完成指示有效 → 采样结果</text><text x="700" y="30">撤销请求</text><text x="20" y="105">PIPE P1：单拍PhyStatus</text><text x="20" y="140">PIPE P2：保持完成/结果至请求释放</text><text x="20" y="175">PMA 3.02a：Ack有效时结果可信；1/0不等于PIPE 011/000</text></g><path d="M40 65H850" stroke="#158577" stroke-width="4"/><path d="M835 55L850 65L835 75" fill="none" stroke="#158577" stroke-width="4"/></svg></figure></div>`;}
function completeGateInfo(o){if(!o||!['dsp','usp'].includes(o.role)||!['6.0','7.0'].includes(o.version)||![2.5,5,8,16,32,64,128].includes(o.rate)||o.version==='6.0'&&o.rate>64||!Array.isArray(o.rx)||!o.rx.length||o.rx.length>32||o.rx.some(x=>!Number.isSafeInteger(x)||x<0)||!Number.isSafeInteger(o.tx)||o.tx<0||!Number.isSafeInteger(o.fallback)||o.fallback<0||o.fallback>255||typeof o.timeout!=='boolean')return null;const normal=o.rx.every(x=>x>=8)&&o.tx>=16;if(normal)return {state:o.timeout?'coincident':'normal-idle'};if(!o.timeout)return {state:'waiting',minRx:Math.min(...o.rx),tx:o.tx};return {state:o.rate>=8&&o.fallback<255?'timeout-idle':'timeout-detect'};}
function completeGateText(o){const r=completeGateInfo(o);if(!r)return '输入无效：本模型仅Base6.0/7.0，6.0不接受128GT/s；每Lane接收数/发送数为非负整数，回退计数0～255。';const t={'coincident':'正常门槛与超时同时被标记：先核实际事件先后及同拍处理，本模型不臆定二者优先级。','normal-idle':'所列正常门槛满足：每条发送TS2的Lane合格连续接收≥8，首收后发送≥16，可按正常分支进入Configuration.Idle。','waiting':`仍等待正常门槛：最少Lane连续接收${r.minRx}，首收后已发送${r.tx}。`,'timeout-idle':'正常门槛未齐；2ms超时后，≥8GT/s且回退计数<FFh，走有限回退至Configuration.Idle。','timeout-detect':'正常门槛未齐；2ms超时后按所列速率/回退计数回Detect。'};return t[r.state]+' Upstream发送数按连续TS2输入；合格接收数已包含编号/Data Rate/适用Retimer字段条件。还需对应收尾动作和其它序列/计时规则，不直接宣告L0。';}
function completeGateExplorer(){const o={version:'7.0',role:'dsp',rate:8,rx:[8,7],tx:16,fallback:0,timeout:false};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('cfgc-version','Base版本',[['6.0','6.0'],['7.0','7.0']],o.version)}${pwrSelect('cfgc-role','本端角色',[['dsp','Downstream'],['usp','Upstream']],o.role)}${pwrSelect('cfgc-rate','当前速率 / GT/s',[2.5,5,8,16,32,64,128].map(x=>[String(x),String(x)]),'8')}<label>各发送Lane合格连续TS2数（逗号分隔）<input id="cfgc-rx" value="8,7"></label><label>首收TS2后发送数（USP须连续）<input id="cfgc-tx" type="number" min="0" step="1" value="16"></label><label>idle_to_rlock_transitioned（十进制）<input id="cfgc-fallback" type="number" min="0" max="255" step="1" value="0"></label>${pwrSelect('cfgc-timeout','2ms超时',[['0','尚未超时'],['1','已确认超时']],'0')}</div><p id="cfgc-result" class="protocol-query-output" aria-live="polite">${esc(completeGateText(o))}</p><figure style="overflow-x:auto"><figcaption>原创：Complete出口分支（省略字段解码和收尾动作）</figcaption><svg viewBox="0 0 920 220" role="img" aria-label="全发送Lane收8并且首收后发16走正常Idle；否则等待2ms，低速或FF回Detect，高速且小于FF有限回退Idle" style="width:100%;min-width:640px;background:#f4f7fb;color:#142333"><g fill="currentColor" font-size="18"><text x="20" y="40">全发送Lane收8 且 首收后发16？</text><text x="550" y="40">是 → 正常Configuration.Idle</text><text x="20" y="95">否：未到2ms → 继续等待</text><text x="20" y="145">已到2ms：≥8GT/s 且 回退计数&lt;FFh</text><text x="550" y="145">是 → 有限回退Idle</text><text x="550" y="190">否 → Detect</text></g><path d="M375 35H535 M375 140H535" stroke="#158577" stroke-width="3"/></svg></figure></div>`;}
for(const type of ['input','change'])document.addEventListener(type,e=>{const id=e.target.id||'';if(id.startsWith('detr-')){const o={iface:$('#detr-iface').value,state:$('#detr-state').value,done:$('#detr-done').value==='1',p2:$('#detr-p2').value==='1',code:$('#detr-code').value.trim()?Number($('#detr-code').value):NaN};$('#detr-result').textContent=detectResultText(o);}if(id.startsWith('cfgc-')){const parts=$('#cfgc-rx').value.split(',');const o={version:$('#cfgc-version').value,role:$('#cfgc-role').value,rate:Number($('#cfgc-rate').value),timeout:$('#cfgc-timeout').value==='1',rx:parts.every(x=>x.trim())?parts.map(Number):[]};for(const k of ['tx','fallback'])o[k]=$('#cfgc-'+k).value.trim()?Number($('#cfgc-'+k).value):NaN;$('#cfgc-result').textContent=completeGateText(o);}});

function blockedErrorInfo(o){if(!o||!['6.0','7.0'].includes(o.version)||!['acs','atomic','ide'].includes(o.kind)||!['posted','np','uio'].includes(o.request)||!['local','rp-validation','rciep-validation'].includes(o.location))return null;if(o.kind==='atomic')return o.request==='np'?{state:'ur',error:'AtomicOp Egress Blocked',owner:'目标Egress Port'}:{state:'outside'};if(o.kind==='ide')return o.version==='7.0'?{state:'no-completion',error:'Misrouted IDE TLP',owner:'检测到所列错路的Port'}:{state:'unread-version'};const owner={'local':'检测ACS组件（通常代作Completer）','rp-validation':'经入Root Port作为Completer','rciep-validation':'关联RCEC作为Completer'}[o.location];if(o.version==='6.0'&&o.request==='uio')return {state:'unread-version'};return {state:o.request==='posted'?'posted-no-completion':'ca',error:'ACS Violation',owner};}
function blockedErrorText(o){const r=blockedErrorInfo(o);if(!r)return '输入无效：选择已定义版本、错误、请求种类和检测位置。';if(r.state==='outside')return 'AtomicOp是Non-Posted请求；所选Posted/UIO不属于AtomicOp Egress Blocked入口。';if(r.state==='unread-version')return '当前版本/组合未由本查询所引正文确认；不把Base7的UIO/IDE专门规则反填Base6。';const t={ur:'返回UR Completion；本地记AtomicOp Egress Blocked，不按普通UR错误设置Unsupported Request Detected。',ca:'返回CA Completion；本地记ACS Violation，不把它改记Completer Abort错误。','posted-no-completion':'普通Posted请求没有对应逐笔Completion；仍需按ACS错误规则记录/处理。','no-completion':'所列IDE错路入口不得转发/发送IDE TLP；NP/UIO也不返回Completion。'};return `${r.owner}；${t[r.state]} 当前错误身份：${r.error}。这是已经分类的单一入口，不裁定并发错误优先级、实际消息使能或完整日志序列。`;}
function blockedErrorExplorer(){const o={version:'7.0',kind:'acs',request:'uio',location:'local'};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('blk-version','所核Base版本',[['6.0','6.0'],['7.0','7.0']],o.version)}${pwrSelect('blk-kind','已经确定的单一错误',[['acs','ACS Violation'],['atomic','AtomicOp Egress Blocked'],['ide','Flow-Through IDE错路（所列入口）']],o.kind)}${pwrSelect('blk-request','请求种类',[['posted','普通Posted'],['np','Non-Posted（AtomicOp选此）'],['uio','UIO（包括写）']],o.request)}${pwrSelect('blk-location','ACS拒绝位置（仅ACS使用）',[['local','本地ACS检测'],['rp-validation','RC验证拒绝：请求经RP来'],['rciep-validation','RC验证拒绝：请求从RCiEP来']],o.location)}</div><p id="blk-result" class="protocol-query-output" aria-live="polite">${esc(blockedErrorText(o))}</p><figure><figcaption>原创：Base7完成状态与本地根因分层</figcaption><svg viewBox="0 0 720 270" role="img" aria-label="ACS违规NP或UIO返回CA，本地记ACS；Atomic出口阻断返回UR，本地记Atomic；所列IDE错路不回完成" style="width:100%;background:#f4f7fb;color:#142333"><g fill="currentColor" font-size="21"><text x="22" y="40">已分类的单一入口</text><text x="22" y="95">ACS：NP / UIO → CA → 本地ACS Violation</text><text x="22" y="150">Atomic出口阻断 → UR → 本地Atomic错误</text><text x="22" y="205">所列IDE错路 → 不返回NP / UIO完成</text><text x="22" y="250">返回状态 ≠ 本地AER错误名称；不裁定并发优先级</text></g></svg></figure></div>`;}
function blockedAerInfo(o){if(!o||['status','mask','severity'].some(k=>!Number.isSafeInteger(o[k])||o[k]<0||o[k]>0xffffffff))return null;return [{bit:21,name:'ACS Violation'},{bit:24,name:'AtomicOp Egress Blocked'}].map(x=>({...x,detected:!!((o.status>>>x.bit)&1),masked:!!((o.mask>>>x.bit)&1),fatal:!!((o.severity>>>x.bit)&1)}));}
function blockedAerText(o){const a=blockedAerInfo(o);if(!a)return '输入无效：三份值须为32-bit无符号十六进制数（可带0x，最多8位）。';return a.map(x=>`${x.name} bit${x.bit}：Status=${+x.detected}（${x.detected?'已记录检测':'未置位，不能证明过去从未发生'}）；Mask=${+x.masked}（${x.masked?'屏蔽该Function的消息与相关Header/Prefix/FEP记录':'未屏蔽，仍需其它上报条件'}）；Severity=${+x.fatal}（${x.fatal?'Fatal':'Non-Fatal'}）。`).join(' ')+' 快照不读取硬件、不推断同一次事件；Status适用位写1清，Mask不是解除阻断控制。';}
function blockedAerDiagram(){return `<figure><figcaption>原创：AER每个DWORD中仅展开bit24和bit21；示意非按比例，其余位另查完整定义</figcaption><svg viewBox="0 0 720 150" role="img" aria-label="bit31到25其它字段，bit24 Atomic，bit23到22其它，bit21 ACS，bit20到0其它字段" style="width:100%;background:#f4f7fb;color:#142333"><g stroke="#235c90" stroke-width="2"><rect x="15" y="30" width="160" height="62" fill="#e1e9f2"/><rect x="175" y="30" width="120" height="62" fill="#c1e9dc"/><rect x="295" y="30" width="115" height="62" fill="#e1e9f2"/><rect x="410" y="30" width="115" height="62" fill="#c1e9dc"/><rect x="525" y="30" width="180" height="62" fill="#e1e9f2"/></g><g fill="currentColor" font-size="20" text-anchor="middle"><text x="95" y="55">31:25</text><text x="95" y="80">其它字段</text><text x="235" y="55">24</text><text x="235" y="80">Atomic</text><text x="352" y="55">23:22</text><text x="352" y="80">其它</text><text x="468" y="55">21</text><text x="468" y="80">ACS</text><text x="615" y="55">20:0</text><text x="615" y="80">其它字段</text><text x="360" y="130">同位不同职责：+04h Status / +08h Mask / +0Ch Severity</text></g></svg></figure>`;}
function blockedAerExplorer(){const o={status:0x01200000,mask:0x00200000,severity:0};return `<div class="flit-explorer"><div class="flit-controls">${[['status','AER +04h Status','01200000'],['mask','AER +08h Mask','00200000'],['severity','AER +0Ch Severity','00000000']].map(([k,t,v])=>`<label>${esc(t)}（十六进制）<input id="baer-${k}" value="${v}" spellcheck="false"></label>`).join('')}</div><p id="baer-result" class="protocol-query-output" aria-live="polite">${esc(blockedAerText(o))}</p>${blockedAerDiagram()}</div>`;}
function uioMatrixInfo(o){if(!o||!['base-pass','ide-pass','dsp-accept','usp-accept'].includes(o.mode)||!Number.isInteger(o.row)||o.row<0||o.row>2||!Number.isInteger(o.col)||o.col<0||o.col>2)return null;const pass=o.mode.endsWith('pass'),ide=o.mode==='ide-pass',usp=o.mode==='usp-accept';const labels=pass?['UIO PR-FC TLP','UIO NPR-FC TLP','UIO Completion']:['UIO Memory Write Request','Other UIO Memory Request','UIO Completion'];const matrix=pass?[['optional','optional','optional'],['optional','optional','optional'],['required','required','optional']]:usp?[['required','required','optional'],['required','required','optional'],['required','required','required']]:[['optional','optional','optional'],['optional','optional','optional'],['required','required','optional']];if(ide)for(let i=0;i<3;i++)matrix[i][i]='forbidden';return {pass,labels,matrix,rule:matrix[o.row][o.col],row:labels[o.row],col:labels[o.col],source:pass?(ide?'Base7表6-37':'Base7表2-43'):usp?'Base7表2-45':'Base7表2-44'};}
function uioMatrixText(o){const r=uioMatrixInfo(o);if(!r)return '输入无效：选择已列四张表及第1～3行/列。';const wording=r.pass?{required:'必须允许行TLP越过列TLP（能力要求，非每拍最高优先级）',optional:'允许越过，也可不越过；不是必须乱序',forbidden:'禁止行TLP越过列TLP'}:{required:'Ingress接收行TLP必须独立于Egress发送列TLP',optional:'该格允许存在或不存在接收依赖，不强制独立'};return `${r.source}：行=${r.row}；列=${r.col}。${wording[r.rule]}。`+(o.mode==='ide-pass'?'只用于所列Flow-Through同Stream及相同Ingress/Egress路径。':'')+' 仅所列矩阵，不证明系统无死锁或全部时序合法。';}
function uioMatrixTable(o){const r=uioMatrixInfo(o);if(!r)return '';const t=r.pass?{required:'必须允许越过',optional:'可越过或不越过',forbidden:'禁止越过'}:{required:'接收必须独立',optional:'可依赖或独立'};return `<div class="table-wrap" tabindex="0" role="region" aria-label="UIO所选矩阵，可横向滚动"><table class="generation-table"><caption>${esc(r.source)} · ${r.pass?'行包越过列包？':'Ingress行接收独立于Egress列发送？'}</caption><thead><tr><th scope="col">行 / 列</th>${r.labels.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.matrix.map((row,i)=>`<tr><th scope="row">${esc(r.labels[i])}</th>${row.map((x,j)=>`<td ${i===o.row&&j===o.col?'style="background:#c1e9dc;color:#142333;font-weight:700"':''}>${t[x]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function uioMatrixExplorer(){const o={mode:'dsp-accept',row:0,col:0};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('umtx-mode','矩阵及适用角色',[['base-pass','基础UIO：越过'],['ide-pass','Flow-Through IDE UIO：越过'],['dsp-accept','Downstream：接收独立性'],['usp-accept','Upstream：接收独立性']],o.mode)}${pwrSelect('umtx-row','选择行（类型见下表）',[['0','第1行'],['1','第2行'],['2','第3行']],'0')}${pwrSelect('umtx-col','选择列（类型见下表）',[['0','第1列'],['1','第2列'],['2','第3列']],'0')}</div><p id="umtx-result" class="protocol-query-output" aria-live="polite">${esc(uioMatrixText(o))}</p><div id="umtx-table">${uioMatrixTable(o)}</div></div>`;}
for(const type of ['input','change'])document.addEventListener(type,e=>{const id=e.target.id||'';if(id.startsWith('blk-')){const o={};for(const k of ['version','kind','request','location'])o[k]=$('#blk-'+k).value;$('#blk-result').textContent=blockedErrorText(o);}if(id.startsWith('baer-')){const o={};for(const k of ['status','mask','severity']){const s=$('#baer-'+k).value.trim();o[k]=/^(?:0x)?[0-9a-f]{1,8}$/i.test(s)?parseInt(s.replace(/^0x/i,''),16):NaN;}$('#baer-result').textContent=blockedAerText(o);}if(id.startsWith('umtx-')){const o={mode:$('#umtx-mode').value,row:Number($('#umtx-row').value),col:Number($('#umtx-col').value)};$('#umtx-result').textContent=uioMatrixText(o);$('#umtx-table').innerHTML=uioMatrixTable(o);}});

function productRxEvaluationInfo(o){if(!o||!['g5','g6'].includes(o.product)||!['fom','direction'].includes(o.feedback)||['p0','eiExit','data','valid','laneBusy','dfeBypass','externalPpm'].some(k=>typeof o[k]!=='boolean'))return null;const blocked=[];if(!o.p0)blocked.push('非P0');if(!o.eiExit)blocked.push('尚未确认出EI');if(!o.data)blocked.push('接收data enable未置位');if(!o.valid)blocked.push('未确认CDR/PHY valid');if(o.laneBusy)blocked.push('普通RX配置仍占用');if(o.product==='g5'){if(o.dfeBypass)blocked.push('Gen5要求DFE bypass为0');if(o.externalPpm)blocked.push('Gen5评估期间外部PPM检测未关闭');if(o.feedback==='direction')blocked.push('Gen5 2.02a不支持Direction Change');}return {state:blocked.length?'blocked':'listed-ready',blocked,unverified:o.product==='g6'?'Gen6所引段未定义旧版同名DFE bypass/外部PPM条件；不是证实可忽略所有监测约束。':''};}
function productRxEvaluationText(o){const r=productRxEvaluationInfo(o);if(!r)return '输入无效：选择所列产品/反馈方式并给出布尔快照。';return (r.state==='blocked'?'所列评估入口尚不满足：'+r.blocked.join('；')+'。':'所列必要前提已满足；可以继续核本产品评估序列。')+(r.unverified?' '+r.unverified:'')+' 这不是完整握手/收敛证明：仍需核RX复位推荐、远端Preset应用等待、请求/Ack有效窗口和结果采样；不能据此判L0或BER。';}
function productRxEvaluationExplorer(){const o={product:'g5',feedback:'fom',p0:true,eiExit:true,data:true,valid:true,laneBusy:false,dfeBypass:true,externalPpm:false};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('prxe-product','产品交付',[['g5','Gen5 PMA 2.02a'],['g6','Gen6 PMA 3.02a']],o.product)}${pwrSelect('prxe-feedback','希望使用的反馈',[['fom','FOM'],['direction','Direction Change']],o.feedback)}${[['p0','RX处于P0'],['eiExit','已检测出Electrical Idle'],['data','接收data enable'],['valid','CDR / PHY valid已有效'],['laneBusy','普通RX配置仍占用'],['dfeBypass','Gen5 DFE bypass'],['externalPpm','Gen5外部PPM检测仍开启']].map(([k,t])=>pwrSelect('prxe-'+k,t,[['0','否 / 0'],['1','是 / 1']],o[k]?'1':'0')).join('')}</div><p id="prxe-result" class="protocol-query-output" aria-live="polite">${esc(productRxEvaluationText(o))}</p>${learningFlow('原创：评估前提、握手完成与Link状态是三层证据', [['① 先核评估入口','产品支持的反馈方式；P0、出EI、data enable和valid。'],['② 再核本次完成','本次请求 → adapt Ack → 在有效窗口采样本次结果。'],['③ 协议状态另核','均衡、Idle握手、L0和Data Link分别取证。8ns复位、2µs等待与评估超时各有起终点。']])}</div>`;}
function cfgIdleInfo(o){const rates=[2.5,5,8,16,32,64,128],modes=['nfm8','nfm130','fm8','fm130','fm1'];if(!o||!['6.0','7.0'].includes(o.version)||!modes.includes(o.mode)||!rates.includes(o.rate)||o.version==='6.0'&&o.rate===128||['deskew','completeTimeout','timeout'].some(k=>typeof o[k]!=='boolean')||!Number.isSafeInteger(o.tx)||o.tx<0||!Number.isSafeInteger(o.counter)||o.counter<0||o.counter>255||!Array.isArray(o.rx)||!o.rx.length||o.rx.length>32||o.rx.some(x=>!Number.isSafeInteger(x)||x<0))return null;const fm=o.mode.startsWith('fm'),low=o.rate<=5;if((o.mode.endsWith('8')&&!low)||(o.mode.endsWith('130')&&![8,16,32].includes(o.rate))||(o.mode==='fm1'&&o.rate<64)||fm&&o.rx.length!==1)return {state:'outside'};if(o.completeTimeout&&low)return {state:'unreachable-entry'};const rxNeed=fm?2:8,txNeed=fm?(o.mode==='fm1'?8:4):16,deskewNeeded=o.mode!=='nfm8',counts=o.rx.every(x=>x>=rxNeed)&&o.tx>=txNeed,normal=counts&&(!deskewNeeded||o.deskew)&&!o.completeTimeout;const info={rxNeed,txNeed,fm,deskewNeeded,counts};if(normal)return {...info,state:o.timeout?'coincident':'l0'};if(!o.timeout)return {...info,state:'wait',reason:o.completeTimeout?'Complete超时入口禁止本正常L0分支':deskewNeeded&&!o.deskew?'未确认deskew先于Data Stream处理':'收/发计数尚不足'};return {...info,state:o.counter<255?'recovery':'detect',nextCounter:o.counter<255?(low?255:o.counter+1):255};}
function cfgIdleText(o){const r=cfgIdleInfo(o);if(!r)return '输入无效：仅Base6/7与所列速率；计数为非负整数，回退计数0～255，FM接收只填一项Flit连续数。';if(r.state==='outside')return '编码/模式与速率或计数维度不匹配：8b/10b用于2.5/5，128b/130b用于8/16/32，1b/1b FM用于64/128。';if(r.state==='unreachable-entry')return '低速Complete超时按前级规则回Detect；不能人工构造低速Complete超时进入本Idle分支。';const unit=r.fm?'IDLE Flit':'Idle Symbol',base=`所列门槛：接收${r.rxNeed}个连续${r.fm?'IDLE Flit':'Symbol Times（每configured Lane）'}，首收后发送至少${r.txNeed}个${unit}。`;const t={l0:'所列正常条件满足，可按本分支转L0；不等于Data Link已初始化。',coincident:'正常条件与超时同时标记：需核实际事件先后/同拍处理，本模型不定义优先级。',wait:'继续等待：'+r.reason+'。',recovery:`已确认最小2ms超时条件，转Recovery.RcvrLock；计数更新为${(r.nextCounter??0).toString(16).toUpperCase().padStart(2,'0')}h。`,detect:'已确认最小2ms超时条件且计数为FFh，转Detect。'};return base+' '+t[r.state]+' 未模拟全部序列解码、定时容差、NoEq字段捕获与所有收尾动作。';}
function cfgIdleExplorer(){const o={version:'7.0',mode:'fm1',rate:64,rx:[2],tx:7,deskew:true,completeTimeout:false,timeout:false,counter:254};return `<div class="flit-explorer"><div class="flit-controls">${pwrSelect('cid-version','Base版本',[['6.0','6.0'],['7.0','7.0']],o.version)}${pwrSelect('cid-mode','编码与模式',[['nfm8','8b/10b NFM'],['nfm130','128b/130b NFM'],['fm8','8b/10b FM'],['fm130','128b/130b FM'],['fm1','1b/1b FM']],o.mode)}${pwrSelect('cid-rate','当前速率 / GT/s',[2.5,5,8,16,32,64,128].map(x=>[String(x),String(x)]),'64')}<label>合格连续接收数（NFM逐Lane逗号分隔；FM单项Flit数）<input id="cid-rx" value="2"></label><label>首收后发送数（单位按模式）<input id="cid-tx" type="number" min="0" step="1" value="7"></label><label>回退计数（十进制0～255）<input id="cid-counter" type="number" min="0" max="255" step="1" value="254"></label>${[['deskew','已确认deskew先于Data Stream处理'],['completeTimeout','从Complete超时进入'],['timeout','已确认到达最小2ms超时条件']].map(([k,t])=>pwrSelect('cid-'+k,t,[['0','否 / 0'],['1','是 / 1']],o[k]?'1':'0')).join('')}</div><p id="cid-result" class="protocol-query-output" aria-live="polite">${esc(cfgIdleText(o))}</p>${learningFlow('原创：Idle的正常出口与有限恢复分支', [['① 按模式核接收和发送','NFM：全Lane接收8个连续Symbol Times，首收后发送16个Idle Symbols。FM：接收2个连续IDLE Flit，首收后按编码发送至少4或8个。'],['② 核正常出口的其它条件','满足适用deskew先后与入口原因条件，才能走正常L0。Complete超时入口不能只凭计数放行。'],['③ 若等待最小超时后的出口','回退计数小于FFh → Recovery.RcvrLock；已为FFh → Detect。正常与超时同拍的优先级另核。']])}</div>`;}
for(const type of ['input','change'])document.addEventListener(type,e=>{const id=e.target.id||'';if(id.startsWith('prxe-')){const o={product:$('#prxe-product').value,feedback:$('#prxe-feedback').value};for(const k of ['p0','eiExit','data','valid','laneBusy','dfeBypass','externalPpm'])o[k]=$('#prxe-'+k).value==='1';$('#prxe-result').textContent=productRxEvaluationText(o);}if(id.startsWith('cid-')){const parts=$('#cid-rx').value.split(',');const o={version:$('#cid-version').value,mode:$('#cid-mode').value,rate:Number($('#cid-rate').value),rx:parts.every(x=>x.trim())?parts.map(Number):[]};for(const k of ['tx','counter'])o[k]=$('#cid-'+k).value.trim()?Number($('#cid-'+k).value):NaN;for(const k of ['deskew','completeTimeout','timeout'])o[k]=$('#cid-'+k).value==='1';$('#cid-result').textContent=cfgIdleText(o);}});

function learningFlow(title,steps){return `<figure style="margin:1rem 0"><figcaption>${esc(title)}</figcaption><div role="group" aria-label="${esc(title)}" style="display:grid;gap:8px;margin-top:12px">${steps.map(([heading,text],i)=>`${i?'<div aria-hidden="true" style="text-align:center;color:#158577;font-size:22px">↓</div>':''}<div style="border:1px solid #cadacf;border-radius:8px;padding:12px;background:#f4f7fb;color:#142333;line-height:1.7;overflow-wrap:anywhere"><strong>${esc(heading)}</strong><div>${esc(text)}</div></div>`).join('')}</div></figure>`;}


// R63: product-specific HDMA snapshot and data-element ownership aids.
function hdmaSnapshotInfo(direction,mode,statusText,intText,poison='unknown',bridge='unknown'){
 const sn=irqParseHex(statusText,32),inn=irqParseHex(intText,32);
 if(sn===null||inn===null||!['read','write'].includes(direction)||!['direct','ll'].includes(mode)||!['yes','no','unknown'].includes(poison)||!['yes','no','unknown'].includes(bridge))return {state:'invalid',message:'请输入32bit hex快照和有效选项。'};
 const status=Number(sn&3n),stop=Number(inn&1n),watermark=Number((inn>>1n)&1n),abort=Number((inn>>2n)&1n),error=Number((inn>>3n)&15n),names=['保留','RUNNING','ABORTED','STOPPED'];
 const errors={0:'NONE',1:'LL_CPL_UR',2:'LL_CPL_CA',3:'LL_CPL_EP',8:'DATA_CPL_TIMEOUT',9:'DATA_CPL_UR',10:'DATA_CPL_CA',11:'DATA_CPL_EP',12:'DATA_MWR'};
 const warnings=[];
 if((sn>>2n)!==0n)warnings.push('STATUS[31:2]保留位非零。');
 if((inn>>7n)!==0n)warnings.push('INT_STATUS[31:7]保留位非零。');
 if(stop&&abort)warnings.push('STOP与ABORT同时置位，不符合所核互斥语义；核采样、地址块及版本。');
 if(!(error in errors))warnings.push('本轮字段表未定义此ERROR编码，不猜补。');
 if(error&&!abort)warnings.push('ERROR非零但ABORT未置位：不能只凭该快照判本次终态，核事件历史/使能。');
 if(status===1&&(stop||abort))warnings.push('RUNNING与停止类事件并存，核旧事件、并发采样及通道选择。');
 if(status===0)warnings.push('STATUS=0保留，不当作IDLE或可启动确认。');
 if(mode==='direct'&&watermark)warnings.push('Direct模式不使用LL Watermark，核历史事件和模式切换。');
 if(direction==='write'&&error===8)warnings.push('Write的超时字段描述与Read适用限制需核，不能推为远端Posted写超时。');
 if(error===11&&poison!=='yes')warnings.push(poison==='no'?'Poison Abort配置关闭，B编码适用条件不满足，核快照。':'B编码受Poison Abort配置限制；当前配置未确认。');
 if(error===12){if(direction==='write')warnings.push('Write DATA_MWR存在Reference/Databook方向冲突；不解作远端MWr回执。');if(bridge!=='yes')warnings.push('DATA_MWR还要求相应AXI Bridge配置，当前未确认满足。');}
 let context='当前快照不足以给出可靠恢复地址或残余长度。';
 if(status===1)context='RUNNING：SAR/DAR/XFERSIZE不作可靠实时进度；LLP仅事件快照。';
 if(status===3)context=mode==='ll'?'STOPPED：可能链表暂空、零搬运或主动停止；结合LLP/原因核上下文。':'STOPPED：结合残量、Stop原因和事件判断；不自动证明远端业务完成。';
 if(status===2){context='ABORTED：终态后核有效上下文，不能无条件直接续传。';if([1,2,3].includes(error))context='ABORTED且描述符装载错误：SAR/DAR/XFERSIZE不作为有效恢复上下文。';if(direction==='read'&&error===12)context='ABORTED且Read本地目标写错误：上下文可能损坏，已写不回滚；LL仅当前元素受影响，不按残量推算成功范围。';}
 const message=['Controller 6.50a · '+direction.toUpperCase()+' / '+mode.toUpperCase(),'STATUS[1:0]='+status+' '+names[status],'STOP='+stop+'；WATERMARK='+watermark+'；ABORT='+abort,'ERROR[6:3]='+irqHex(error,1)+' '+(errors[error]||'未定义编码'),context,...warnings.map(x=>'注意：'+x),'本工具不执行清除/Start；该快照不构成释放缓冲、解除映射或自动重试许可。'].join('\n');
 return {state:'decoded',status,statusName:names[status],stop,watermark,abort,error,errorName:errors[error]||'未定义编码',warnings,context,message};
}
function hdmaDataOwnerInfo(cb,ccs,body,control){
 if(!['0','1'].includes(cb)||!['0','1'].includes(ccs)||!['yes','no'].includes(body)||!['yes','no'].includes(control))return {state:'invalid',message:'请选择有效的周期位和发布前提。'};
 const match=cb===ccs,published=body==='yes'&&control==='yes';let state=!published?(match?'early-consume-risk':'not-published'):(match?'consumer-candidate':'empty');
 const labels={'early-consume-risk':'CB=CCS，但发布前提未满足：可能提前消费半更新元素。','not-published':'CB不等于CCS且发布未完成；尚未交接，不能靠改周期位掩盖内容未就绪。','consumer-candidate':'CB=CCS，发布前提自述满足：本轮可消费候选，不是已完成。','empty':'CB不等于CCS：本轮列表暂空，可导致STOPPED，不是永久结束标记。'};
 return {state,match,published,message:['仅6.50a数据元素，LLP=0；CB='+cb+'，CCS='+ccs,labels[state],'不推导Link/TCB或PCS/~PCS的冲突公式。设备可见顺序、缓存、DMA映射和缓冲所有权仍需平台确认。'].join('\n')};
}
function hdmaBitStrip(title,fields){return '<figure class="note"><figcaption>'+esc(title)+' · 原创32bit字段示意（高位在左）</figcaption><div style="overflow-x:auto"><div style="display:grid;grid-template-columns:repeat(32,minmax(28px,1fr));min-width:896px;margin:12px 0">'+Array.from({length:32},(_,i)=>'<small style="text-align:center;border:1px solid #b8ccc8">'+(31-i)+'</small>').join('')+fields.map(x=>'<div style="grid-column:span '+(x[0]-x[1]+1)+';border:1px solid #72968e;padding:12px 4px;text-align:center;min-height:62px;writing-mode:'+(x[0]===x[1]?'vertical-rl':'horizontal-tb')+'" title="['+x[0]+':'+x[1]+'] '+esc(x[2])+'">'+esc(x[2])+'</div>').join('')+'</div></div><p>窄屏可横向滚动；字段标签与位数对应，不代表字节传输顺序。</p></figure>';}
function hdmaStatusDiagrams(){return hdmaBitStrip('STATUS',[[31,2,'Reserved'],[1,0,'STATUS']])+hdmaBitStrip('INT_STATUS',[[31,7,'Reserved'],[6,3,'ERROR'],[2,2,'ABORT'],[1,1,'WATERMARK'],[0,0,'STOP']]);}
function hdmaSnapshotExplorer(){const r=hdmaSnapshotInfo('read','ll','2','64','yes','yes');return '<section class="flit-explorer"><h4>HDMA快照解码 · 非硬件恢复命令</h4><div class="flit-controls">'+powerSelect('hds-direction','引擎',[['read','Read：远端→本地'],['write','Write：本地→远端']])+powerSelect('hds-mode','模式',[['ll','Linked List'],['direct','Direct']])+powerInput('hds-status','STATUS (hex)','2')+powerInput('hds-int','INT_STATUS (hex)','64')+powerSelect('hds-poison','Poison Abort配置',[['yes','已启用'],['no','未启用'],['unknown','未确认']])+powerSelect('hds-bridge','相关AXI Bridge条件',[['yes','已确认满足'],['no','不满足'],['unknown','未确认']])+'</div><pre class="note" id="hds-result" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre></section>';}
