// R64: PIPE7.1 PCIe rate-change planning and partial-order learning model.
function pipeRatePlanInfo(topology,pstate,ei,standby,rate,pclk,width,rateRule,widthRule){
 const yn=x=>['yes','no'].includes(x),rule=x=>['yes','no','unknown'].includes(x);
 if(!['input','output'].includes(topology)||!['P0','P0s','P1','P2'].includes(pstate)||![ei,standby,rate,pclk,width].every(yn)||![rateRule,widthRule].every(rule))return {state:'invalid',message:'请选择有效的PCIe接口条件。'};
 const notes=['仅PIPE7.1 PCIe模式选定规则；不验证目标Rate/Width/PCLK组合能力、真实波形或LTSSM。'];
 if(rate==='no'&&pclk==='no'&&width==='no')return {state:'no-op',need:'none',entry:null,message:'没有请求任何变更，不启动一轮切速。\n'+notes[0]};
 const failures=[];if(!['P0','P1'].includes(pstate))failures.push('切速入口要求P0或P1。');if(ei!=='yes')failures.push('TxElecIdle必须有效。');if(pstate==='P0'&&standby!=='yes')failures.push('P0还要求RxStandby有效。');if(pstate==='P1')notes.push('P1不额外要求RxStandby；RxStandbyStatus在P1/P2未定义，不轮询它确认切速入口。');
 let need='unresolved',explain='';
 if(rate==='no'){need='not-covered';explain='Rate稳定：表8-3列Not applicable，不能据此裁定独立Width/PCLK变更的许可或握手。';}
 else if(topology==='output'){need='not-applicable';explain='PCLK为PHY输出：不使用输入Ok/Ack；仍等PhyStatus。此legacy分支不证明支持Gen5或更高交付。';}
 else if(pclk==='yes'){need='required';explain='Rate与PCLK Rate都改变：表8-3要求Ok/Ack，不受Width是否改变影响。';}
 else{const rules=width==='yes'?[rateRule,widthRule]:[rateRule];if(rules.includes('yes')){need='required';explain='至少一个适用datasheet参数要求握手。';}else if(rules.includes('unknown')){need='unresolved';explain='PCLK档位不变，但适用datasheet参数未全部确认，不能默认省略。';}else{need='not-required';explain='适用datasheet参数均已确认不要求Ok/Ack；仍须等待本次PhyStatus完成。';}}
 const entry=failures.length===0,state=!entry?'blocked':need==='not-covered'?'not-covered':need==='unresolved'?'unresolved':'planned';
 const message=['入口：'+(entry?'所列门控满足':'不满足'),...failures.map(x=>'阻止：'+x),'握手判定：'+need,explain,...notes].join('\n');return {state,entry,need,failures,notes,message};
}
function pipeRateTraceInfo(handshake,text){
 if(!['yes','no'].includes(handshake))return {state:'invalid',message:'选择是否已确认需要Ok/Ack。',rows:[]};
 const events=String(text).trim().split(/[\s,，]+/).filter(Boolean);if(!events.length||events.length>64)return {state:'invalid',message:'请输入1～64个事件；事件可用逗号或空白分隔。',rows:[]};
 let phase=0,phyDone=false,released=false,failed=false,error='',timeout=false;const rows=[];
 const labels=['等待request','等待Ok','等待MAC配置/时钟稳定','等待Ack高','等待本次PhyStatus高','已见完成，等待结束边沿及Ok低','等待撤Ack','握手闭环完成'];
 for(let i=0;i<events.length;i++){
  const event=events[i];let issue='';
  if(event==='timeout'){timeout=true;rows.push({index:i+1,event,note:'轨迹报告超时/失败，PIPE不在此规定统一超时值。'});break;}
  if(event==='release'){if(!phyDone)issue='还未见本次PhyStatus完成，不能释放TxElecIdle/RxStandby。';else if(released)issue='重复release；模型仅跟踪一次释放。';else released=true;}
  else if(handshake==='yes'){
   const expected=['request','ok','clock-stable','ack-high','status-high','status-low-ok-low','ack-low'];
   if(event!==expected[phase])issue='当前应为'+(expected[phase]||'闭环结束后的合法上层动作')+'，不能用'+event+'推进本次操作。';else{phase++;if(event==='status-high')phyDone=true;}
  }else{
   if(event==='request'&&phase===0)phase=1;
   else if(event==='status-high'&&phase===1){phase=2;phyDone=true;}
   else if(event==='status-low'&&phase===2)phase=3;
   else issue='无Ok/Ack分支只跟踪request→status-high（可随后status-low）与完成后release；不接收此事件。';
  }
  if(issue){error='事件'+(i+1)+' '+event+'：'+issue;failed=true;rows.push({index:i+1,event,note:issue});break;}
  rows.push({index:i+1,event,note:event==='release'?'完成已采样后释放；尚不代表Link可用。':handshake==='yes'?labels[phase]:phyDone?'已见本次PHY完成':'等待本次PHY完成'});
 }
 const closed=handshake==='yes'?phase===7:phyDone;
 const state=failed?'order-error':timeout?'reported-timeout':closed?'complete':phyDone?'await-cleanup':'pending';
 const message=[state==='order-error'?error:state==='reported-timeout'?'轨迹已报告失败，需按MAC/产品和上层计时恢复。':state==='complete'?'所列接口步骤已完成；不证明RX对齐、L0或数据链路就绪。':state==='await-cleanup'?'本次PHY完成已见，但Ok/Ack收尾未闭环；完成后可释放空闲。':'序列尚未完成，不能用旧脉冲补成功。','PHY完成已见：'+(phyDone?'是':'否')+'；空闲已释放：'+(released?'是':'否'),handshake==='yes'?'模型采用§8.4.1结束边沿撤Ok分支；保留与p63字段文字差异。':'是否可省握手需先用需求查询并确认datasheet，不能由此输入反推。','仅事件次序模型，不检查1周期脉宽、真实PCLK稳定/毛刺、CDC或共享PLL。'].join('\n');return {state,phase,phyDone,released,closed,error,rows,message};
}
function pipeRatePlanExplorer(){const r=pipeRatePlanInfo('input','P0','yes','yes','yes','yes','no','unknown','unknown');return '<section class="flit-explorer"><h4>PCIe切速入口与Ok/Ack需求</h4><div class="flit-controls">'+powerSelect('prp-topology','PCLK方向',[['input','PHY输入'],['output','PHY输出（legacy）']])+powerSelect('prp-power','当前P-state',[['P0','P0'],['P1','P1'],['P0s','P0s'],['P2','P2']])+powerSelect('prp-ei','TxElecIdle',[['yes','有效'],['no','无效']])+powerSelect('prp-standby','RxStandby输入',[['yes','有效'],['no','无效']])+powerSelect('prp-rate','Rate是否改变',[['yes','改变'],['no','不变']])+powerSelect('prp-pclk','PCLK Rate是否改变',[['yes','改变'],['no','不变']])+powerSelect('prp-width','Width是否改变',[['no','不变'],['yes','改变']])+powerSelect('prp-rate-rule','Rate握手参数',[['unknown','未确认'],['yes','要求'],['no','不要求']])+powerSelect('prp-width-rule','Rate+Width握手参数',[['unknown','未确认'],['yes','要求'],['no','不要求']])+'</div><pre id="prp-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre></section>';}
function pipeRateTracePlot(r){return '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px">'+r.rows.map(x=>'<div class="note"><b>'+x.index+'. '+esc(x.event)+'</b><p>'+esc(x.note)+'</p></div>').join('')+'</div>';}
function pipeRateTraceExplorer(){const value='request, ok, clock-stable, ack-high, status-high, release, status-low-ok-low, ack-low',r=pipeRateTraceInfo('yes',value);return '<section class="flit-explorer"><h4>切速事件顺序 · 选定接口分支</h4><div class="flit-controls">'+powerSelect('prt-handshake','是否已确认需要Ok/Ack',[['yes','需要'],['no','不需要（已核参数）']])+'<label style="grid-column:1/-1">事件序列（逗号分隔）<textarea id="prt-events" rows="3" style="width:100%;font:inherit;padding:10px">'+esc(value)+'</textarea></label>'+'</div><p>支持事件：request / ok / clock-stable / ack-high / status-high / status-low-ok-low / ack-low / release / timeout；无握手分支另可使用status-low。</p><pre id="prt-result" class="note" aria-live="polite" style="white-space:pre-wrap;font:inherit">'+esc(r.message)+'</pre><div id="prt-plot">'+pipeRateTracePlot(r)+'</div></section>';}
function pipeRateBoundaryDiagram(){return '<figure class="note"><figcaption>原创切速交接图 · PIPE7.1 §8.4.1 PCLK输入分支</figcaption><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-top:12px">'+[['MAC请求','Rate/PCLK/Width组合与入口门控'],['PHY许可','Ok高后，MAC才可改实际输入PCLK'],['MAC交接','配置/时钟稳定后Ack高'],['PHY完成','采到本次PhyStatus高，可按条件释放空闲'],['接口收尾','本模型：PhyStatus结束且Ok低→撤Ack'],['协议恢复','RX锁定、对齐、LTSSM和数据链路另核']].map(x=>'<div style="border:1px solid #72968e;padding:12px;border-radius:6px"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p></div>').join('')+'</div><p>图不按时间比例。释放空闲与撤Ack是两个条件，允许先释放再收尾；p63/p126边沿差异见正文。</p></figure>';}
