// R65: versioned L0p arbitration and timing budgets; no live link control.
function l0pArbitrationInfo(version,configured,current,dspWidth,dspPriority,uspWidth,uspPriority){
 const legal=[1,2,4,8,16],nums=[configured,current,dspWidth,uspWidth].map(Number);
 if(!['6.0','7.0'].includes(version)||!nums.every((n,i)=>String(n)===String([configured,current,dspWidth,uspWidth][i]).trim()&&legal.includes(n))||![dspPriority,uspPriority].every(x=>['yes','no'].includes(x)))return {state:'invalid',message:'请选择6.0/7.0、合法宽度和Priority。'};
 const [max,now,dw,uw]=nums,dp=dspPriority==='yes',up=uspPriority==='yes';
 if(now>max||dw>max||uw>max)return {state:'invalid',message:'当前/请求宽度不能超过已配置宽度；这不是最大能力字段。'};
 if(dw===now||uw===now)return {state:'outside-model',message:'简化模型要求双方都请求实际改变宽度；相同当前宽度和已Ack重复请求另有处理规则。'};
 if((dp&&dw>now)||(up&&uw>now))return {state:version==='7.0'?'undefined':'outside-model',message:version==='7.0'?'Base7.0：Priority设在Up-size上行为未定义，不给赢家。':'Base6.0本轮不扩展Priority Up-size解释，先核适用条件。'};
 if(version==='6.0'&&dp&&up&&dw===uw)return {state:'unresolved',message:'Base6.0所核条款没有7.0那句双方Priority同宽DSP平局规则；保留待核，不自动套用新版。'};
 let winner,reason;if(dp!==up){winner=dp?'DSP':'USP';reason='只有一侧Priority，该侧胜。';}else if(dw===uw){winner='DSP';reason='同宽平局由DSP胜'+(dp?'（7.0双方Priority）':'（普通请求）')+'。';}else if(dp){winner=dw<uw?'DSP':'USP';reason='双方Priority取较窄目标。';}else{winner=dw>uw?'DSP':'USP';reason='双方普通请求取较宽目标。';}
 const width=winner==='DSP'?dw:uw,loser=winner==='DSP'?'USP':'DSP';return {state:'resolved',winner,width,loser,reason,message:['Base'+version+'，配置x'+max+'，当前x'+now+'；赢家 '+winner+' → x'+width,reason,loser+'须Ack赢家；'+(version==='7.0'?'赢家可Nak或忽略输方请求。':'输方其它响应/后续操作仍按本版条款核对。'),'假定双方请求已合法形成、满足使能及100ns同时窗口；不是自动断Lane命令。','这是L0p管理应答，非Replay Ack/Nak或TLP Completion。'].join('\n')};
}
function l0pBudgetInfo(version,encoding){
 if(!['6.0','7.0'].includes(version)||!['8b10b','128b130b','1b1b'].includes(encoding))return {state:'invalid',message:'请选择已核版本和编码。'};
 const old=version==='6.0',low=encoding==='8b10b',responseNs=old?1000:low?4000:1000,requestWaitNs=old?2000:low?8000:4000,quietNs=old?1000:low?4000:1000,activationNs=24000000;
 const end=old?'响应Flit最后bit':'响应Flit第一个bit';
 return {state:'listed',responseNs,requestWaitNs,quietNs,activationNs,responseEnd:end,abandonWaitNs:old?null:16000,message:['Base'+version+' / '+encoding+'（已假定当前FM及L0p适用）','应答端预算：'+responseNs/1000+' µs；从有效请求Flit最后bit到接收封装引脚，量至'+end+'离开发送封装引脚。','请求者未收到响应的等待预算：'+requestWaitNs/1000+' µs；到期须重发'+(old?'或放弃。':'相同请求或放弃。'),'新宽度请求间隔参考：'+quietNs/1000+' µs；'+(old?'仅对应6.0完成后等待这一替代条件，另有放弃/对端路径。':'还须同时满足已完成/放弃等条件；自己放弃后至少16µs。'),'激活失败：从开始激活计24 ms仍未加入活动Lane → Recovery。',old?'不向6.0回填7.0五Flit重复、4/8/16µs放弃条件。':'7.0同请求五Flit内最多三份；Up-size放弃看Ack后16µs未启动且8µs未重发。','这些预算不相加成总退出延迟；不判定真实时间戳、通用容差或完整请求历史。'].join('\n')};
}
