function l0pLaneFlowDiagram(){return '<figure class="note"><figcaption>原创L0p扩宽边界图 · 原活动Lane继续传输</figcaption><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;margin-top:12px">'+[['管理协商','请求/Ack不是全部Lane已经就绪'],['新增Lane','EI退出→TS1/TS2接收8与发送16门控'],['汇合边界','适用SDS→共同SKP→deskew→活动集合更新'],['异常恢复','激活24ms失败必须Recovery；缩窄24ms分支强度另核']].map(x=>'<div style="border:1px solid #72968e;padding:12px;border-radius:6px"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p></div>').join('')+'</div><p>图不按比例。2.5GT/s无EIEOS/SDS，5GT/s有EIEOS无SDS；6/7其它例外见正文。</p></figure>';}
function r65Refresh(e){const id=e.target?.id||'',v=x=>document.getElementById(x).value;if(id.startsWith('lpa-'))document.getElementById('lpa-result').textContent=l0pArbitrationInfo(v('lpa-version'),v('lpa-config'),v('lpa-current'),v('lpa-dsp-width'),v('lpa-dsp-priority'),v('lpa-usp-width'),v('lpa-usp-priority')).message;if(id.startsWith('lpb-'))document.getElementById('lpb-result').textContent=l0pBudgetInfo(v('lpb-version'),v('lpb-encoding')).message;}
