// R66: DOE header interpretation and TDISP state gate; offline learning only.
function doeHeaderInfo(version,h1,h2,connection){
 const parse=x=>typeof x==='string'&&/^(?:0x)?[0-9a-f]{1,8}$/i.test(x.trim())?Number.parseInt(x.trim().replace(/^0x/i,''),16):null;
 const a=parse(h1),b=parse(h2);if(!['6.0','7.0'].includes(version)||a===null||b===null||!['yes','no'].includes(connection))return {state:'invalid',message:'请选择6.0/7.0，输入1～8位十六进制DWORD；不接受负数、溢出或空值。'};
 const vendor=a&65535,type=(a>>>16)&255,encoded=b&0x3ffff,dwords=encoded===0?262144:encoded,cid=(b>>>18)&4095,warnings=[];
 if(encoded===1)return {state:'invalid-length',message:'Length=1不构成合法对象：至少2DW含头；7.0明确禁止编码1。'};
 if(a>>>24)warnings.push('Header1保留位非零');
 if(version==='6.0'){if(b>>>18)warnings.push('6.0 Header2[31:18]是保留位');if(connection==='yes')warnings.push('6.0没有本版7.0 Connection ID字段');}
 else {if(b>>>30)warnings.push('Header2[31:30]保留位非零');if(connection==='no'&&cid)warnings.push('所选类型不使用Connection ID，这12bit为保留位');}
 const use=version==='7.0'&&connection==='yes';
 return {state:'decoded',vendor,type,encoded,dwords,bytes:dwords*4,payloadBytes:(dwords-2)*4,connectionId:use?cid:null,warnings,message:`Base${version}：Vendor=${vendor.toString(16).padStart(4,'0')}h，Type=${type.toString(16).padStart(2,'0')}h；总长${dwords} DW / ${dwords*4} Byte（含8Byte头），正文${(dwords-2)*4} Byte。${use?'Connection ID='+cid+'（假定所选类型确实定义该字段）':'Connection ID不适用；相关位按保留解释。'}${warnings.length?' 警告：'+warnings.join('；')+'。':''} 只解码头，不证明实际传输长度、能力、SPDM或安全验证通过。`};
}
function doeHeaderExplorer(){return `<div class="note"><h3>DOE Header离线解码</h3><label>Base版本 <select id="doeh-version"><option>7.0</option><option>6.0</option></select></label> <label>Header1 hex <input id="doeh-h1" value="00010001" maxlength="10"></label> <label>Header2 hex <input id="doeh-h2" value="00000003" maxlength="10"></label> <label>对象类型定义使用Connection ID <select id="doeh-cid"><option value="no">否／未确认</option><option value="yes">是（已由类型定义确认）</option></select></label><p id="doeh-result" aria-live="polite">${esc(doeHeaderInfo('7.0','00010001','00000003','no').message)}</p></div>`;}
function tdispCommandInfo(state,command,supported,secured,nonce){
 const states=['CONFIG_UNLOCKED','CONFIG_LOCKED','RUN','ERROR'];
 const map={'81':{name:'GET_VERSION',states,required:true},'82':{name:'GET_CAPABILITIES',states,required:true},'83':{name:'LOCK',states:['CONFIG_UNLOCKED'],required:true},'84':{name:'GET_REPORT',states:['CONFIG_LOCKED','RUN'],required:true},'85':{name:'GET_STATE',states,required:true},'86':{name:'START',states:['CONFIG_LOCKED'],required:true},'87':{name:'STOP',states,required:true},'88':{name:'BIND_P2P',states:['RUN']},'89':{name:'UNBIND_P2P',states:['RUN']},'8a':{name:'SET_MMIO_ATTRIBUTE',states:['RUN']},'8b':{name:'VDM',states},'8c':{name:'SET_TDISP_CONFIG',states:['CONFIG_UNLOCKED']}};
 const q=map[command];if(!states.includes(state)||!q||![supported,secured,nonce].every(v=>['yes','no'].includes(v)))return {state:'invalid',message:'状态、命令或选项无效。'};
 if(secured==='no')return {state:'insecure-drop',message:'非安全封装的TDISP消息不得使用，也不得响应；不能返回普通TDISP_ERROR代替安全传输。'};
 if(supported==='no')return {state:'unsupported',message:'UNSUPPORTED_REQUEST：未支持该命令。'+(q.required?' 该命令属于必需项，未实现还说明不满足本版实现要求。':' 可选命令不能仅凭Base版本假定支持。')};
 if(!q.states.includes(state))return {state:'wrong-state',message:`${q.name}在${state}不满足表11-4状态条件：INVALID_INTERFACE_STATE。`};
 if(command==='86'&&nonce==='no')return {state:'invalid-nonce',message:'START nonce不匹配：INVALID_NONCE，不能进入RUN。'};
 const warning=command==='84'&&state==='RUN'?' 警告：正文和表11-4允许RUN，但表11-17错误条件仅写not CONFIG_LOCKED，需勘误/实现确认。':'';
 return {state:'parameter-check',command:q.name,warning,message:`${q.name}：状态门控通过，仅可继续检查参数；不表示执行成功。${warning} 仍须版本协商、有效接口、并发/分片历史及命令专属IDE/配置条件；本工具不执行任何设备操作。`};
}
