// R67: finite initial-credit table baseline and FM allocation options, not a conformance verdict.
function fcInitialMinimumInfo(version,mode,pool,type,scale,payload,count,merged){
 const num=x=>typeof x==='string'&&/^\d+$/.test(x)?Number(x):NaN;
 const s=num(scale),b=num(payload),n=num(count),header=['PH','NPH','CplH'].includes(type);
 if(!['6.0','7.0'].includes(version)||!['FM','NFM'].includes(mode)||!['shared','dedicated'].includes(pool)||!['PH','PD','NPH','NPD','CplH','CplD'].includes(type)||![1,4,16].includes(s)||!Number.isSafeInteger(b)||b<16||b>4096||b%16||!Number.isSafeInteger(n)||n<1||n>8||!['yes','no'].includes(merged))return {state:'invalid',message:'输入无效：Payload需16～4096Byte且16Byte对齐，VC数1～8，Scale为1/4/16；本查询不自动推导能力。'};
 if(mode==='NFM'&&(pool==='shared'||merged==='yes'))return {state:'invalid-mode',message:'NFM没有Shared/Merged；请选Dedicated和非Merged。'};
 if(mode==='FM'&&pool==='shared'&&merged==='yes'&&type.startsWith('Cpl'))return {state:'merged-reference',message:'Shared Cpl应编码Merged，使用Posted公共池；请改查对应PH/PD，不再加一份Cpl初始容量。'};
 const special=version==='7.0'&&mode==='FM'&&pool==='shared';let encoded;
 if(header)encoded=s===1&&special?4:1;
 else if(s>1)encoded=Math.ceil(b/(16*s))+1;
 else if(special)encoded=type==='PD'?Math.ceil(b/16)+4:Math.max(b/16,4)+4;
 else encoded=b/16;
 const units=encoded*s,max=(header?127:2047)*s,globalMinimum=special?units*n*(merged==='yes'&&type.startsWith('P')?2:1):null;
 const warnings=[];if(units>max)warnings.push('有限基线超过该Scale最大未用信用');if(globalMinimum!==null&&globalMinimum>max)warnings.push('Shared总下限超过本Scale可表达的最大未用信用，需要更高Scale或重新评估分配');
 const scope=special?'表基线用于总量核算，不是每VC都须广告此值':'仅本版表的有限广告基线';
 return {state:'calculated',encoded,units,scale:s,globalMinimum,max,warnings,message:`Base${version} ${mode} ${pool} ${type}：基线字段${encoded.toString(16).padStart(header?2:3,'0')}h ×${s} = ${units}实际信用单位${header?'（Header）':` / ${units*16}Byte数据缓冲口径`}。${globalMinimum===null?'本查询不外推6.0的Shared全VC总量公式。':`7.0 Shared有限贡献总下限=${globalMinimum}实际单位（${n}个已启用VC${merged==='yes'&&type.startsWith('P')?'，Merged Posted再×2':''}）。`}${scope}。${warnings.length?' 警告：'+warnings.join('；')+'。':''} 假定该行允许有限非零广告；还须核Completion角色、Zero/Infinite/Merged、所有VC实际分配和死锁规则，不是配置合法性结论。`};
}
function fcMinimumExplorer(){return `<div class="note"><h3>有限初始广告基线（非配置合法性裁决）</h3><label>Base <select id="fcmin-version"><option>7.0</option><option>6.0</option></select></label> <label>模式 <select id="fcmin-mode"><option>FM</option><option>NFM</option></select></label> <label>池 <select id="fcmin-pool"><option value="shared">Shared</option><option value="dedicated">Dedicated / NFM</option></select></label> <label>类型 <select id="fcmin-type">${['PH','PD','NPH','NPD','CplH','CplD'].map(t=>`<option ${t==='PD'?'selected':''}>${t}</option>`).join('')}</select></label> <label>Scale <select id="fcmin-scale"><option>1</option><option>4</option><option>16</option></select></label> <label>对应接收Payload上限 Byte <input id="fcmin-payload" value="1024" inputmode="numeric"></label> <label>已启用VC数 <input id="fcmin-count" value="2" inputmode="numeric"></label> <label>Merged <select id="fcmin-merged"><option value="no">否</option><option value="yes">是</option></select></label><p id="fcmin-result" aria-live="polite">${esc(fcInitialMinimumInfo('7.0','FM','shared','PD','1','1024','2','no').message)}</p></div>`;}
function fcFmAllocationInfo(version,local,remote,layout,merged){
 const count=x=>typeof x==='string'&&/^[0-7]$/.test(x)?Number(x):null,l=count(local),r=count(remote);
 if(!['6.0','7.0'].includes(version)||l===null||r===null||!['auto','single','multi'].includes(layout)||!['yes','no'].includes(merged))return {state:'invalid',message:'输入无效：Extended VC Count须为0～7，不能输入VC ID或当前启用数量。'};
 const path=layout==='auto'?(l===0||r===0?'single':'multi'):layout;
 if(path==='multi'&&l===0)return {state:'invalid-layout',message:'Local Extended VC Count=0，只能使用单VC布局。'};
 if(path==='single'&&l!==0&&r!==0)return {state:'invalid-layout',message:'双方Extended VC Count均非0，不能仅因当前启用1个VC而选单VC能力布局。'};
 const finite='有限非零 / Infinite',m=merged==='yes',multi=path==='multi',rows=[];
 for(const kind of ['P','NP','Cpl'])rows.push(['Shared',kind,m&&kind==='Cpl'?'Merged':finite+(multi?' / Zero':'')]);
 for(const kind of ['P','NP','Cpl'])rows.push(['Dedicated',kind,!multi&&(!m||kind==='NP')?'Zero':finite]);
 const rowNumbers=path==='single'?(m?'5～8':'3～4'):(m?'11～13':'9～10');
 let note=l!==0&&r===0?(version==='7.0'?'7.0推荐单VC布局，同时允许多VC布局。':'6.0注6允许采用单VC布局；不回填7.0的推荐强度。'):'';
 if(multi)note+=version==='6.0'?' 6.0 Zero Shared不允许VC0。':' 7.0允许多VC全Shared Zero，但Merged时Posted必须有非Zero贡献者。';
 if(m)note+=' Merged须所有VC及Header/Data一致；Dedicated永不Merged。';
 return {state:'listed',path,merged:m,rows,rowNumbers,note,message:`Base${version} FM ${path==='single'?'单VC':'多VC'} ${m?'Merged':'非Merged'}布局，表${version==='6.0'?'3-2':'3-3'}行${rowNumbers}。${note} 下表仅为选定布局的编码集合；还须核最小广告、Cpl角色、Scale/所有VC总量和死锁条件，不能直接判配置合法。`};
}
