// R68: decoded training-control byte and nominal OS transmit shape, not an LTSSM validator.
function tsTrainingControlInfo(version,rate,tsType,hexByte){
 const rates=['2.5','5','8','16','32','64','128'];
 if(!['6.0','7.0'].includes(version)||!rates.includes(rate)||!['TS1','TS2'].includes(tsType)||typeof hexByte!=='string'||!/^(?:0x)?[0-9a-f]{1,2}$/i.test(hexByte.trim()))return {state:'invalid',rows:[],warnings:[],message:'输入无效：请选择已列版本、速率、TS类型和一个十六进制字节。'};
 if(version==='6.0'&&rate==='128')return {state:'outside-version',rows:[],warnings:[],message:'Base6.0查询不定义128GT/s；请用7.0，不外推旧版字段。'};
 const n=parseInt(hexByte.trim().replace(/^0x/i,''),16),r=Number(rate),pam=r>=64,rows=[],warnings=[],h=n.toString(16).padStart(2,'0').toUpperCase()+'h';let state='decoded';
 const put=(bit,value,name,condition)=>rows.push([bit,String(value),name,condition]);
 if(pam){
  const names={0:'控制请求清零',1:'Hot Reset',2:'Disable Link',4:'Loopback：Follower A/F',5:'Loopback：Pseudoport B/C',6:'Loopback：Pseudoport D/E',8:'Compliance Receive',12:'Loopback + Compliance Receive'};
  const code=n&15;put('[3:0]',code.toString(2).padStart(4,'0'),names[code]||'Reserved枚举','完整枚举值；不是四个独立控制bit');put('[7:4]',n>>>4,'Reserved','发送置0；非零不直接推出整个TS无效');
  if(!(code in names)){state='reserved-code';warnings.push('该枚举未定义控制请求；不能按独立bit拼出命令，也不据此独立判整TS无效。');}
  if(n&240)warnings.push('高4bit为Reserved；检查观察点与发送端置零要求，接收端不因Reserved非零直接否决TS。');
  warnings.push('字段按Recovery.RcvrCfg及适用Loopback角色解释；TS2在Configuration中的该控制字段为Reserved。B/C、D/E还要按Loopback Lead位置区分。');
 }else{
  const bit=i=>(n>>i)&1;
  put('0',bit(0),'Hot Reset','与Disable Link、Loopback互斥');put('1',bit(1),'Disable Link','与Hot Reset、Loopback互斥');put('2',bit(2),'Loopback','与Hot Reset、Disable Link互斥');
  put('3',bit(3),r<=5?'Disable Scrambling':'Reserved',r<=5?'仅2.5/5GT/s适用':'≥8GT/s不使用此位禁扰码');
  if(r>5&&bit(3))warnings.push('bit3为Reserved非零；这不是整TS有效性的充分否决条件。');
  if(tsType==='TS1'){
   put('4',bit(4),'Compliance Receive',r===2.5?'2.5GT/s支持可选':'≥5GT/s支持必需；仍受状态/角色门控');
   put('5',bit(5),'Modified Compliance in Loopback','Loopback Lead且支持≥32GT/s等条件；不能只看当前速率');
   if(version==='7.0'&&bit(4)&&(bit(0)||bit(1))){state='undefined-combination';warnings.push('7.0 TS1 Compliance Receive与Hot Reset或Disable Link并置为未定义组合。');}
   if(version==='6.0'&&bit(4)&&(bit(0)||bit(1)))warnings.push('6.0已核通用互斥规则限定低3bit；不把7.0新增明确措辞倒填为6.0结论。');
  }else{
   put('4',bit(4),r===2.5?'Retimer Present':'Reserved','TS2的Retimer报告仅2.5GT/s');put('5',bit(5),r===2.5?'Two Retimers Present':'Reserved','TS2的双Retimer报告仅2.5GT/s');
   if(r!==2.5&&(n&48))warnings.push('TS2 bit5/4在当前速率为Reserved；不能当成TS1 Compliance控制。');
  }
  const elbc=['支持完整均衡流程','支持绕过最高NRZ速率均衡','No Equalization Needed，并须支持相应绕过','支持Modified TS'][n>>>6];put('[7:6]',(n>>>6).toString(2).padStart(2,'0'),'ELBC：'+elbc,'需结合状态、编码与能力；不是收到即执行');
  if(bit(0)+bit(1)+bit(2)>1){state='undefined-combination';warnings.push('Hot Reset、Disable Link、Loopback中多位置1：未定义组合。');}
 }
 const position=pam?'S6 / S14低4bit枚举':'S5独立控制位';
 const message=`Base${version} · ${rate}GT/s · ${tsType} · ${h} · ${position}。${rows.map(x=>`${x[0]}=${x[1]} ${x[2]}`).join('；')}。${warnings.join(' ')} 仅字段解释，不代表实际LTSSM请求可执行，也未验证Parity、有效半部、连续序列计数或对端能力。`;
 return {state,rows,warnings,position,byte:n,message};
}
