function orderedSetShapeInfo(version,rate,mode,kind,context){
 const rates=['2.5','5','8','16','32','64','128'],contexts=['ordinary','wake-pending','wake-satisfied','l0-recovery'];
 if(!['6.0','7.0'].includes(version)||!rates.includes(rate)||!['FM','NFM'].includes(mode)||!['EIOS','EIEOS','SDS','FTS'].includes(kind)||!contexts.includes(context))return {state:'invalid',message:'输入无效：仅处理已列版本、速率、模式、OS与场景。'};
 const r=Number(rate),pam=r>=64;
 if(version==='6.0'&&r===128)return {state:'outside-version',message:'Base6.0不定义128GT/s查询。'};
 if(pam&&mode!=='FM')return {state:'invalid-mode',message:'64/128GT/s必须使用FM，不能组合为NFM。'};
 let count=1,symbolsPerOs=16,sequence='',note='';
 if(kind==='EIOS'){
  if(r<=5){symbolsPerOs=4;count=r===5?2:1;sequence='COM + 3×IDL；'+count+'份EIOS组成EIOSQ';}
  else sequence=pam?'16Symbol：0F F0重复8次':'16Symbol：66h重复16次';
  note='长度为完整名义发送结构；最后一个高速EIOS允许的尾部截断另看正文，不能按此反推实际截断长度。';
 }else if(kind==='EIEOS'){
  if(r===2.5)return {state:'not-defined',message:'2.5GT/s无本查询定义的EIEOS；不要套用5GT/s模式。'};
  if(r===5)sequence='COM + 14×EIE + D10.2';
  else if(r<64){const run={8:1,16:2,32:4}[r];sequence=`${run}×00h、${run}×FFh循环至16Symbol`;if(r===32)count=2;}
  else {sequence='8×00h + 8×FFh';if(context==='wake-pending'){count=r===128?10:4;if(r===128)sequence='[I-EIEOS(8×FFh+8×00h), EIEOS(8×00h+8×FFh)]重复5组';}}
  note='wake-pending仅限Speed/L1→RcvrLock、L0p扩宽或EI→Loopback，且全部相关Lane退出EI及任一Lane两个连续有效TS1这两个终止条件均尚未满足。L0→Recovery在64/128GT/s取单个EIEOS，即使先前部分Lane处于L0p电气空闲。';
 }else if(kind==='SDS'){
  if(r<8)return {state:'not-defined',message:'2.5/5GT/s不使用本查询的SDS OS结构。'};
  sequence=pam?'[B1 C6 C6 C6]×4为单个SDS；连续两个SDS组成发送序列':r===32?'E1h + 15×87h':'E1h + 15×55h';if(pam)count=2;
  note=(mode==='FM'?'非Loopback：SDS序列 → Control SKP → Data Stream。':'非Loopback：SDS → Data Block，其首Symbol开始Data Stream。')+' 当前长度仅含SDS，不含Control SKP和后续Data Stream；1b/1b SDS序列须16Byte对齐。';
 }else{
  if(mode==='FM')return {state:'unsupported-mode',message:'FM不支持L0s，不能生成FTS唤醒结构；参见Base6.0 §5.4.1.1 p623及Base7.0的L0s/TS字段说明。'};
  if(r<=5){symbolsPerOs=4;sequence='COM + 3×FTS(K28.1)';}
  else sequence='单个FTS：16Symbol OS Block（具体固定Symbol值参见4.2.5.6）';
  note='仅计算单个FTS，不是完整唤醒列车：不含N_FTS/Extended 4096重复、前后EIEOSQ、SKP和SDS。5GT/s FTS前需至少4个有效幅度EIE、最多8个；不并入本单OS长度。';
 }
 const decodedBits=count*symbolsPerOs*8,wireBits=r<=5?count*symbolsPerOs*10:r<=32?count*130:count*128,ui=wireBits/(pam?2:1);
 const message=`Base${version} · ${rate}GT/s · ${mode} · ${kind} · ${context}：${count}个OS，每OS ${symbolsPerOs}个解码/规定Symbol；序列Symbol区${decodedBits}bit（${decodedBits/8}Byte），线上${wireBits}bit，${ui}UI。${sequence}。${note} 该查询假定LTSSM发送条件已成立，不决定状态转移，不模拟接收容错。`;
 return {state:'listed',count,symbolsPerOs,decodedBits,wireBits,ui,sequence,note,message};
}
