// R69: selected Base7.0 TDISP gates; no traffic generation, key validation or complete security claim.
function tdispAccessInfo(role,state,xtMode,nonTee,xt,t,ideRequired,bound){
 const roles=['mmio','dma-untranslated','dma-translated','ats'];
 if(!roles.includes(role)||!['CONFIG_UNLOCKED','CONFIG_LOCKED','RUN','ERROR'].includes(state)||![xtMode,nonTee,xt,t,ideRequired,bound].every(x=>['0','1'].includes(x)))return {state:'invalid',message:'输入无效：请选择所列角色、状态和0/1字段。'};
 if(xtMode==='0'&&xt==='1')return {state:'outside-context',message:'未启XT时本查询不解释XT=1：请选择XT=0表示该位不参与此模式判定；这不是整TLP有效性裁决。'};
 let result='gate-pass',reason='';const mode=xtMode==='1',shared=nonTee==='1',X=xt==='1',T=t==='1';
 if(role==='mmio'){
  if(!shared){if(state!=='RUN'){result='reject';reason='私有MMIO要求TDI仍在RUN。';}else if(!T||mode&&!X){result='reject';reason=mode?'私有MMIO要求XT/T=11。':'私有MMIO要求T=1。';}else if(ideRequired==='1'&&bound!=='1'){result='reject';reason='要求IDE时须收到绑定本TDI的流。';}else reason='所列私有MMIO的状态、标记与流绑定门控通过。';}
  else if(mode&&T){result='reject';reason='XT模式共享MMIO要求T=0，XT可0或1。';}
  else {result='ordinary-policy';reason='共享MMIO按普通设备访问策略处理；TDISP此分支不按状态额外限制，不等于所有访问均合法。';}
 }else{
  if(state!=='RUN')return {state:'outside-run',message:'该主机DMA/ATS访问表以被TVM接纳且在RUN的TDI为前提。LOCKED/ERROR普通Memory/ATS禁止发起；非RUN清位不是发送许可。'};
  if(mode&&role==='dma-translated'&&!X&&T){result='reject';reason='XT模式Translated 01须拒绝，不能沿用未翻译的无特定限制语义。';}
  else {const target=mode?(X?(T?'TEE':'non-TEE'):(T?'TA':'non-TEE')):(T?'TA':'non-TEE');
   if(target==='TA'){result='ta-permission';reason='目标类别由TA翻译或TEE权限检查决定；仍须核实际映射与访问权限。';}
   else if((target==='non-TEE')!==shared){result='reject';reason=`此组合只允许${target}内存，与所选目标类别不符。`;}
   else reason=`所列主机规则允许该${target}目标类别，仍需TA权限与来源隔离。`;
  }
 }
 return {state:result,message:`Base7.0 · ${role} · ${state} · XT模式${xtMode} · XT/T=${xt}${t} · ${shared?'非TEE/共享':'TEE/私有'}：${reason} 仅所列TDISP门控，假定标记已按正确IDE上下文解码且通过IDE检查；不证明完整访问授权，不对Posted拒绝虚构Completion。`};
}
function tdispTagPlanInfo(kind,state,xtMode,restriction,te,locked,lockedXt){
 if(!['untranslated','ats','translated','msi','msix','pri'].includes(kind)||!['CONFIG_UNLOCKED','CONFIG_LOCKED','RUN','ERROR'].includes(state)||![xtMode,locked,lockedXt].every(x=>['0','1'].includes(x))||!['tee','nontee','unspecified'].includes(restriction)||!['0','1','unknown'].includes(te))return {state:'invalid',message:'输入无效：仅处理所列请求家族/状态/字段。'};
 const mode=xtMode==='1';let X=0,T=0,note='',status='tag-plan';
 if(mode===false&&lockedXt==='1')return {state:'invalid-config',message:'XT模式关闭时XT_BIT_FOR_LOCKED_MSIX须0；DSM_CONFIG值2不合法。'};
 if(state!=='RUN'){
  if(state==='CONFIG_LOCKED'&&(kind==='msi'||kind==='msix'))note='CONFIG_LOCKED仅许可XT/T均清零的MSI/MSI-X；不应用RUN锁表分支。';
  else if(['CONFIG_LOCKED','ERROR'].includes(state)&&['untranslated','ats','translated'].includes(kind))return {state:'prohibited-origin',message:'CONFIG_LOCKED/ERROR禁止普通Memory及ATS Translation请求发起；不能靠改成00绕过。'};
  else return {state:'clear-not-permit',xt:0,t:0,message:'非RUN时此组已核请求应清XT/T；本工具不据此授予发送许可，ERROR中断许可未在本组作通用判定。'};
 }else if(kind==='msi')note='来自Function MSI Capability的地址/数据，清XT/T；RUN不使该配置自动可信。';
 else if(kind==='msix'){
  T=locked==='1'?1:0;X=mode&&T?Number(lockedXt):0;note=locked==='1'?'已锁定且已报告MSI-X：T=1，XT按XT_BIT_FOR_LOCKED_MSIX。':'MSI-X未锁定并报告：清XT/T。';
 }else if(kind==='pri'){T=1;note='RUN Page Request：XT清0、T置1；响应须核RUN及匹配标记，走默认流。';}
 else if(kind==='translated'){
  if(mode&&te==='unknown')return {state:'needs-te',message:'XT模式Translated须依据受支持且可信TA返回的TE；缺TE不能按意图猜测。'};
  X=mode?1:0;T=mode?Number(te):1;note=mode?'Translated按TE：TE=1→11，TE=0→10；无01发送分支。':'XT关闭：RUN Translated的T=1。';
 }else {if(mode){X=restriction==='unspecified'?0:1;T=restriction==='nontee'?0:1;}else T=1;note=mode?'未翻译/ATS按意图：TEE=11，非TEE=10，无特定限制=01。':'XT未启用，RUN普通未翻译/ATS的T=1，实际目标由TA权限判断。';}
 return {state:status,xt:X,t:T,message:`Base7.0 · ${kind} · ${state}：发送XT/T=${X}${T}（XT未启用时显示0表示不按XT模式解释）。${note} 仅字段规划，前提为能力/状态及配置满足；未核全部ATS、会话、密钥和流匹配，不是执行命令。`};
}
