// R70: selected register semantics and measurement evidence; no device I/O.
function fberControlInfo(version,mode,encoding,hex,access){
 if(!['6.0','7.0'].includes(version)||!['FM','NFM'].includes(mode)||!['NRZ','PAM4'].includes(encoding)||!['read','write'].includes(access)||typeof hex!=='string'||!/^(?:0x)?[0-9a-f]{1,8}$/i.test(hex.trim()))return {state:'invalid',message:'输入无效：请选择版本、模式、编码、读/写观察点和32bit十六进制值。'};
 const value=parseInt(hex.trim().replace(/^0x/i,''),16),enable=value&1,clear=(value>>>1)&1,granularity=(value>>>2)&3,burst=(value>>>4)&1,reserved=Math.floor(value/32),units=['valid Flit中FEC纠正的全部bit','valid Flit中每UI even bit的FEC纠正数','valid Flit中每UI odd bit的FEC纠正数','Control SKP OS parity mismatch事件'][granularity];
 const issues=[];if(version==='7.0'&&burst)issues.push('7.0 bit4已废弃，置1行为未定义。');if(encoding==='NRZ'&&[1,2].includes(granularity))issues.push('非PAM4使用Granularity01/10，测量结果未定义。');if(reserved)issues.push('保留位[31:5]非零；检查读写上下文，不据此解释隐藏功能。');if(access==='read'&&clear)issues.push('Clear位规定读回恒0；输入与正常读回规则不符，不把它当已清零历史。');
 let state=mode==='NFM'?'inactive':access==='read'&&clear?'inconsistent-read':version==='7.0'&&burst||encoding==='NRZ'&&[1,2].includes(granularity)?'undefined':'decoded';
 const operation=access==='write'?`${enable?'写1到Enable会开始并重置相关计数。':'Enable=0停止测量。'}${clear?'本次还写1清FBER计数。':''}`:'读回Enable只是当前值；Clear读0无法判断过去是否写1。';
 const message=`Base${version} · ${mode} · ${encoding} · ${access} · ${value.toString(16).padStart(8,'0').toUpperCase()}h：E=${enable}，C=${clear}，G=${granularity.toString(2).padStart(2,'0')}，B=${burst}。计数口径：${units}。${mode==='NFM'?'该能力在NFM无效果；以下字段适用性提示不能当本模式正在计数。':operation} ${issues.join(' ')} ${version==='6.0'?'6.0 bit4=1选择最长burst，0为首次burst；不把它解释为逐Lane错误计数单位改变。':'7.0应保持bit4=0。'} FBER计数饱和、不回绕；不据控制字计算BER，不执行寄存器写入。`;
 return {state,value,enable,clear,granularity,burst,reserved,units,issues,message};
}
function bermonEvidenceInfo(mode,seed,done,fresh,matched,apiOk,denominator,saturated){
 if(!['window','continuous'].includes(mode)||![seed,done,fresh,matched,apiOk,denominator,saturated].every(x=>['0','1'].includes(x)))return {state:'invalid',message:'输入无效：仅处理窗口/连续与所列0/1证据。'};
 const issues=[];if(apiOk==='0')issues.push('本轮调用存在失败；不能把返回结构视为有效统计。');if(seed==='0')issues.push('seed未验证，不计bit错误且读回无效。');if(matched==='0')issues.push('图样/Gray/Precode/观察点配置未确认匹配。');if(mode==='window'&&done==='0')issues.push('本次窗口尚未Done，不能作为完整窗口。');if(fresh==='0')issues.push('没有本轮新捕获/报告，旧值不能复用。');if(denominator==='0')issues.push('有效比较bit分母未核，不计算BER或零错误上界。');if(saturated==='1')issues.push('已知计数饱和，只能保留下界，不能给精确错误数。');
 const state=apiOk==='0'||seed==='0'||matched==='0'?'invalid-evidence':mode==='window'&&done==='0'?'waiting-window':fresh==='0'?'needs-snapshot':denominator==='0'?'needs-denominator':saturated==='1'?'lower-bound':'usable-evidence';
 const message=`Preliminary SDK1.00a_pre3 / ${mode}：${state==='usable-evidence'?'所列证据齐备，可继续解释该观察窗口。':issues.join(' ')} ${mode==='continuous'?'连续模式不要求窗口Done，须保存快照及实际有效区间。':'窗口模式要求本轮Done。'} 结合3.02a seed/捕获有效性要求作证据检查，不推断两个交付版本兼容。通过不表示达到BER目标，不替代完整测量算法/合规/硬件验证，不运行产品API。`;
 return {state,issues,message};
}
