// R71: selected ordinary Completion lifecycle rules; not a complete packet validator.
function completionArrivalInfo(version,fmSupported,phase,knownOld,idMatch,mismatch,kind,status,allData){
 const bad=message=>({state:'invalid',message});
 if(!['3.0','6.0','7.0'].includes(version)||![fmSupported,knownOld,idMatch,allData].every(x=>['0','1'].includes(x))||!['normal','flr-active','flr-done-disabled','reenabled'].includes(phase)||!['none','ido-only','byte-address','other'].includes(mismatch)||!['memread','config'].includes(kind)||!['SC','UR','CA','RRS','Reserved'].includes(status))return bad('输入无效：仅处理所列普通Memory Read/Configuration上下文。');
 if(version==='3.0'&&fmSupported==='1')return bad('Base3.0没有Flit Mode支持；请把FM支持设为0。');
 if(phase==='normal'&&knownOld==='1')return bad('已知复位前旧完成需要选择相应FLR窗口；正常窗口不解释此标记。');
 if(mismatch==='byte-address'&&kind!=='memread')return bad('Byte Count/Lower Address特别分支仅处理Memory Read。');
 if(version==='3.0'&&phase!=='normal')return {state:'version-scope',message:'本查询FLR窗口核读的是6.0/7.0；3.0本轮只核所列普通Completion关联规则，不跨版推断FLR细节。'};
 let state,reason;
 if(phase==='flr-active'){state='flr-drop-options';reason='FLR执行期间的Completion可按Unexpected处理，或在更新流控信息后静默丢弃；不据此满足新请求。';}
 else if(phase==='flr-done-disabled'&&knownOld==='1'){state='unexpected';reason='FLR已完成且Function尚未重新使能，旧Completion按Unexpected丢弃。';}
 else if(idMatch==='0'){state='unexpected';reason='没有匹配的活动Transaction ID：Unexpected Completion并丢弃，不能绑定给其它请求。';}
 else if(phase==='reenabled'&&knownOld==='1'){state='stale-risk';reason='已知是旧完成，即使ID与新请求相同也不能据此认定属于新请求；线上的Tag不携带请求代次，须依赖复位前排空和平台生命周期证据。';}
 else if(mismatch==='ido-only'&&version==='3.0'){state='version-scope';reason='本查询核读的3.0关联检查段没有新版明确的IDO排除条文，保留版本边界，不倒填6.0/7.0规则。';}
 else if(['byte-address','other'].includes(mismatch)){
  if(version==='3.0'){state=mismatch==='byte-address'?'recommended-unexpected':'recommended-malformed';reason=mismatch==='byte-address'?'3.0脚注：Memory Read仅Byte Count/Lower Address不匹配，推荐Unexpected；正确成形时也可Malformed。':'3.0强烈推荐Malformed；包正确成形时允许Unexpected分类。';}
  else if(fmSupported==='1'){state='mismatch-options';reason='6.0/7.0 MUST@FLIT要求Unexpected；若包正确成形，允许改按Malformed处理。按是否支持FM判断，不只看当前链路模式。';}
  else {state='optional-check-boundary';reason='未支持FM的实现不套用MUST@FLIT强制性；需核实现的可选检查与其报告策略，本查询不判定可接受。';}
 }
 else if(status==='RRS'){state=kind==='config'?'config-retry':'invalid-status-context';reason=kind==='config'?'Configuration RRS走RC的特殊重试/软件可见性规则，当前请求不是成功完成；重新发出的请求单独看待。':'普通Memory Read不能把RRS当通用重试指令；完整成形性与错误优先级在本查询之外。';}
 else if(['UR','CA','Reserved'].includes(status)){state='terminal-error';reason=(status==='Reserved'?'保留Completion Status按UR处理。':'')+'该错误终止普通请求并释放对应内部完成上下文；已接收部分数据如何交付依实现，不能据此授予软件缓冲区所有权。';}
 else if(kind==='config'){state='config-sc';reason='Configuration SC仍须满足该请求的单Completion、数据与字段规则；此查询不根据Memory Read的分片输入推导其合法性。';}
 else if(allData==='0'){state='awaiting-more';reason='SC但尚未收到全部所需读数据，活动上下文及Tag仍需保留；首个成功Completion不等于请求结束。';}
 else {state='success-complete';reason='所列门控通过且所需读数据齐备，可结束本请求的完成上下文；不自动等于软件同步/缓存一致性已完成。';}
 const note=mismatch==='ido-only'&&version!=='3.0'?' IDO bit2不作相等性检查；不能仅因该位不同判异常。':'';
 return {state,message:`Base${version} · ${phase} · ${state}：${reason}${note} 前提：除所选差异外包已正确成形且其它语义检查已通过；活动ID包含Requester ID与Tag，不是只比较Tag。仅查询所列规则，不覆盖UIO、完整错误优先级或全部接收合法性。`};
}
function completionArrivalExplorer(){return `<div class="note"><h3>Completion到达与上下文处置</h3>${r69Select('cra-version','Base',['3.0','6.0','7.0'],'7.0')} ${r69Select('cra-fm','实现支持FM',['0','1'],'1')} ${r69Select('cra-phase','接收窗口',[['normal','普通活动请求'],['flr-active','FLR执行期间'],['flr-done-disabled','FLR结束且未重新使能'],['reenabled','FLR后已重新使能']],'flr-active')} ${r69Select('cra-old','已知为复位前旧完成',['0','1'],'0')} ${r69Select('cra-match','活动Transaction ID匹配',['0','1'],'1')} ${r69Select('cra-mismatch','其它关联字段差异',[['none','无'],['ido-only','仅IDO bit2'],['byte-address','Memory Read仅Byte Count/Lower Address'],['other','其它关联字段']],'none')} ${r69Select('cra-kind','请求种类',[['memread','普通Memory Read'],['config','Configuration']],'memread')} ${r69Select('cra-status','Completion Status',['SC','UR','CA','RRS','Reserved'],'SC')} ${r69Select('cra-data','全部所需读数据已收齐',['0','1'],'0')}<p id="cra-result" aria-live="polite">${esc(completionArrivalInfo('7.0','1','flr-active','0','1','none','memread','SC','0').message)}</p></div>`;}
function tagPartitionInfo(smallBits,n){
 if(!['5','8'].includes(smallBits)||typeof n!=='string'||!/^\d+$/.test(n))return {state:'invalid',message:'请输入5/8-bit小Tag类型和非负整数N。'};
 const N=Number(n),limit=smallBits==='5'?32:256;
 if(!Number.isSafeInteger(N)||N>limit)return {state:'invalid',message:`${smallBits}-bit小Tag池N须为0～${limit}。`};
 const largeCount=768-3*N,excluded=3*N,total=768-2*N,ranges=N===256?[]:[1,2,3].map(bank=>[bank*256+N,bank*256+255]);
 return {state:'partition',N,smallCount:N,largeCount,excluded,total,ranges,message:`Base7.0示例分区：小Tag ${N}个；10-bit有效Tag ${largeCount}个；三个大Tag bank排除${excluded}个；合计${total}个。小池低8位0～N−1从三个大池同时剔除。这只是规范讨论的一种实现方法，不是强制分配算法；计数不等于实际并发许可，不覆盖UIO或14-bit混合池。`};
}
function tagPartitionOutput(q){
 if(q.state!=='partition')return `<p>${esc(q.message)}</p>`;
 const hex=x=>'0x'+x.toString(16).toUpperCase().padStart(3,'0');
 return `<figure class="note"><figcaption><b>原创Tag低8位分区图：每个大池都避开相同低位</b></figcaption><p>${esc(q.message)}</p><div class="table-wrap"><table class="generation-table"><thead><tr><th>池 / Tag[9:8]</th><th>低8位0～255的分区</th><th>可用完整Tag范围</th></tr></thead><tbody>${[1,2,3].map((b,i)=>`<tr><th>${b.toString(2).padStart(2,'0')}</th><td><div style="display:flex;min-width:220px;border:1px solid #64748b"><span style="background:#f4b6b6;color:#171717;flex:${q.N};${q.N?'':'display:none'}" title="排除${q.N}个低位">排除 ${q.N}</span><span style="background:#b8ddcc;color:#171717;flex:${256-q.N};${q.N===256?'display:none':''}" title="保留${256-q.N}个">保留 ${256-q.N}</span></div></td><td>${q.ranges[i]?hex(q.ranges[i][0])+'～'+hex(q.ranges[i][1]):'无'}</td></tr>`).join('')}<tr><th>小Tag池 / 00</th><td>${q.N?'低8位0～'+(q.N-1):'不分配'}</td><td>${q.N?'0x000～'+hex(q.N-1):'无'}</td></tr></tbody></table></div><p>宽度按256个低位编号的比例绘制；数字是Tag编号数，不是packet bit图。协议错误路径可能截短Tag，分区避免本方法中的低8位别名，不能消除所有迟到完成风险。</p></figure>`;
}
function tagPartitionExplorer(){return `<div class="note"><h3>5/8-bit与10-bit Tag分区计算</h3>${r69Select('tap-bits','小Tag池位数',['5','8'],'5')} <label>小池数量N <input id="tap-n" type="number" min="0" max="256" step="1" value="16"></label><div id="tap-result" aria-live="polite">${tagPartitionOutput(tagPartitionInfo('5','16'))}</div></div>`;}
function r71LifecycleDiagram(){return `<figure class="note"><figcaption><b>原创请求生命周期示意：三条终止路径</b></figcaption><div style="display:flex;flex-wrap:wrap;gap:12px;align-items:center"><div class="note">发起普通NP请求<br>建立RID + Tag上下文</div><b>→</b><div class="note">Outstanding<br>部分SC数据 → 继续等待 ↺</div><b>→</b><div class="note">① 全部所需SC数据：成功结束<br>② UR / CA：错误结束<br>③ Completion Timeout：超时结束</div></div><p>内部上下文结束 ≠ 软件已同步 ≠ 所有旧包消失。FLR另有丢弃/等待规则；重新使能后旧Completion可能与新ID碰撞。此图是所列普通请求的教学流程，不是线上状态编码，不覆盖UIO。</p></figure>`;}
function r71Refresh(e){const id=e.target?.id||'';if(id.startsWith('cra-')){const out=$('#cra-result');if(out)out.textContent=completionArrivalInfo(...['version','fm','phase','old','match','mismatch','kind','status','data'].map(x=>$('#cra-'+x).value)).message;}if(id.startsWith('tap-')){const out=$('#tap-result');if(out)out.innerHTML=tagPartitionOutput(tagPartitionInfo($('#tap-bits').value,$('#tap-n').value));}}
document.addEventListener('input',r71Refresh);document.addEventListener('change',r71Refresh);


// R72: selected poison and AER snapshot rules, read-only teaching tools.
function poisonReportInfo(version,role,severity,aer,ceMask,ueMask,corGate,ueGate,headerNeeded,space){
 if(!['6.0','7.0'].includes(version)||!['intermediate','ultimate-safe','ultimate-unsafe','protected','egress'].includes(role)||!['nonfatal','fatal'].includes(severity)||![aer,ceMask,ueMask,corGate,ueGate,headerNeeded,space].every(x=>['0','1'].includes(x)))return {state:'invalid',message:'输入无效：请选择所列版本、Poison角色、严重度与0/1条件。'};
 const advisory=severity==='nonfatal'&&['intermediate','ultimate-safe'].includes(role);let ce=false,ue=false,log=false,messageType='none',reason='',state='uncorrectable';
 if(advisory){state='advisory';if(aer==='0'){reason='无AER的本ANFE场景不发错误Message，不按普通Non-Fatal替代上报。';}
 else {ce=true;if(ceMask==='1'){state='advisory-ce-masked';reason='先置CE[13]，CE Mask[13]=1即停止；不继续置对应UE、记Header或发ERR_COR。';}
 else {ue=true;log=ueMask==='0'&&headerNeeded==='1'&&space==='1';messageType=corGate==='1'?'ERR_COR':'none';reason='CE Mask[13]=0后置对应UE；UE Mask只在此ANFE分支决定Header记录资格，ERR_COR按Correctable报告使能。';}}}
 else {ue=aer==='1';const blocked=aer==='1'&&ueMask==='1';log=aer==='1'&&!blocked&&headerNeeded==='1'&&space==='1';messageType=!blocked&&ueGate==='1'?(severity==='fatal'?'ERR_FATAL':'ERR_NONFATAL'):'none';reason=(role==='protected'?'受保护控制目标的Poison保持Uncorrectable，禁止目标修改；':'')+(role==='egress'?'出口阻断不是中间Receiver ANFE；不发送TLP。':'')+(severity==='fatal'?'有效严重度Fatal，不走ANFE。':role==='protected'?'即使Severity为Non-Fatal也不能改成ANFE。':'最终接收者不能安全继续操作，不按ANFE消化。');if(role==='egress'&&severity==='nonfatal')reason='出口阻断不是中间Receiver ANFE；不发送TLP，按一般UE路径处理。';if(aer==='0')reason+=' 无AER时不显示AER寄存器记录，但适用基线报告门控仍需考虑。';}
 if(aer==='1'&&headerNeeded==='1'&&!log&&!(advisory&&ceMask==='1'))reason+=ueMask==='1'?' 对应UE屏蔽，不记录新Header。':' 没有可用记录资源，不记录本次Header；Status不是完整事件计数。';
 return {state,advisory,ceStatus:ce,ueStatus:ue,headerRecorded:log,messageType,message:`Base${version} · ${role} · ${severity}：${reason} AER CE[13]本事件${ce?'置位':'不由本分支新增'}；对应UE本事件${ue?'置位':'不由本分支新增'}；新Header${log?'满足所列记录条件':'不记录'}；消息${messageType==='none'?'无':messageType}。这里只描述本次事件，不清除旧Status/Header。前提：Poison已检测、无更高优先级错误、DPC不触发；消息门控已综合适用Command/Device Control，角色安全性由使用者确认。不推断Root中断或数据已修复。`};
}
function poisonReportExplorer(){return `<div class="note"><h3>Poison角色与报告路径</h3>${r69Select('por-version','Base',['6.0','7.0'],'7.0')} ${r69Select('por-role','检测角色',[['intermediate','中间Receiver'],['ultimate-safe','最终：安全保留/处理Poison'],['ultimate-unsafe','最终：无法安全继续'],['protected','最终：禁止修改的控制目标'],['egress','Poisoned TLP出口阻断']],'intermediate')} ${r69Select('por-severity','有效严重度',[['nonfatal','Non-Fatal'],['fatal','Fatal']],'nonfatal')} ${r69Select('por-aer','实现AER',['0','1'],'1')} ${r69Select('por-cemask','CE Mask[13]',['0','1'],'1')} ${r69Select('por-uemask','对应UE Mask',['0','1'],'0')} ${r69Select('por-cor','Correctable报告使能',['0','1'],'1')} ${r69Select('por-ue','所选UE级别报告门控通过',['0','1'],'1')} ${r69Select('por-header','本事件需要记Header',['0','1'],'1')} ${r69Select('por-space','当前有可用记录资源',['0','1'],'1')}<p id="por-result" aria-live="polite">${esc(poisonReportInfo('7.0','intermediate','nonfatal','1','1','0','1','1','1','1').message)}</p><p>只显示AER本事件新增记录，既有状态不会被本查询清除。资源可用须已考虑多Header使能、FEP和实际容量；无AER时严重度指有效基线分类，不能假设有可编程Severity寄存器。</p></div>`;}
function aerHeaderInfo(version,fmSupported,prefixSupported,ueHex,advHex,dwHex,sharedOverflow){
 const hexOK=x=>typeof x==='string'&&/^(?:0x)?[0-9a-f]{1,8}$/i.test(x.trim());
 if(!['6.0','7.0'].includes(version)||![fmSupported,prefixSupported,sharedOverflow].every(x=>['0','1'].includes(x))||![ueHex,advHex,dwHex].every(hexOK))return {state:'invalid',message:'输入无效：请选择所列条件，UE/Control/DW输入1～8位十六进制寄存器数值。'};
 const val=x=>parseInt(x.trim().replace(/^0x/i,''),16),ue=val(ueHex),adv=val(advHex),dw=val(dwHex),fep=adv&31,defined=AER_UE_BITS.some(x=>x[0]===fep),valid=defined&&((ue>>>fep)&1)===1,multiCap=(adv>>>9)&1,multiEnable=(adv>>>10)&1,prefix=(adv>>>11)&1,rawCapacity=(adv>>>13)&31,loggedFM=(adv>>>18)&1,loggedSize=(adv>>>19)&31,supports=fmSupported==='1',capacity=rawCapacity||(!supports?(prefixSupported==='1'?8:4):0),mode=!supports?'NFM':valid?(loggedFM?'FM':'NFM'):'unknown',bytes=[24,16,8,0].map(n=>(dw>>>n)&255),issues=[];
 if(multiEnable&&!multiCap)issues.push('MHR Enable=1但Capable=0，不能据此认定支持多Header。');
 if(!supports&&prefixSupported==='1'&&rawCapacity>0&&rawCapacity<8)issues.push('不支持FM且支持End-End Prefix时，非零容量不得小于8DW。');
 if(supports&&capacity===0)issues.push('FM支持下不能套用NFM零值4/8DW兼容解释；需核实现容量。');
 if(valid&&supports&&loggedSize>capacity&&capacity>0)issues.push('本次Logged TLP Size超过实现容量，快照/配置存在矛盾。');
 if(valid&&supports&&loggedFM&&prefix)issues.push('FM记录时Prefix Log Present必须0；重叠区域用于FM Header，不是NFM Prefix。');
 if(valid&&prefix&&prefixSupported==='0')issues.push('不支持End-End Prefix，不能把Present位当有效Prefix日志。');
 if(sharedOverflow==='1'){if(multiCap)issues.push('已确认共享VF日志时MHR Capable必须0。');if(dw!==0xffffffff)issues.push('已确认共享VF溢出时Header Log应返回全1，所输DW不符。');if(supports&&loggedSize!==0)issues.push('已确认共享VF溢出且支持FM，Logged TLP Size必须0。');if(prefix)issues.push('已确认共享VF溢出时Prefix Present必须0。');}
 const state=issues.length?'inconsistent':sharedOverflow==='1'?'shared-overflow':!valid?'invalid-fep':'snapshot';
 const btext=bytes.map(x=>x.toString(16).padStart(2,'0').toUpperCase()).join(' '),detail=sharedOverflow==='1'?'已确认共享VF溢出：全1为无Header哨兵，不作为TLP解码。':valid?'FEP定义有效，但仍须确认记录历史/Mask及采样一致性，不证明本次有新包头。':'FEP未指向已置的定义UE位：日志不按当前有效记录解释。';
 return {state,fep,defined,valid,multiCap,multiEnable,prefix,rawCapacity,capacity,loggedSize,mode,bytes,issues,message:`Base${version} · ${state}：FEP=${fep}（${defined?'已定义UE位':'未定义位'}），${valid?'定义有效':'无效'}；MHR C/E=${multiCap}/${multiEnable}；容量${capacity||'待核'}DW；捕获模式${mode}；本次记录长度${supports&&valid?loggedSize+'DW':'此条件下不解释'}。${detail} ${issues.join(' ')} 所输日志DW按Header顺序为 ${btext}（仅在它确属有效Header时解释；按DW寄存器数值拆分，不是主存小端byte流）。工具不解析完整TLP，不证明快照原子或错误已恢复。`};
}
